const durationStatistic = /^\d+(?:\.\d+)?±\d+(?:\.\d+)?(?:ms|s)(?:\s*\(\d+(?:\.\d+)?%\))?$/u

function endsWithScriptBase(text: string): boolean {
  const tail = text.slice(-2),
    code = tail.codePointAt(0)
  // Some renderer V8 versions reject astral letters in the combined Unicode
  // class below. Classify this alphabet through its single BMP compatibility
  // character only; keep source spelling, offsets and native geometry intact.
  if (code !== undefined && code >= 0x1d400 && code <= 0x1d7ff) {
    const letter = tail.normalize('NFKC')
    return letter.length === 1 && /^[\p{L}\p{N}]$/u.test(letter)
  }
  return /[\p{L}\p{N})\]]$/u.test(text)
}

// Heuristic source grouping, promoted from the verified paragraph-flow spike.
// English boundary rules are candidates, not semantic or translation-quality certification.
export type PdfLayoutTextItem = {
  str: string
  width: number
  height: number
  dir: string
  transform: number[]
  hasEOL?: boolean
  fontName?: string
  fontFamily?: string
  fontAscent?: number
  fontDescent?: number
  fontVertical?: boolean
}
export type PdfLayoutPage = {
  nativeAppendixOverview?: NativeAppendixOverview
  nativeOutlineRestart?: NativeOutlineRestart
  nativeOnlineAppendixRestart?: NativeOutlineRestart
  nativeContentsReference?: NativeOutlineRestart
  nativeCommandAdvances?: Record<string, number>
  nativeTableNoteEvidence?: NativeReferenceEvidence
  nativeReferenceEvidence?: NativeReferenceEvidence
  nativeDisplayMathEvidence?: NativeReferenceEvidence
  nativeDerivativeRuleEvidence?: NativeReferenceEvidence
  nativeNumberedPacketEvidence?: NativeReferenceEvidence
  nativeCompactAlgorithmEvidence?: NativeReferenceEvidence
  nativeFolioFontEvidence?: NativeSectionFontEvidence
  nativeSectionFontEvidence?: NativeSectionFontEvidence
  page: number
  width: number
  height: number
  rotation: number
  items: PdfLayoutTextItem[]
}
type Rect = { x: number; y: number; right: number; bottom: number }
type Item = PdfLayoutTextItem &
  Rect & {
    index: number
    nativeLine: number
    key: string
    page: number
    font: number
    baseline: number
    originalBaseline: number
    dropCapNext?: number
    dropCapMarginReturn?: true
    unsupported: boolean
  }
type Line = Rect & { font: number; baseline: number; text: string; items: Item[] }
type Block = Rect & {
  sourceOnly?: true
  font: number
  lines: Line[]
  source: string
  items: Item[]
  risks: string[]
  readingBaseline?: number
}
type LayoutBlock = {
  dehyphenateKeywordTail?: true
  nativeProse?: true
  sourceOnly?: true
  preserve?: 'formula' | 'code' | 'literal' | 'reference'
  tableCell?: true
  id: string
  page: number
  source: string
  items: string[]
  originalStrings: string[]
  rect: Rect & { font: number }
  lines: (Rect & { text: string; items: string[] })[]
  risks: string[]
}
type LayoutPage = {
  page: number
  width: number
  height: number
  sourceItems: number
  blocks: LayoutBlock[]
}
type LayoutUnit = {
  figure?: true
  id: string
  kind: 'prose-candidate' | 'heading-candidate' | 'other'
  referenceBoundary?: true
  source: string
  sourceOnly?: true
  preserve?: 'formula' | 'code' | 'literal' | 'reference'
  items: string[]
  originalStrings: string[]
  fragments: { id: string; page: number; rect: Rect & { font: number } }[]
  risks: string[]
}
export type PdfTranslationLayout = {
  bodyFont: number
  pages: LayoutPage[]
  units: LayoutUnit[]
  joins: { from: string; to: string; kind: 'page' | 'column'; left: string; right: string }[]
}

// Same conservative source policy as joinCaptionLines in the Node caption pipeline.
// Keep this browser entry independent of its Node imports and unrelated caption heuristics.
function joinCaptionLines(lines: string[], pageWords: ReadonlySet<string>): string {
  return lines.reduce((text, line) => {
    const next = line.trim()
    if (!next) return text
    if (text.endsWith('\u00ad')) return text.slice(0, -1) + next
    const prefix = /(\p{L}+)-$/u.exec(text)?.[1]
    const suffix = /^(\p{Ll}+)/u.exec(next)?.[1]
    if (
      prefix &&
      suffix &&
      pageWords?.has((prefix + suffix).toLowerCase()) &&
      !pageWords.has((prefix + '-' + suffix).toLowerCase())
    )
      return text.slice(0, -1) + next
    return text + (text && !/[-\u2010\u2011]$/.test(text) ? ' ' : '') + next
  }, '')
}

const median = (values: number[]): number =>
  [...values].sort((a, b) => a - b)[Math.floor(values.length / 2)] ?? 9
const bounds = (items: Rect[]): Rect => ({
  x: Math.min(...items.map((i) => i.x)),
  y: Math.min(...items.map((i) => i.y)),
  right: Math.max(...items.map((i) => i.right)),
  bottom: Math.max(...items.map((i) => i.bottom))
})
function joinLines(left: string, right: string): string {
  if (!left) return right
  if (/[A-Za-z]-$/.test(left) && /^[a-z]/.test(right)) {
    // Match the complete English prefix at the hyphen.
    const keepHyphen = /(?:^|[^A-Za-z])(?:non|pre|post|well|self)-$/i.test(left)
    return (keepHyphen ? left : left.slice(0, -1)) + right
  }
  return left + ' ' + right
}

function isContractIdentifierWrap(lead: string, tail: string): boolean {
  const prefix =
      /\b(?:under|through) (?:a |the )?contract with (?:the )?(?:[A-Z][a-z]+ (?:and )?){2,}([A-Z][a-z]{3,})-$/u.exec(
        lead
      )?.[1],
    suffix = /^([a-z]{3,}) \((?=[A-Z0-9-]*[A-Z])(?=[A-Z0-9-]*\d)[A-Z0-9][A-Z0-9-]{7,24}\)\.$/u.exec(
      tail
    )?.[1]
  return (
    !!prefix &&
    !!suffix &&
    /^(?:administration|authority|committee|commission|department|foundation|institution)$/iu.test(
      prefix + suffix
    )
  )
}

function endsWithCitationAuthor(text: string): boolean {
  if (!text.endsWith(',')) return false
  const last = text.length - 2
  for (let index = last; index >= 0; index--) {
    const character = text[index]
    if (!/[A-Za-z\s.,'’-]/u.test(character)) return false
    if (index < last && /[A-Za-z]/u.test(character)) return true
  }
  return false
}

function lineOf(items: Item[]): Line {
  const font = Math.max(...items.map((i) => i.font))
  items.sort((a, b) => a.x - b.x || a.index - b.index)
  for (let first = 0; first < items.length; first++) {
    if (items[first].font >= font * 0.85) continue
    let end = first + 1
    let right = items[first].right
    while (
      end < items.length &&
      items[end].font < font * 0.85 &&
      items[end].x <= right + font * 0.15
    ) {
      right = Math.max(right, items[end].right)
      end++
    }
    const cluster = items.slice(first, end)
    if (
      Math.max(...cluster.map((part) => part.originalBaseline)) -
        Math.min(...cluster.map((part) => part.originalBaseline)) >
      font * 0.15
    )
      items.splice(first, cluster.length, ...cluster.sort((a, b) => a.index - b.index))
    first = end - 1
  }
  // A spacing accent may precede its native base despite a larger x coordinate.
  // Preserve proven native order, including a same-font grave over a word vowel.
  for (const mark of [...items]) {
    if (mark.str !== 'ˆ' && mark.str !== '`') continue
    const bases = items.filter(
      (base) =>
        base.index === mark.index + 1 &&
        (mark.str === 'ˆ'
          ? /^[A-Za-z\p{Script=Greek}\d]$/u.test(base.str)
          : /^[AEIOUaeiou][a-z]{1,}\b/u.test(base.str)) &&
        mark.fontName &&
        base.fontName &&
        Math.abs(mark.font - base.font) < font * 0.05 &&
        Math.abs(mark.x - base.x) < font * 0.15 &&
        (mark.str === 'ˆ'
          ? base.originalBaseline - mark.originalBaseline > font * 0.15 &&
            base.originalBaseline - mark.originalBaseline < font * 0.35
          : mark.fontName === base.fontName &&
            Math.abs(base.originalBaseline - mark.originalBaseline) < font * 0.1 &&
            mark.x >= base.x &&
            mark.x - base.x < font * 0.1 &&
            mark.width < font * 0.45) &&
        mark.width > 0 &&
        mark.width <= base.width &&
        !mark.unsupported &&
        !base.unsupported &&
        Math.abs(mark.transform[2]) < 0.001 &&
        Math.abs(base.transform[2]) < 0.001
    )
    if (bases.length !== 1 || items.indexOf(mark) < items.indexOf(bases[0])) continue
    items.splice(items.indexOf(mark), 1)
    items.splice(items.indexOf(bases[0]), 0, mark)
  }
  const accents = new Map<Item, Item>()
  for (const mark of items.filter((item) => /^\p{M}$/u.test(item.str) || item.str === '¨')) {
    const bases = items.filter(
      (base) =>
        /^\p{L}/u.test(base.str) &&
        Math.abs(base.x - mark.x) < font * 0.15 &&
        Math.abs(base.baseline - mark.baseline) < font * 0.1 &&
        Math.abs(base.font - mark.font) < font * 0.1 &&
        (mark.str !== '¨' ||
          (/^[AEIOUYaeiouy]/u.test(base.str) &&
            base.index === mark.index + 1 &&
            base.fontName &&
            base.fontName === mark.fontName &&
            mark.width < font * 0.45 &&
            mark.x >= base.x &&
            mark.x - base.x < font * 0.1))
    )
    if (bases.length === 1) accents.set(mark, bases[0])
  }
  // A same-font spacing acute may be printed between two runs of a cover name.
  // Its synthetic trailing space overlaps the carrier by the accent's offset.
  const joinedPrefixes = new Set<Item>()
  for (const mark of items) {
    if (mark.page !== 1 || mark.str !== '´') continue
    const prefix = items.find((run) => run.index === mark.index - 1)
    const base = items.find((run) => run.index === mark.index + 1)
    if (
      !prefix ||
      !base ||
      ![prefix, mark, base].every(
        (run) =>
          nativeHorizontalSourceItem(run) &&
          !run.unsupported &&
          run.fontName === mark.fontName &&
          Math.abs(run.font - mark.font) < font * 0.02
      ) ||
      !/^[A-Z]{2,}(?: [A-Z]{2,}){2,8} $/u.test(prefix.str) ||
      !/^[AEIOU][A-Z]{2,}(?: [A-Z]{2,}){1,6}$/u.test(base.str) ||
      prefix.hasEOL ||
      mark.hasEOL ||
      Math.abs(prefix.originalBaseline - base.originalBaseline) > font * 0.02 ||
      base.originalBaseline - mark.originalBaseline < font * 0.2 ||
      base.originalBaseline - mark.originalBaseline > font * 0.3 ||
      Math.abs(mark.x - prefix.right) > font * 0.04 ||
      mark.x - base.x < font * 0.1 ||
      mark.x - base.x > font * 0.18 ||
      Math.abs(mark.width - font * 0.5) > font * 0.05
    )
      continue
    accents.set(mark, base)
    joinedPrefixes.add(prefix)
  }
  const fractions = resolveInlineFractions(
    items.map((item) => ({
      i: item.index,
      text: item.str,
      fontSize: item.font,
      baseline: -item.originalBaseline,
      bounds: [item.x, -item.bottom, item.right, -item.y]
    })),
    -median(items.filter((item) => item.font >= font * 0.9).map((item) => item.baseline)),
    font
  )
  // Negative powers may be emitted as separate minus and digit glyphs. Require
  // both glyphs to share a raised baseline beside the actual base ten.
  const negativeExponentItems = new Set<Item>()
  for (let n = 1; n < items.length; n++) {
    const sign = items[n]
    const base = items[n - 1]
    if (!/(?:^|[^0-9])10$/u.test(base.str) || !/^[−-](?:\d{1,2})?$/u.test(sign.str)) continue
    const digits = sign.str.length === 1 ? items[n + 1] : sign
    if (
      !digits ||
      (digits !== sign && !/^\d{1,2}$/u.test(digits.str)) ||
      sign.font >= base.font * 0.9 ||
      digits.font >= base.font * 0.9 ||
      base.originalBaseline - sign.originalBaseline <= base.font * 0.2 ||
      Math.abs(digits.originalBaseline - sign.originalBaseline) > base.font * 0.1 ||
      sign.x - base.right < -base.font * 0.1 ||
      sign.x - base.right > base.font * 0.4 ||
      (digits !== sign &&
        (digits.x - sign.right < -base.font * 0.1 || digits.x - sign.right > base.font * 0.3))
    )
      continue
    negativeExponentItems.add(sign)
    negativeExponentItems.add(digits)
  }
  let previousNonAccent: Item | undefined
  const text = items
    .map((item, n) => {
      const prev = previousNonAccent
      if (!accents.has(item)) previousNonAccent = item
      if (accents.has(item)) return ''
      const fraction = fractions.find((value) => value.indices.includes(item.index))
      if (fraction) {
        const first = items.find((value) => fraction.indices.includes(value.index))
        return item === first ? ' ' + fraction.label : ''
      }
      // Preserve an unambiguous power of ten from its actual raised glyphs.
      // Flattening 6 × 10⁶ to 6 × 106 changes the quantity sent to the model.
      const exponent =
        negativeExponentItems.has(item) ||
        (prev &&
          /^\d{1,2}$/u.test(item.str) &&
          item.font < prev.font * 0.9 &&
          prev.baseline - item.baseline > prev.font * 0.2 &&
          item.x - prev.right < prev.font * 0.4 &&
          /\d\s*[×·]\s*10\s*$/u.test(
            items
              .slice(0, n)
              .map((part) => part.str)
              .join('')
          )) ||
        // A comparative bound can use a bare power without a coefficient.
        (prev &&
          /\b(?:greater|less) than 10$/u.test(prev.str) &&
          /^\d{1,2}$/u.test(item.str) &&
          items[n + 1] &&
          /^(?:in|at|for|under|over|within) /u.test(items[n + 1].str) &&
          prev.nativeLine === item.nativeLine &&
          prev.nativeLine === items[n + 1].nativeLine &&
          prev.index + 1 === item.index &&
          !prev.hasEOL &&
          !item.hasEOL &&
          item.font >= prev.font * 0.6 &&
          item.font < prev.font * 0.85 &&
          prev.originalBaseline - item.originalBaseline > prev.font * 0.25 &&
          prev.originalBaseline - item.originalBaseline < prev.font * 0.45 &&
          Math.abs(item.x - prev.right) < prev.font * 0.1)
      // A raised footnote after a completed body sentence is a separate
      // token. Flattening "Table 6." plus its marker to "6.3" fabricates a
      // decimal/reference identity and prevents safe link relocation.
      const following = items[n + 1]
      const sentenceFootnote =
        prev &&
        /^\d{1,2}$/u.test(item.str) &&
        /\.$/u.test(prev.str) &&
        (prev.str.match(/\p{L}{2,}/gu)?.length ?? 0) >= 4 &&
        prev.fontName &&
        ((item === items.at(-1) && prev.fontName === item.fontName) ||
          (following &&
            following.index > item.index &&
            following.index <= item.index + 2 &&
            following.fontName === prev.fontName &&
            Math.abs(following.font - prev.font) < prev.font * 0.03 &&
            Math.abs(following.originalBaseline - prev.originalBaseline) < prev.font * 0.03 &&
            following.x - item.right > prev.font * 0.25 &&
            following.x - item.right < prev.font * 0.75 &&
            /^[A-Z][a-z]{3,} [A-Z\p{Ll}]/u.test(following.str) &&
            /\b(?:January|February|March|April|May|June|July|August|September|October|November|December) (?:19|20)\d{2}\.$/u.test(
              prev.str
            ))) &&
        item.font >= prev.font * 0.5 &&
        item.font < prev.font * 0.85 &&
        prev.originalBaseline - item.originalBaseline > prev.font * 0.2 &&
        prev.originalBaseline - item.originalBaseline < prev.font * 0.55 &&
        item.x - prev.right >= -prev.font * 0.1 &&
        item.x - prev.right < prev.font * 0.4
      const value = exponent
        ? item.str.replace(/[−-]/gu, '⁻').replace(/\d/gu, (digit) => '⁰¹²³⁴⁵⁶⁷⁸⁹'[Number(digit)])
        : (joinedPrefixes.has(item) ? item.str.trimEnd() : item.str).replace(
            /^\p{L}/u,
            (letter) => {
              const marks = [...accents].filter(([, base]) => base === item)
              const composed =
                letter +
                marks
                  .map(([mark]) =>
                    mark.str === '¨' ? '\u0308' : mark.str === '´' ? '\u0301' : mark.str
                  )
                  .join('')
              return marks.some(([mark]) => mark.str === '¨' || mark.str === '´')
                ? composed.normalize('NFC')
                : composed
            }
          )
      return (
        (!exponent &&
        prev &&
        prev.dropCapNext !== item.index &&
        (sentenceFootnote || item.x - prev.right > font * 0.1) &&
        !/\s$/.test(prev.str) &&
        !/^\s/.test(item.str)
          ? ' '
          : '') + value
      )
    })
    .join('')
    .trim()
  return {
    ...bounds(items),
    font,
    baseline: median(items.filter((i) => i.font >= font * 0.9).map((i) => i.baseline)),
    text,
    items
  }
}
function gaps(blocks: Rect[], axis: 'x' | 'y'): { start: number; end: number; size: number }[] {
  const end = axis === 'x' ? 'right' : 'bottom'
  const spans = blocks.map((b) => [b[axis], b[end]]).sort((a, b) => a[0] - b[0])
  let right = spans[0][1]
  const result = []
  for (const [start, stop] of spans.slice(1)) {
    if (start > right) result.push({ start: right, end: start, size: start - right })
    right = Math.max(right, stop)
  }
  return result
}

// Reading order uses complete native lanes, never crop ownership or text suppression.
const orderedNativeRange = (blocks: Block[]): [number, number] => [
  Math.min(...blocks.flatMap((b) => b.items.map((i) => i.index))),
  Math.max(...blocks.flatMap((b) => b.items.map((i) => i.index)))
]
const horizontalNativeBlock = (block: Block): boolean =>
  block.items.length > 0 &&
  block.items.every(
    (item) =>
      !item.unsupported &&
      item.dir === 'ltr' &&
      !!item.fontName &&
      item.fontVertical === false &&
      Number.isFinite(item.fontAscent) &&
      Number.isFinite(item.fontDescent) &&
      item.fontAscent! > 0 &&
      item.fontDescent! <= 0 &&
      item.fontAscent! > item.fontDescent! &&
      item.transform.length === 6 &&
      item.transform.every(Number.isFinite) &&
      item.transform[0] > 0 &&
      item.transform[3] > 0 &&
      item.transform[1] === 0 &&
      item.transform[2] === 0
  )

function leadingNativeCaptionColumns(blocks: Block[], pageBlocks: Block[]): Block[] | undefined {
  for (const caption of blocks.filter(
    (b) => captionLabel.test(b.source) && horizontalNativeBlock(b)
  )) {
    const above = blocks.filter((b) => b.bottom <= caption.bottom + 0.001)
    const below = blocks.filter((b) => b.y > caption.bottom + 0.001)
    if (
      above.length + below.length !== blocks.length ||
      below.length < 4 ||
      Math.max(...above.map((b) => b.bottom)) !== caption.bottom ||
      orderedNativeRange(above)[1] >= orderedNativeRange(below)[0]
    )
      continue
    const font = median(below.map((b) => b.font))
    const gutters = gaps(below, 'x').filter((g) => g.size > font * 0.9)
    if (gutters.length !== 1) continue
    const gutter = gutters[0]
    const lanes = [
      below.filter((b) => b.right <= gutter.start + 0.001),
      below.filter((b) => b.x >= gutter.end - 0.001)
    ]
    if (
      lanes.flat().length !== below.length ||
      !below.every(horizontalNativeBlock) ||
      !lanes.every(
        (lane) =>
          lane.filter(
            (b) => b.lines.length >= 2 && wordCount(b.source) >= 12 && !symbolicExpression(b.source)
          ).length >= 2
      ) ||
      orderedNativeRange(lanes[0])[1] >= orderedNativeRange(lanes[1])[0] ||
      caption.x > Math.min(...lanes[0].map((b) => b.x)) + font ||
      caption.right < Math.max(...lanes[1].map((b) => b.right)) - font
    )
      continue
    return [...readingOrder(above, pageBlocks), ...readingOrder(below, pageBlocks)]
  }
}

function nativeThreePanelDescriptions(blocks: Block[], pageBlocks: Block[]): Block[] | undefined {
  if (blocks.length !== 6 || !blocks.every(horizontalNativeBlock)) return
  const markers = blocks.filter((b) => /^\([a-c]\)$/u.test(b.source)).sort((a, b) => a.x - b.x)
  if (markers.length !== 3 || markers.some((b, i) => b.source !== '(' + 'abc'[i] + ')')) return
  const lanes: Block[][] = []
  for (const marker of markers) {
    const bodies = blocks.filter(
      (b) =>
        !markers.includes(b) &&
        b.lines.length >= 2 &&
        wordCount(b.source) >= 12 &&
        !symbolicExpression(b.source) &&
        Math.abs(b.lines[0].baseline - marker.lines[0].baseline) <= 0.001 &&
        b.lines[0].x >= marker.right &&
        b.lines[0].x - marker.right < marker.font &&
        Math.abs(b.x - marker.x) < marker.font * 0.1 &&
        Math.abs(b.font - marker.font) < marker.font * 0.05 &&
        orderedNativeRange([marker])[1] < orderedNativeRange([b])[0]
    )
    if (bodies.length !== 1) return
    lanes.push([marker, bodies[0]])
  }
  if (
    new Set(lanes.flat()).size !== blocks.length ||
    lanes.some(
      (lane, i) =>
        i > 0 &&
        (Math.min(...lane.map((b) => b.x)) - Math.max(...lanes[i - 1].map((b) => b.right)) <
          lane[0].font * 0.5 ||
          orderedNativeRange(lanes[i - 1])[1] >= orderedNativeRange(lane)[0])
    )
  )
    return
  const [first, last] = orderedNativeRange(blocks)
  if (
    pageBlocks.some(
      (b) => !blocks.includes(b) && b.items.some((i) => i.index >= first && i.index <= last)
    )
  )
    return
  return lanes.flat()
}

function readingOrder(blocks: Block[], pageBlocks = blocks): Block[] {
  if (blocks.length < 2) return [...blocks]
  const font = median(blocks.map((b) => b.font))
  // Column gutters can be slightly narrower than one font em.
  let x = gaps(blocks, 'x')
    .filter((g) => g.size > font * 0.9)
    .sort((a, b) => b.size - a.size)[0]
  const y = gaps(blocks, 'y')
    .filter((g) => g.size > font * 0.35)
    .sort((a, b) => b.size - a.size)[0]
  // Two displayed equations can leave a vertical gap beside their short
  // introductions. A complete neighboring prose frame and the alternating
  // native stream prove one column, rather than two independent text lanes.
  if (x && blocks.length <= 4) {
    const pageOrder = [...pageBlocks].sort((a, b) => a.y - b.y)
    for (let offset = 0; offset + 3 < pageOrder.length; offset++) {
      const ordered = pageOrder.slice(offset, offset + 4)
      if (!blocks.every((block) => ordered.includes(block))) continue
      const sequenceGap = gaps(ordered, 'x').find((gap) => gap.size > font * 0.9)
      if (!sequenceGap) continue
      const first = Math.min(...ordered[0].items.map((item) => item.index))
      const last = Math.max(...ordered.at(-1)!.items.map((item) => item.index))
      if (
        ordered.every(
          (block, index) =>
            block.items.every((item) => !item.unsupported && !!item.fontName) &&
            (index % 2 === 0
              ? wordCount(block.source) >= 2 &&
                !terminal(block.source) &&
                !symbolicExpression(block.source) &&
                block.right <= sequenceGap.start + 0.001
              : symbolicExpression(block.source) && block.x >= sequenceGap.end - 0.001) &&
            (index === 0 ||
              (block.y > ordered[index - 1].bottom &&
                block.y - ordered[index - 1].bottom < font * 5 &&
                Math.min(...block.items.map((item) => item.index)) >
                  Math.max(...ordered[index - 1].items.map((item) => item.index))))
        ) &&
        !pageBlocks.some(
          (block) =>
            !ordered.includes(block) &&
            block.items.some((item) => item.index >= first && item.index <= last)
        ) &&
        pageBlocks.some(
          (block) =>
            !ordered.includes(block) &&
            wordCount(block.source) >= 12 &&
            !symbolicExpression(block.source) &&
            block.x <= ordered[0].x + font * 0.2 &&
            block.right > Math.max(...ordered.map((part) => part.right)) + font * 2 &&
            ((block.bottom < ordered[0].y && ordered[0].y - block.bottom < font * 6) ||
              (block.y > ordered.at(-1)!.bottom && block.y - ordered.at(-1)!.bottom < font * 6))
        )
      )
        return ordered.filter((block) => blocks.includes(block))
    }
  }
  // A pair of centered author/affiliation stacks belongs above the body
  // columns. Require the complete native band, paired rows and terminal email
  // lines; a title or a few short blocks alone cannot override a column cut.
  if (x)
    for (const gap of gaps(blocks, 'y').filter((gap) => gap.size > font * 0.5)) {
      const above = blocks.filter((block) => block.bottom <= gap.start + 0.001)
      const below = blocks.filter((block) => block.y >= gap.end - 0.001)
      const lanes = [
        above.filter((b) => b.right <= x!.start + 0.001),
        above.filter((b) => b.x >= x!.end - 0.001)
      ].map((lane) => lane.sort((a, b) => a.y - b.y))
      if (
        above.length + below.length !== blocks.length ||
        lanes[0].length !== lanes[1].length ||
        lanes[0].length < 3 ||
        lanes[0].length > 6 ||
        lanes.flat().length !== above.length ||
        Math.max(...above.flatMap((b) => b.items.map((i) => i.index))) >=
          Math.min(...below.flatMap((b) => b.items.map((i) => i.index)))
      )
        continue
      if (
        lanes.every((lane) => {
          const center = (lane[0].x + lane[0].right) / 2
          return (
            standaloneContactLine.test(lane.at(-1)!.source) &&
            lane[0].font > lane[1].font * 1.05 &&
            lane.every(
              (b, index) =>
                b.lines.length === 1 &&
                !b.risks.length &&
                b.items.every((i) => !i.unsupported && !!i.fontName) &&
                Math.abs((b.x + b.right) / 2 - center) < font * 0.5 &&
                (index === 0 ||
                  (b.y >= lane[index - 1].bottom - font * 0.1 &&
                    b.y - lane[index - 1].bottom < font * 1.5))
            )
          )
        }) &&
        lanes[0].every(
          (b, index) =>
            Math.abs(b.y - lanes[1][index].y) < font * 0.15 &&
            Math.abs(b.font - lanes[1][index].font) < font * 0.05 &&
            b.items[0].fontName === lanes[1][index].items[0].fontName
        ) &&
        [false, true].every((right) =>
          below.some(
            (b) =>
              (right ? b.x >= x!.end - 0.001 : b.right <= x!.start + 0.001) &&
              b.lines.length >= 2 &&
              wordCount(b.source) >= 12 &&
              !symbolicExpression(b.source)
          )
        )
      )
        return [...readingOrder(above, pageBlocks), ...readingOrder(below, pageBlocks)]
    }
  if (!x) {
    const columns = leadingNativeCaptionColumns(blocks, pageBlocks)
    if (columns) return columns
  }
  // Repeated prose frames can prove a gutter obscured by a short formula tail.
  // Require two disjoint native streams and validate every complete block;
  // a spanning title, interleaved source stream or larger overhang rejects it.
  if (!x) {
    const frames = blocks.filter(
      (block) =>
        wordCount(block.source) >= 12 &&
        block.right - block.x >= font * 8 &&
        block.lines.length >= 2 &&
        !symbolicExpression(block.source) &&
        !block.risks.length
    )
    const candidates =
      frames.length >= 4 ? gaps(frames, 'x').filter((gap) => gap.size > font * 0.9) : []
    if (candidates.length === 1) {
      const gutter = candidates[0]
      const left = frames.filter((block) => block.right <= gutter.start + 0.001)
      const right = frames.filter((block) => block.x >= gutter.end - 0.001)
      const lastLeft = Math.max(...left.flatMap((block) => block.items.map((item) => item.index)))
      const firstRight = Math.min(
        ...right.flatMap((block) => block.items.map((item) => item.index))
      )
      if (
        left.length >= 2 &&
        right.length >= 2 &&
        lastLeft < firstRight &&
        blocks.every((block) => {
          const first = Math.min(...block.items.map((item) => item.index))
          const last = Math.max(...block.items.map((item) => item.index))
          return last < firstRight
            ? block.x < gutter.start &&
                block.right <= gutter.end + font &&
                (block.right <= gutter.start + 0.001 || symbolicExpression(block.source))
            : first >= firstRight && block.x >= gutter.end - font * 0.05
        })
      )
        x = gutter
    }
  }
  // A full-width gap with complete native sections takes priority over columns.
  // Both sections must independently occupy both sides of the same gutter.
  const horizontalSection =
    x &&
    y &&
    y.size > font * 2 &&
    (() => {
      const above = blocks.filter((block) => block.bottom <= y.start + 0.001)
      const below = blocks.filter((block) => block.y >= y.end - 0.001)
      return (
        above.length + below.length === blocks.length &&
        [above, below].every(
          (section) =>
            section.some(
              (block) =>
                block.right <= x!.start + 0.001 &&
                block.lines.length >= 2 &&
                wordCount(block.source) >= 12 &&
                block.right - block.x >= font * 8 &&
                !symbolicExpression(block.source) &&
                !block.risks.length
            ) &&
            section.some(
              (block) =>
                block.x >= x!.end - 0.001 &&
                block.lines.length >= 2 &&
                wordCount(block.source) >= 12 &&
                block.right - block.x >= font * 8 &&
                !symbolicExpression(block.source) &&
                !block.risks.length
            )
        ) &&
        Math.max(...above.flatMap((block) => block.items.map((item) => item.index))) <
          Math.min(...below.flatMap((block) => block.items.map((item) => item.index)))
      )
    })()
  // Repeated complete native heading rows can end with short right labels.
  // A lane containing only those labels is not an independent body column.
  // Enclose each pair only for XY-cut, then return its unchanged text owners.
  if (x) {
    const right = blocks.filter((block) => block.x >= x!.end - 0.001),
      left = blocks.filter((block) => block.right <= x!.start + 0.001),
      inventory = pageBlocks.flatMap((block) => block.items),
      pairs = right.map((tag) => {
        const matches = left.filter(
          (head) =>
            head.lines.length === 1 &&
            head.items.length === 1 &&
            wordCount(head.source) >= 3 &&
            head.items[0].nativeLine === tag.items[0]?.nativeLine &&
            Math.abs(head.lines[0].baseline - tag.lines[0]?.baseline) < 0.001 &&
            head.items[0].index < tag.items[0].index
        )
        return { tag, head: matches.length === 1 ? matches[0] : undefined }
      })
    if (
      right.length >= 2 &&
      left.length + right.length === blocks.length &&
      pairs.every(({ tag, head }) => {
        if (!head || tag.lines.length !== 1 || tag.items.length !== 1) return false
        const first = head.items[0],
          last = tag.items[0]
        return (
          !head.risks.length &&
          !tag.risks.length &&
          /^[A-Z][A-Z0-9-]{1,15}$/u.test(tag.source) &&
          inventory.filter((item) => item.nativeLine === first.nativeLine).length === 2 &&
          [first, last].every(
            (item) =>
              !item.unsupported &&
              !!item.fontName &&
              item.width > 0 &&
              item.height > 0 &&
              item.transform.length === 6 &&
              [...item.transform, item.width, item.height].every(Number.isFinite) &&
              item.transform[0] > 0 &&
              item.transform[3] > 0 &&
              item.transform[1] === 0 &&
              item.transform[2] === 0 &&
              Math.abs(item.font - head.font) < head.font * 0.05
          ) &&
          pairs.every(
            (other) =>
              !!other.head &&
              other.head.items[0].fontName === first.fontName &&
              other.tag.items[0].fontName === last.fontName &&
              Math.abs(other.head.x - head.x) < head.font * 0.15 &&
              Math.abs(other.tag.right - tag.right) < head.font * 0.15
          ) &&
          left.some(
            (body) =>
              body !== head &&
              !body.risks.length &&
              wordCount(body.source) >= 10 &&
              !symbolicExpression(body.source) &&
              body.y > head.bottom &&
              body.y - head.bottom < head.font * 3 &&
              Math.abs(body.x - head.x) < head.font * 0.15 &&
              body.right - body.x > (tag.right - head.x) * 0.7 &&
              body.items.every((item) => item.index > last.index) &&
              !pairs.some(
                (other) =>
                  other.head &&
                  other.head !== head &&
                  other.head.y > head.y &&
                  other.head.y < body.y
              )
          )
        )
      })
    ) {
      const groups = new Map<Block, Block[]>()
      for (const { head, tag } of pairs) {
        const items = [...head!.items, ...tag.items]
        groups.set(
          { ...bounds(items), font: head!.font, source: '', items, lines: [], risks: [] },
          [head!, tag]
        )
      }
      const enclosed = new Set(pairs.flatMap(({ head, tag }) => [head!, tag]))
      return readingOrder(
        [...blocks.filter((block) => !enclosed.has(block)), ...groups.keys()],
        pageBlocks
      ).flatMap((block) => groups.get(block) ?? [block])
    }
  }
  // XY-cut: proved section boundaries first, otherwise full-height gutters.
  const cut = horizontalSection ? y : (x ?? y)
  if (!cut) {
    const panels = nativeThreePanelDescriptions(blocks, pageBlocks)
    if (panels) return panels
    // Inline formulas can extend above the prose baseline; wrapped text can
    // extend left of its opening line. Group only matching native baselines,
    // then order their actual opening positions without a pairwise tolerance sort.
    const anchor = (block: Block): Line | Item => {
      const first = block.lines[0] ?? block.items[0]
      return block.readingBaseline === undefined
        ? first
        : { ...first, baseline: block.readingBaseline }
    }
    const rows: { baseline: number; top: number; blocks: Block[] }[] = []
    for (const block of [...blocks].sort((a, b) => anchor(a).baseline - anchor(b).baseline)) {
      const row = rows.at(-1)
      if (row && Math.abs(row.baseline - anchor(block).baseline) <= 0.001) {
        row.blocks.push(block)
        row.top = Math.min(row.top, block.y)
      } else rows.push({ baseline: anchor(block).baseline, top: block.y, blocks: [block] })
    }
    return rows
      .sort((a, b) => a.top - b.top || a.baseline - b.baseline)
      .flatMap((row) => row.blocks.sort((a, b) => anchor(a).x - anchor(b).x))
  }
  const axis = x && !horizontalSection ? 'x' : 'y',
    point = (cut.start + cut.end) / 2
  return [
    ...readingOrder(
      blocks.filter((b) => b[axis] < point),
      pageBlocks
    ),
    ...readingOrder(
      blocks.filter((b) => b[axis] >= point),
      pageBlocks
    )
  ]
}
function undecodedGlyph(text: string): boolean {
  return text.length === 1 && text.charCodeAt(0) < 32 && !/\s/u.test(text)
}
function symbolicExpression(text: string): boolean {
  if (undecodedGlyph(text)) return true
  if (
    /·/u.test(text) &&
    /[A-Za-z\p{Script=Greek}]/u.test(text) &&
    /^[A-Za-z\p{Script=Greek}\d\s·]+$/u.test(text) &&
    !/[A-Za-z]{3,}/u.test(text)
  )
    return true
  // Tokenization examples are literal lists, sometimes flattened from several
  // output rows. Keep quoted tokens and their underscore boundary markers intact.
  const tokens = [...text.matchAll(/[‘’'"][A-Za-z_][A-Za-z_0-9]*[‘’'"]/gu)]
  if (
    tokens.length >= 2 &&
    /[[\]]/u.test(text) &&
    /^[\s,，[\]]*$/u.test(text.replace(/[‘’'"][A-Za-z_][A-Za-z_0-9]*[‘’'"]/gu, ''))
  )
    return true
  // Norm bars and Adobe extensible-bracket pieces have no translatable prose.
  if (/^[✓✗∣∥‖︷︸⏞⏟\uF8EB-\uF8FE\s]+$/u.test(text.trim())) return true
  // A prose citation lead-in is not a function with a square-bracket argument.
  if (/^(?:Following|See(?: also)?|As in|According to)\s*\[$/iu.test(text.trim())) return false
  if (/^[A-Z][A-Za-z-]{2,}\s+\[\d+(?:[ ,–-]\d+)*\]\s+(?:and|or)$/u.test(text.trim())) return false
  // A numeric comparison in a prose continuation is not a function call.
  if (/^[A-Za-z]{3,}\s+\(\d+(?:\.\d+)?\s+vs\.$/u.test(text.trim())) return false
  // Lowercase prose (including a word continued from the preceding line) can
  // introduce a parenthesized example/condition. It is not a named math function.
  if (
    /^[a-z]{3,}\s+\((?:(?:e\.g|i\.e|a\.k\.a)\.|[∼~]|[A-Za-z]\s*[<>≤≥=])/u.test(text.trim()) &&
    !/^(?:sin|cos|tan|log|ln|exp|min|max|det|relu|softmax|sigmoid|norm|var)\b/u.test(text.trim())
  )
    return false
  const content = text.replace(
    /\b(?:where|and|for|from|thus|hence|therefore|lim|max|min|log|ln|exp|sin|cos|tan|det)\b/giu,
    ''
  )
  // A Cyrillic prose row can contain a parenthetical or Latin citation label.
  if (
    /^(?:(?=\p{Script=Cyrillic})\p{Lu} )?\p{Script=Cyrillic}{3,}\s/u.test(content) &&
    !/[∠√∑∫∏=≠≤≥+*/^←→∂−\p{Script=Greek}\p{Cc}]/u.test(content) &&
    (content.match(/\p{Script=Cyrillic}{3,}/gu)?.length ?? 0) >= 2
  )
    return false
  return (
    (content.includes('\u0302') ||
      /[([|√∑∫=≠≤≥+*/^←→∂−\p{Script=Greek}]/u.test(content) ||
      /^[)\]}]+(?:\s*[A-Za-z\p{Script=Greek}])?$/u.test(content.trim()) ||
      /\b[A-Za-z]{2,}\s*[([]/u.test(content)) &&
    !/(?:[A-Za-z]{3,}|\b(?:an|as|at|be|by|do|go|if|in|is|it|no|of|on|or|so|to|up|us|we)\b)/iu.test(
      content.replace(/\b[A-Za-z]{2,}[\p{Script=Greek}\d]*(?=\s*[([])/gu, '')
    )
  )
}

// Classify an existing owner, without acquiring sources or constructing a frame.
// Every apparent long word must instead contain an independently attached index.
function nativeNumberedScriptChain(
  block: Block,
  page: PdfLayoutPage,
  blocks: readonly Block[],
  attachedScripts: ReadonlySet<Item>
): boolean {
  const items = block.items,
    number = items.at(-1),
    relations = items.filter((item) => item.str.includes('='))
  if (
    page.rotation !== 0 ||
    block.lines.length !== 1 ||
    block.risks.length ||
    !number ||
    !/^\([1-9]\d{0,3}\)$/u.test(number.str) ||
    number.hasEOL !== true ||
    relations.length < 2 ||
    symbolicExpression(block.source) ||
    !symbolicExpression(items.map((item) => item.str).join(' ')) ||
    items.some((item) => /[A-Za-z]{3,}|[\p{Cc}\p{Co}]/u.test(item.str)) ||
    items
      .map((item) => item.str)
      .join('')
      .replace(/\s/gu, '') !== block.source.replace(/\s/gu, '')
  )
    return false
  const complete = (item: Item): boolean => {
    const raw = page.items[item.index]
    return (
      !!raw &&
      raw.str === item.str &&
      raw.fontName === item.fontName &&
      raw.width === item.width &&
      raw.height === item.height &&
      raw.transform.length === 6 &&
      raw.transform.every((value, index) => value === item.transform[index]) &&
      item.key === `${page.page}:${item.index}` &&
      item.page === page.page &&
      !item.unsupported &&
      item.dir === 'ltr' &&
      !!item.fontName &&
      item.fontVertical === false &&
      item.width > 0 &&
      item.height > 0 &&
      item.transform.length === 6 &&
      [...item.transform, item.width, item.height, item.fontAscent, item.fontDescent].every(
        (value) => Number.isFinite(value)
      ) &&
      item.transform[0] === item.height &&
      item.transform[3] === item.height &&
      item.transform[1] === 0 &&
      item.transform[2] === 0 &&
      item.fontAscent! > 0 &&
      item.fontAscent! <= 1 &&
      item.fontDescent! <= 0 &&
      item.fontDescent! >= -1 &&
      item.transform[4] >= 0 &&
      item.transform[4] + item.width <= page.width &&
      item.transform[5] + item.height * item.fontDescent! >= 0 &&
      item.transform[5] + item.height * item.fontAscent! <= page.height
    )
  }
  const font = relations[0].font,
    baseline = relations[0].originalBaseline
  if (
    !Number.isFinite(font) ||
    font <= 0 ||
    !items.every(
      (item, index) => complete(item) && (index === 0 || item.index > items[index - 1].index)
    ) ||
    ![...relations, number].every(
      (item) => item.font === font && Math.abs(item.originalBaseline - baseline) < font * 0.05
    )
  )
    return false
  const previousNumber = `(${Number(number.str.slice(1, -1)) - 1})`,
    witnesses = blocks.filter(
      (peer) =>
        peer !== block &&
        peer.items.length === 1 &&
        peer.source === previousNumber &&
        peer.items[0].str === previousNumber
    )
  if (witnesses.length !== 1) return false
  const witness = witnesses[0].items[0]
  if (
    !complete(witness) ||
    witness.index >= items[0].index ||
    witness.fontName !== number.fontName ||
    witness.font !== font ||
    Math.abs(witness.right - number.right) >= font * 0.05
  )
    return false
  const characters = items.flatMap((item) =>
      item.str
        .split('')
        .filter((character) => !/\s/u.test(character))
        .map((character) => ({ character, item }))
    ),
    words = [
      ...characters
        .map((part) => part.character)
        .join('')
        .matchAll(/[A-Za-z]{3,}/gu)
    ]
  return (
    words.length > 0 &&
    words.every((word) => {
      const members = [
        ...new Set(
          characters.slice(word.index, word.index + word[0].length).map((part) => part.item)
        )
      ]
      return (
        members.some((item) => item.font === font) &&
        members.some((item, index) => {
          const base = members[index - 1]
          return (
            !!base &&
            attachedScripts.has(item) &&
            /^[A-Za-z]{1,2}$/u.test(item.str) &&
            item.fontName !== base.fontName &&
            item.font > base.font * 0.55 &&
            item.font < base.font * 0.85 &&
            item.originalBaseline - base.originalBaseline > base.font * 0.08 &&
            item.originalBaseline - base.originalBaseline < base.font * 0.55 &&
            item.x - base.right >= -base.font * 0.05 &&
            item.x - base.right < base.font * 0.3
          )
        })
      )
    })
  )
}

// A named function can share a block with only the lower part of a TeX
