    const rows = [1, 2, 3, 4].map((offset) => nativeGroups.get(first.nativeLine + offset) ?? [])
    const firstLabel = rows[0][0]
    const mode = (label: Item): string =>
      /^[A-Z][a-z]{2,15}, [A-Z][a-z]{2,8}\.$/u.test(label.str) ? label.str.split(',')[0] : ''
    const cells: Item[][] = []
