    const figure = floats.filter((block) => /^Fig(?:ure|\.) [1-9]\d*\. /u.test(block.source))
    const table = floats.filter((block) => /^Table [1-9]\d*\. /u.test(block.source))
    if (figure.length !== 2 || table.length !== 1) continue
