function nativeTextOverlapsProof(item: PdfLayoutTextItem, domain: Rect): boolean {
  if (!item.str.trim()) return false
  const rect = nativeProseProofDomain([item])
  return (
    !rect ||
    (rect.x < domain.right &&
      rect.right >= domain.x &&
      rect.bottom > domain.y &&
      rect.y < domain.bottom)
  )
}

// Rotated margin text must be bounded in its own axes before testing a prose row.
function nativeProseRowOverlap(item: PdfLayoutTextItem, domain: Rect): boolean {
  if (item.transform[1] === 0 && item.transform[2] === 0)
    return nativeTextOverlapsProof(item, domain)
  const [a, b, c, d, x, y] = item.transform,
    advance = Math.hypot(a, b),
    ascent = item.fontAscent,
    descent = item.fontDescent
  if (!item.str.trim()) return false
  if (
    item.fontVertical !== false ||
    item.dir !== 'ltr' ||
    item.width <= 0 ||
    ![...item.transform, item.width, ascent, descent].every(Number.isFinite) ||
    advance <= 0 ||
    ascent! <= descent!
  )
    return true
  const corners = [0, item.width].flatMap((offset) =>
    [descent!, ascent!].map((height) => ({
      x: x + (a / advance) * offset + c * height,
      y: y + (b / advance) * offset + d * height
    }))
  )
  return (
    Math.min(...corners.map((p) => p.x)) < domain.right &&
    Math.max(...corners.map((p) => p.x)) >= domain.x &&
    Math.max(...corners.map((p) => p.y)) > domain.y &&
    Math.min(...corners.map((p) => p.y)) < domain.bottom
  )
}

// A wrapped expansion is ordinary prose only when its complete preceding words
// independently spell the acronym. Prove both native rows and their owners;
// an acronym-looking function or a detached label supplies no such evidence.
function nativeWrappedAcronymProse(
  block: LayoutBlock,
  page: LayoutPage,
  raw: PdfLayoutTextItem[]
): boolean {
  const shape = /^([A-Z][a-z]{3,}) \(([A-Z](?:&?[A-Z]){1,7})\)(?: (?:and|or))?$/u.exec(block.source)
  if (
    !shape ||
    block.sourceOnly ||
    block.tableCell ||
    block.risks.length ||
    block.lines.length !== 1 ||
    block.source !== block.lines[0].text
  )
    return false
  const indices = block.items.map((key) => Number(key.split(':')[1])),
    owned = new Set(indices),
    first = raw[indices[0]],
    last = raw[indices.at(-1)!]
  if (
    !first?.fontName ||
    !last ||
    owned.size !== indices.length ||
    indices.some((i, n) => n > 0 && i <= indices[n - 1])
  )
    return false
  const literal = indices
    .map((i) => raw[i]?.str)
    .join(' ')
    .replace(/\s*&\s*/gu, '&')
    .replace(/\(\s+/gu, '(')
    .replace(/\s+\)/gu, ')')
  if (
    block.originalStrings.length !== indices.length ||
    indices.some((i, n) => raw[i]?.str !== block.originalStrings[n]) ||
    literal !== block.source
  )
    return false
  const size = first.height,
    y = first.transform[5],
    x = first.transform[4]
  const valid = (i: PdfLayoutTextItem): boolean =>
    !!i &&
    i.dir === 'ltr' &&
    i.fontName === first.fontName &&
    i.width > 0 &&
    size > 0 &&
    [...i.transform, i.width, i.height, i.fontAscent, i.fontDescent].every(Number.isFinite) &&
    i.fontAscent! > 0 &&
    i.fontAscent! > i.fontDescent! &&
    i.fontAscent === first.fontAscent &&
    i.fontDescent === first.fontDescent &&
    Math.abs(i.height - size) < size * 0.01 &&
    i.transform[0] > 0 &&
    i.transform[3] > 0 &&
    i.transform[1] === 0 &&
    i.transform[2] === 0
  const native = raw.flatMap((i, index) => (i.str.trim() ? [{ ...i, index }] : [])),
    current = native.filter((i) => Math.abs(i.transform[5] - y) < size * 0.01)
  if (
    !current.length ||
    current[0].index !== indices[0] ||
    current.some((i) => !valid(i)) ||
    indices.some((i) => !current.some((r) => r.index === i))
  )
    return false
  const previous = native.filter((i) => i.index < indices[0]),
    predecessor = previous.at(-1)
  if (!predecessor) return false
  const priorY = predecessor.transform[5],
    before = previous.filter((i) => Math.abs(i.transform[5] - priorY) < size * 0.01)
  if (
    !before.length ||
    !before.every(valid) ||
    priorY - y < size * 0.75 ||
    priorY - y > size * 1.7 ||
    Math.abs(before[0].transform[4] - x) > size * 0.1
  )
    return false
  const all = [...before, ...current],
    keys = new Set(all.map((i) => i.index)),
    previousOwners = page.blocks.filter((b) =>
      b.items.includes(page.page + ':' + before.at(-1)!.index)
    ),
    next = current.filter((i) => i.index > indices.at(-1)!)
  if (
    previousOwners.length !== 1 ||
    previousOwners[0] === block ||
    previousOwners[0].tableCell ||
    previousOwners[0].sourceOnly ||
    previousOwners[0].risks.some((r) => r !== 'possible-continuation') ||
    !previousOwners[0].lines.length ||
    symbolicExpression(previousOwners[0].source) ||
    (previousOwners[0].source.match(/[A-Za-z]{2,}/gu)?.length ?? 0) < 12 ||
    !next.length
  )
    return false
  const beforeText = before.map((i) => i.str).join(' '),
    afterText = next.map((i) => i.str).join(' '),
    letters = shape[2].replaceAll('&', ''),
    words = [...beforeText.matchAll(/[A-Za-z]+/gu)],
    start = words.at(-(letters.length - 1))?.index
  if (
    start === undefined ||
    !/^[A-Za-z][A-Za-z\s(),.'’&;:!\d%–-]*$/u.test(afterText) ||
    (afterText.match(/[A-Za-z]{2,}/gu)?.length ?? 0) < 6
  )
    return false
  const expansion = beforeText.slice(start).match(/[A-Za-z]+|&/gu)
  if (
    !expansion ||
    expansion.some((w) => w !== '&' && !/^[A-Z][a-z]+$/u.test(w)) ||
    [...expansion.map((w) => (w === '&' ? '&' : w[0])), shape[1][0]].join('') !== shape[2]
  )
    return false
  for (const row of [before, current])
    for (let n = 1; n < row.length; n++) {
      const left = row[n - 1],
        right = row[n],
        gap = right.transform[4] - left.transform[4] - left.width
      if (
        right.index <= left.index ||
        raw.slice(left.index + 1, right.index).some((i) => i.str.trim()) ||
        gap < -size * 0.05 ||
        gap > size
      )
        return false
    }
  const right = Math.max(...current.map((i) => i.transform[4] + i.width)),
    oldRight = Math.max(...before.map((i) => i.transform[4] + i.width))
  if (
    right - x < page.width * 0.5 ||
    Math.abs(oldRight - right) > size * 1.5 ||
    raw
      .slice(before[0].index, current.at(-1)!.index + 1)
      .some((i, n) => i.str.trim() && !keys.has(before[0].index + n))
  )
    return false
  if (
    all.some((i) => {
      const owners = page.blocks.filter((b) => b.items.includes(page.page + ':' + i.index))
      return (
        owners.length !== 1 ||
        owners[0].tableCell ||
        owners[0].sourceOnly ||
        owners[0].risks.some((r) => r !== 'possible-continuation')
      )
    })
  )
    return false
  const domain = nativeProseProofDomain(all)
  return (
    !!domain &&
    domain.x >= 0 &&
    domain.y >= 0 &&
    domain.right <= page.width &&
    domain.bottom <= page.height &&
    !raw.some((i, index) => !keys.has(index) && nativeTextOverlapsProof(i, domain))
  )
}

// Short closed references can resemble function calls after symbolic token removal.
// Release only complete native text with an adjacent, independently owned prose row.
function nativeClosedReferenceProse(
  block: LayoutBlock,
  page: LayoutPage,
  raw: PdfLayoutTextItem[]
): boolean {
  const numbered = /^\((\d+)\) [A-Z][a-z]+(?: [a-z]+)+ \((\d+)\)\.$/u.exec(block.source)
  const citation = /^[a-z]{3,} from \[\d+\]\.$/u.test(block.source)
  if (
    (!numbered && !citation) ||
    block.sourceOnly ||
    block.tableCell ||
    block.risks.length ||
    block.lines.length !== 1 ||
    block.items.length !== (numbered ? 1 : 3)
  )
    return false
  const indices = block.items.map((key) => Number(key.split(':')[1]))
  const current = indices.map((index) => raw[index]),
    first = current[0]
  if (!first?.fontName || current.some((item) => !item)) return false
  const font = first.height,
    y = first.transform[5],
    x = first.transform[4]
  if (
    current.some(
      (item, i) =>
        !item.fontName ||
        item.dir !== 'ltr' ||
        item.width <= 0 ||
        Math.abs(item.height - font) > font * 0.05 ||
        Math.abs(item.transform[5] - y) > font * 0.05 ||
        (i > 0 &&
          (indices[i] <= indices[i - 1] ||
            current[i - 1].hasEOL ||
            Math.abs(item.transform[4] - current[i - 1].transform[4] - current[i - 1].width) >
              font * 0.15))
    )
  )
    return false
  if (numbered) {
    if (first.str !== block.source || Number(numbered[1]) !== Number(numbered[2]) + 1) return false
  } else if (
    !/^[a-z]{3,} from \[$/u.test(first.str) ||
    !/^\d+$/u.test(current[1].str) ||
    current[2].str !== '].' ||
    current[2].fontName !== first.fontName
  )
    return false
  const previous = page.blocks.filter((owner) => {
    if (
      owner === block ||
      owner.tableCell ||
      owner.sourceOnly ||
      owner.risks.some((risk) => !['ambiguous-line-hyphen', 'possible-continuation'].includes(risk))
    )
      return false
    const line = owner.lines.at(-1)!
    const keys = line.items.map((key) => Number(key.split(':')[1]))
    const items = keys.map((index) => raw[index]),
      last = items.at(-1)!
    if (
      !items.length ||
      !last?.hasEOL ||
      Math.max(...keys) >= indices[0] ||
      raw.slice(Math.max(...keys) + 1, indices[0]).some((item) => item.str.trim()) ||
      Math.abs(line.x - x) > font * 0.15 ||
      last.transform[5] - y < font * 0.75 ||
      last.transform[5] - y > font * 1.7 ||
      items[0].fontName !== first.fontName ||
      last.fontName !== first.fontName ||
      Math.abs(items[0].height - font) > font * 0.05 ||
      Math.abs(last.height - font) > font * 0.05 ||
      symbolicExpression(line.text) ||
      (line.text.match(/[A-Za-z]{2,}/gu)?.length ?? 0) < (numbered ? 6 : 8)
    )
      return false
    if (numbered) {
      if (!owner.source.startsWith('(' + numbered[2] + ') ')) return false
    } else if (
      !/[a-z]{2,}-$/u.test(line.text) ||
      current.at(-1)!.transform[4] + current.at(-1)!.width >= line.right - font * 2
    )
      return false
    const used = new Set([...keys, ...indices])
    if (
      [...used].some(
        (index) =>
          !raw[index].fontName ||
          Math.abs(raw[index].transform[3] - raw[index].height) > raw[index].height * 0.05 ||
          page.blocks.filter((owner) => owner.items.includes(`${page.page}:${index}`)).length !== 1
      )
    )
      return false
    const domains = [
      nativeProseProofDomain(current),
      ...items.map((item) => nativeProseProofDomain([item]))
    ]
    return (
      domains.every((domain) => !!domain) &&
      !raw.some(
        (item, index) =>
          !used.has(index) && domains.some((domain) => nativeTextOverlapsProof(item, domain!))
      )
    )
  })
  return previous.length === 1
}

// A date-bearing continuation requires two complete native prose rows.
function nativeContinuedLiteralProse(
  block: LayoutBlock,
  page: LayoutPage,
  raw: PdfLayoutTextItem[]
): boolean {
  if (
    block.sourceOnly ||
    block.tableCell ||
    block.risks.length ||
    block.lines.length !== 1 ||
    !/^(?:(?:day|date) \((?:[1-9]|1[0-2])\/(?:[1-9]|[12]\d|3[01])\) and)$/u.test(block.source)
  )
    return false
  const firstIndex = Number(block.items[0].split(':')[1]),
    first = raw[firstIndex]
  if (!first?.fontName) return false
  let start = firstIndex
  while (start > 0 && !raw[start - 1].hasEOL) start--
  let end = start
  while (end < raw.length && !raw[end].hasEOL) end++
  if (start === 0 || end === raw.length) return false
  let previousStart = start - 1
  while (previousStart > 0 && !raw[previousStart - 1].hasEOL) previousStart--
  const current = raw.slice(start, end + 1).filter((item) => item.str.trim()),
    previous = raw.slice(previousStart, start).filter((item) => item.str.trim()),
    font = first.height
  if (!current.length || !previous.length || current[0] !== first) return false
  const valid = (item: PdfLayoutTextItem): boolean =>
    item.fontName === first.fontName &&
    item.dir === 'ltr' &&
    item.width > 0 &&
    font > 0 &&
    [...item.transform, item.width, item.height].every(Number.isFinite) &&
    item.transform[0] > 0 &&
    item.transform[3] > 0 &&
    item.transform[1] === 0 &&
    item.transform[2] === 0 &&
    Math.abs(item.height - font) < font * 0.05
  const text = (items: PdfLayoutTextItem[]): string => items.map((item) => item.str).join(' ')
  if (
    ![...current, ...previous].every(valid) ||
    [current, previous].some(
      (row) =>
        (text(row).match(/[A-Za-z]{2,}/gu)?.length ?? 0) < 8 ||
        !/^[A-Za-z0-9\s.,;:'’()[\]/–—-]+$/u.test(text(row)) ||
        row.some(
          (item, i) =>
            Math.abs(item.transform[5] - row[0].transform[5]) > font * 0.05 ||
            (i > 0 &&
              (item.transform[4] < row[i - 1].transform[4] + row[i - 1].width - font * 0.05 ||
                item.transform[4] > row[i - 1].transform[4] + row[i - 1].width + font * 0.8))
        )
    ) ||
    /[.!?:;]$/u.test(text(previous).trim())
  )
    return false
  const joined = text(current)
  for (const [opening, closing] of [
    ['(', ')'],
    ['[', ']']
  ]) {
    let depth = 0
    for (const char of joined) {
      if (char === opening) depth++
      if (char === closing && --depth < 0) return false
    }
    if (depth) return false
  }
  const x = first.transform[4],
    y = first.transform[5],
    oldY = previous[0].transform[5],
    right = previous.at(-1)!.transform[4] + previous.at(-1)!.width
  if (
    Math.abs(previous[0].transform[4] - x) > font * 0.2 ||
    oldY - y < font * 0.75 ||
    oldY - y > font * 2 ||
    current.at(-1)!.transform[4] + current.at(-1)!.width > right + font * 0.2
  )
    return false
  const domain = nativeProseProofDomain([...current, ...previous])
  if (!domain) return false
  return (
    !raw.some(
      (item, index) =>
        (index < previousStart || index > end) && nativeTextOverlapsProof(item, domain)
    ) &&
    block.items.every(
      (key) => page.blocks.filter((owner) => owner.items.includes(key)).length === 1
    )
  )
}

// Explicit equation references retain the native body font and nearby prose.
function nativeNamedEquationProse(
  block: LayoutBlock,
  page: LayoutPage,
  raw: PdfLayoutTextItem[]
): boolean {
  if (
    block.sourceOnly ||
    block.tableCell ||
    block.risks.length ||
    block.lines.length !== 1 ||
    !/^(?:(?:Hence|From|By|Using|See) Eq\.|Equations?) \((?:[A-Z]|\d+)\.\d+\)(?: and \((?:[A-Z]|\d+)\.\d+\))?[,.:]?$/u.test(
      block.source
    )
  )
    return false
  const indices = block.items.map((key) => Number(key.split(':')[1])),
    items = indices.map((i) => raw[i]),
    first = items[0],
    last = items.at(-1)!
  if (!first?.fontName || !last || indices.some((i, n) => n > 0 && i <= indices[n - 1]))
    return false
  const font = first.height,
    y = first.transform[5],
    x = first.transform[4]
  const valid = (item: PdfLayoutTextItem): boolean =>
    !!item &&
    item.fontName === first.fontName &&
    item.dir === 'ltr' &&
    item.width > 0 &&
    font > 0 &&
    [...item.transform, item.width, item.height].every(Number.isFinite) &&
    item.transform[0] > 0 &&
    item.transform[3] > 0 &&
    item.transform[1] === 0 &&
    item.transform[2] === 0 &&
    Math.abs(item.height - font) < font * 0.05
  if (
    !items.every(valid) ||
    raw.some(
      (item) =>
        item.str.trim() &&
        (![...item.transform, item.width, item.height].every(Number.isFinite) ||
          ((item.width <= 0 || item.height <= 0) && Math.abs(item.transform[5] - y) < font * 2))
    )
  )
    return false
  const used = new Set(indices)
  if (
    raw
      .slice(indices[0], indices.at(-1)! + 1)
      .some((item, n) => item.str.trim() && !used.has(indices[0] + n))
  )
    return false
  for (let i = 0; i < items.length; i++) {
    if (Math.abs(items[i].transform[5] - y) > font * 0.05) return false
    if (
      i &&
      (items[i].transform[4] < items[i - 1].transform[4] + items[i - 1].width - font * 0.05 ||
        items[i].transform[4] > items[i - 1].transform[4] + items[i - 1].width + font * 0.65)
    )
      return false
  }
  const peers = raw.filter(
    (item) =>
      valid(item) &&
      !items.includes(item) &&
      Math.abs(item.transform[5] - y) < font * 20 &&
      (item.str.match(/[A-Za-z]{2,}/gu)?.length ?? 0) >= 8 &&
      !symbolicExpression(item.str) &&
      item.width > font * 15
  )
  if (peers.length < 2 || !peers.some((item) => Math.abs(item.transform[4] - x) < font * 0.2))
    return false
  const domain = nativeProseProofDomain(items)
  if (!domain) return false
  return (
    items.every(
      (_, n) => page.blocks.filter((owner) => owner.items.includes(block.items[n])).length === 1
    ) && !raw.some((item, i) => !used.has(i) && nativeTextOverlapsProof(item, domain))
  )
}

// Repeated native post-bibliography headings can share one grouped prose unit.
function nativePostReferenceSections(
  unit: LayoutUnit,
  pages: LayoutPage[],
  rawItems: Map<number, PdfLayoutTextItem[]>
): boolean {
  if (unit.sourceOnly || unit.risks.length || unit.fragments.length !== 1) return false
  const page = pages.find((page) => page.page === unit.fragments[0].page),
    raw = rawItems.get(unit.fragments[0].page)
  if (!page || !raw) return false
  if (
    raw.some(
      (item) =>
        item.str.trim() &&
        (![...item.transform, item.width, item.height].every(Number.isFinite) ||
          item.width <= 0 ||
          item.height <= 0)
    )
  )
    return false
  const lines = page.blocks.flatMap((block) => block.lines).sort((a, b) => a.y - b.y || a.x - b.x),
    start = lines.findIndex((line) => line.items[0] === unit.items[0])
  if (start < 0 || !/^(?:Acknowledgements|Acknowledgments|Funding)$/u.test(lines[start].text))
    return false
  const first = raw[Number(lines[start].items[0].split(':')[1])]
  if (!first?.fontName) return false
  const font = first.height,
    x = first.transform[4]
  const titles =
    /^(?:Acknowledgements|Acknowledgments|Funding|Author contributions|Competing interests|Conflicts of interest|Data availability|Code availability)$/u
  let headings = 0,
    proseLines = 0,
    lastHeading = -1,
    bodyFont: string | undefined
  const owned = new Set<string>(),
    names = new Set<string>()
  let bottom = lines[start].bottom
  for (let i = start; i < lines.length; i++) {
    const line = lines[i]
    if (i > start && line.y - bottom > font * 1.5) break
    const items = line.items.map((key) => raw[Number(key.split(':')[1])])
    if (
      !items.length ||
      items.some(
        (item) =>
          !item ||
          !item.fontName ||
          item.dir !== 'ltr' ||
          ![...item.transform, item.width, item.height].every(Number.isFinite) ||
          item.width <= 0 ||
          item.transform[0] <= 0 ||
          item.transform[3] <= 0 ||
          item.transform[1] !== 0 ||
          item.transform[2] !== 0 ||
          Math.abs(item.height - font) > font * 0.05
      )
    )
      return false
    if (Math.abs(line.x - x) > font * 0.2) return false
    if (titles.test(line.text)) {
      if (
        line.items.length !== 1 ||
        items[0].fontName !== first.fontName ||
        names.has(line.text) ||
        (headings > 0 && lastHeading === i - 1)
      )
        return false
      names.add(line.text)
      headings++
      lastHeading = i
    } else {
      if (
        /^(?:\[\d+\]|\d+[.)])\s+\p{L}/u.test(line.text) ||
        items.some((item) => item.fontName === first.fontName)
      )
        return false
      bodyFont ??= items[0].fontName
      if (items.some((item) => item.fontName !== bodyFont)) return false
      if ((line.text.match(/[A-Za-z]{2,}/gu)?.length ?? 0) >= 6) proseLines++
    }
    for (const key of line.items) owned.add(key)
    bottom = line.bottom
    if (headings >= 3 && i > lastHeading && proseLines >= 3) break
  }
  if (headings < 3 || proseLines < 3 || !font || bottom <= lines[start].bottom) return false
  const domain = nativeProseProofDomain([...owned].map((key) => raw[Number(key.split(':')[1])]))
  if (!domain) return false
  return !raw.some(
    (item, i) => !owned.has(`${page.page}:${i}`) && nativeTextOverlapsProof(item, domain)
  )
}

// A word before an inline document path belongs to the surrounding prose only
// when native rows, fonts and the complete parenthesis independently agree.
function nativeParenthesizedPathProse(
  block: LayoutBlock,
  page: LayoutPage,
  raw: PdfLayoutTextItem[]
): boolean {
  if (
    block.sourceOnly ||
    block.tableCell ||
    block.risks.length ||
    block.items.length !== 1 ||
    !/^[a-z]{4,} \($/u.test(block.source)
  )
    return false
  if (
    raw.some(
      (item) =>
        item.str.trim() &&
        (![...item.transform, item.width, item.height].every(Number.isFinite) ||
          item.width <= 0 ||
          item.height <= 0)
    )
  )
    return false
  const index = Number(block.items[0].split(':')[1]),
    word = raw[index]
  if (!word || word.str !== block.source || !word.fontName || word.hasEOL) return false
  const font = word.height,
    x = word.transform[4],
    y = word.transform[5]
  const valid = (item: PdfLayoutTextItem): boolean =>
    !!item.fontName &&
    item.dir === 'ltr' &&
    item.width > 0 &&
    font > 0 &&
    [...item.transform, item.width, item.height].every(Number.isFinite) &&
    item.transform[0] > 0 &&
    item.transform[3] > 0 &&
    item.transform[1] === 0 &&
    item.transform[2] === 0 &&
    Math.abs(item.height - font) < font * 0.05
  const path = raw[index + 1],
    tail = raw[index + 2],
    previous = raw[index - 1]
  if (!path || !tail || !previous || ![word, path, tail, previous].every(valid)) return false
  if (
    path.hasEOL ||
    !tail.hasEOL ||
    !previous.hasEOL ||
    path.fontName === word.fontName ||
    tail.fontName !== word.fontName ||
    previous.fontName !== word.fontName ||
    !/^[A-Za-z0-9_-]+(?:\/[A-Za-z0-9_-]+)+\.[A-Za-z]{1,8}$/u.test(path.str) ||
    !/^\) [A-Za-z][A-Za-z ,.'’-]+(?:[A-Za-z]|[.!?])$/u.test(tail.str) ||
    (tail.str.match(/[A-Za-z]{2,}/gu)?.length ?? 0) < 6 ||
    !/^[A-Za-z][A-Za-z0-9 ,.'’-]+[A-Za-z]$/u.test(previous.str) ||
    (previous.str.match(/[A-Za-z]{2,}/gu)?.length ?? 0) < 8 ||
    Math.abs(previous.transform[4] - x) > font * 0.15 ||
    previous.transform[5] - y < font * 0.75 ||
    previous.transform[5] - y > font * 1.7
  )
    return false
  for (const [left, right] of [
    [word, path],
    [path, tail]
  ]) {
    if (
      Math.abs(right.transform[5] - y) > font * 0.05 ||
      Math.abs(right.transform[4] - left.transform[4] - left.width) > font * 0.15
    )
      return false
  }
  const right = tail.transform[4] + tail.width
  if (Math.abs(previous.transform[4] + previous.width - right) > font * 0.5) return false
  const used = new Set([index - 1, index, index + 1, index + 2])
  const domain = nativeProseProofDomain([...used].map((i) => raw[i]))
  if (!domain) return false
  if (raw.some((item, i) => !used.has(i) && nativeTextOverlapsProof(item, domain))) return false
  return [...used].every(
    (i) => page.blocks.filter((owner) => owner.items.includes(`${page.page}:${i}`)).length === 1
  )
}

// Preserve a native prose word continued before a complete section locator.
function nativeHyphenatedSectionTail(
  block: LayoutBlock,
  page: LayoutPage,
  raw: PdfLayoutTextItem[]
): boolean {
  if (
    block.sourceOnly ||
    block.tableCell ||
    block.items.length !== 1 ||
    block.risks.length ||
    !/^[a-z]{3,} \(§\d+(?:\.\d+)+\)\.$/u.test(block.source)
  )
    return false
  const index = Number(block.items[0].split(':')[1]),
    tail = raw[index]
  if (!tail || tail.str !== block.source || !tail.fontName || tail.dir !== 'ltr') return false
  const font = tail.height,
    x = tail.transform[4],
    y = tail.transform[5]
  if (
    !(font > 0) ||
    tail.transform[1] !== 0 ||
    tail.transform[2] !== 0 ||
    tail.transform[0] <= 0 ||
    tail.transform[3] <= 0
  )
    return false
  const owners = page.blocks.filter((owner) => {
    if (
      owner === block ||
      owner.sourceOnly ||
      owner.tableCell ||
      owner.lines.length < 2 ||
      owner.risks.some((risk) => !['ambiguous-line-hyphen', 'possible-continuation'].includes(risk))
    )
      return false
    const line = owner.lines.at(-1)!
    if (
      !/[a-z]{2,}-$/u.test(line.text) ||
      (line.text.match(/\p{L}{2,}/gu)?.length ?? 0) < 6 ||
      symbolicExpression(line.text)
    )
      return false
    const indices = line.items.map((key) => Number(key.split(':')[1])),
      previous = indices.map((i) => raw[i])
    if (
      Math.max(...indices) >= index ||
      raw.slice(Math.max(...indices) + 1, index).some((item) => item.str.trim())
    )
      return false
    const last = previous.at(-1)!
    if (
      !last.hasEOL ||
      previous.some(
        (item) =>
          !item ||
          item.dir !== 'ltr' ||
          item.fontName !== tail.fontName ||
          Math.abs(item.height - font) > font * 0.05 ||
          item.transform[1] !== 0 ||
          item.transform[2] !== 0 ||
          Math.abs(item.transform[5] - last.transform[5]) > font * 0.05
      )
    )
      return false
    const gap = last.transform[5] - y
    if (
      gap <= font * 0.75 ||
      gap >= font * 1.7 ||
      Math.abs(line.x - x) >= font * 0.15 ||
      tail.width >= line.right - line.x - font * 2
    )
      return false
    // An earlier complete prose row independently establishes this body's left edge.
    if (
      !owner.lines
        .slice(0, -1)
        .some(
          (peer) =>
            Math.abs(peer.x - line.x) < font * 0.15 &&
            (peer.text.match(/\p{L}{2,}/gu)?.length ?? 0) >= 6 &&
            !symbolicExpression(peer.text)
        )
    )
      return false
    const owned = new Set([...indices, index])
    // No unowned native ink may cross the two adjacent row domains, even when
    // the PDF emits that competing source outside their native index interval.
    return !raw.some(
      (item, i) =>
        !owned.has(i) &&
        item.str.trim() &&
        item.width > 0 &&
        item.height > 0 &&
        item.transform[4] < line.right &&
        item.transform[4] + item.width > Math.min(x, line.x) &&
        item.transform[5] >= y - font * 0.1 &&
        item.transform[5] <= last.transform[5] + font * 0.1
    )
  })
  return owners.length === 1
}

// Native proof: an isolated word+decimal reference has both a numbered-equation
// target and a contiguous native prose continuation. No grouping is changed.
// Restore a complete existing sentence-tail owner only. The numbered equation,
// the preceding body owner and any separate proof box keep their original roles.
function nativeWrappedEquationReferenceTail(
  block: LayoutPage['blocks'][number],
  page: LayoutPage,
  rawPages: PdfLayoutPage[],
  layoutPages: LayoutPage[]
): boolean {
  const lead = /^([A-Z][a-z]{3,19} from) \((\d{1,6})\)$/u.exec(block.source)
  const proofPart = /^Part \(i\)\.$/u.test(block.source)
  const whole =
    /^(?:([a-z]{3,20} from) \((\d{1,6})\)\.|([A-Z][a-z]{2,16}ing) \((\d{1,6})\):)$/u.exec(
      block.source
    )
  const match = proofPart
    ? [block.source, 'Part', 'i']
    : (lead ??
      (whole
        ? [whole[0], whole[1] ?? whole[3], whole[2] ?? whole[4]]
        : /^([a-z]{3,20}) \((\d{1,6})\)\.$/u.exec(block.source)))
  if (
    !match ||
    /^(?:sin|cos|tan|log|exp|min|max|argmin|argmax|det|relu|softmax|sigmoid|norm|var)$/u.test(
      whole || lead || proofPart ? match[1].split(' ')[0].toLowerCase() : match[1]
    ) ||
    block.sourceOnly ||
    block.preserve ||
    block.tableCell ||
    block.risks.length ||
    block.lines.length !== 1 ||
    block.items.length !== (whole || proofPart ? 1 : lead ? 2 : 3)
  )
    return false
  const raw = rawPages.find((p) => p.page === page.page)
  if (!raw || raw.rotation !== 0 || !raw.nativeSectionFontEvidence?.complete) return false
  const indices = block.items.map((key) => Number(key.split(':')[1]))
  if (indices.some((n, at) => !Number.isSafeInteger(n) || (at > 0 && n <= indices[at - 1])))
    return false
  const selected = indices.map((n) => raw.items[n]),
    first = selected[0],
    last = selected.at(-1)!
  const valid = (
    p: PdfLayoutPage,
    item: PdfLayoutTextItem | undefined,
    zero = false
  ): item is PdfLayoutTextItem => {
    if (!item || !p.nativeSectionFontEvidence?.complete) return false
    const font = p.nativeSectionFontEvidence.fonts[item.fontName ?? '']
    return (
      !!font?.nativeMetrics &&
      font.ascent > 0 &&
      font.ascent <= 1 &&
      font.descent >= -1 &&
      font.descent <= 0 &&
      font.ascent === item.fontAscent &&
      font.descent === item.fontDescent &&
      item.fontVertical === false &&
      item.dir === 'ltr' &&
      item.transform.length === 6 &&
      [...item.transform, item.width, item.height, item.fontAscent, item.fontDescent].every(
        Number.isFinite
      ) &&
      (item.width > 0 || (zero && item.width === 0)) &&
      item.height > 0 &&
      item.transform[0] > 0 &&
      Math.abs(item.transform[0] - item.height) < item.height * 0.05 &&
      item.transform[3] === item.height &&
      item.transform[1] === 0 &&
      item.transform[2] === 0 &&
      Number.isFinite(p.width) &&
      p.width > 0 &&
      Number.isFinite(p.height) &&
      p.height > 0 &&
      item.transform[4] >= 0 &&
      item.transform[4] + item.width <= p.width &&
      item.transform[5] + font.descent * item.height >= 0 &&
      item.transform[5] + font.ascent * item.height <= p.height
    )
  }
  if (!selected.every((item) => valid(raw, item)) || !first.fontName) return false
  const font = first.height,
    baseline = first.transform[5],
    labelText = '(' + match[2] + ')'
  if (
    whole || proofPart
      ? first.str !== block.source
      : lead
        ? first.str !== match[1] || selected[1].str !== labelText
        : selected[0].str !== match[1] ||
          selected[1].str !== labelText ||
          selected[2].str !== '.' ||
          selected[2].fontName !== first.fontName
  )
    return false
  for (const [at, item] of selected.entries()) {
    if (
      block.originalStrings[at] !== item.str ||
      page.blocks.filter((b) => b.items.includes(page.page + ':' + indices[at])).length !== 1 ||
      Math.abs(item.height - font) >= font * 0.05 ||
      Math.abs(item.transform[5] - baseline) >= font * 0.05 ||
      (at > 0 &&
        (selected[at - 1].hasEOL ||
          raw.items.slice(indices[at - 1] + 1, indices[at]).some((i) => i.str.trim() || i.hasEOL) ||
          item.transform[4] - selected[at - 1].transform[4] - selected[at - 1].width <
            -font * 0.05 ||
          item.transform[4] - selected[at - 1].transform[4] - selected[at - 1].width > font * 0.8))
    )
      return false
  }
  const next = raw.items.findIndex((i, at) => at > indices.at(-1)! && !!i.str.trim())
  const emptyEnd = raw.items
    .slice(indices.at(-1)! + 1, next < 0 ? undefined : next)
    .some((i) => !i.str.trim() && i.hasEOL)
  const ownerAt = (index: number, ordinary = false): LayoutPage['blocks'][number] | undefined => {
    const key = page.page + ':' + index,
      owners = page.blocks.filter((b) => b.items.includes(key))
    if (owners.length !== 1) return
    const owner = owners[0]
    if (
      owner.tableCell ||
      owner.risks.some((r) => r !== 'possible-continuation') ||
      (ordinary && (owner.sourceOnly || owner.preserve)) ||
      !owner.items.every((key, at) => {
        const [number, itemIndex] = key.split(':').map(Number),
          item = raw.items[itemIndex]
        return (
          number === page.page &&
          valid(raw, item) &&
          owner.originalStrings[at] === item.str &&
          page.blocks.filter((b) => b.items.includes(key)).length === 1
        )
      })
    )
      return
    return owner
  }
  if (lead || proofPart) {
    const after = raw.items[next]
    if (
      !valid(raw, after) ||
      !ownerAt(next, true) ||
      last.hasEOL ||
      emptyEnd ||
      Math.abs(after.height - font) >= font * 0.05 ||
      Math.abs(after.transform[5] - baseline) >= font * 0.05 ||
      after.transform[4] - last.transform[4] - last.width < 0 ||
      after.transform[4] - last.transform[4] - last.width > font * 0.8 ||
      (lead && !/^that(?:\s|[([])/u.test(after.str))
    )
      return false
  } else if (!last.hasEOL && !emptyEnd) return false
  if (whole || lead || proofPart) {
    // Context is read-only: the mathematical owners remain independently protected.
    const context = page.blocks.filter(
      (owner) =>
        owner !== block &&
        !owner.tableCell &&
        !owner.sourceOnly &&
        !owner.preserve &&
        owner.risks.every((risk) => risk === 'possible-continuation') &&
        Math.abs(owner.rect.x - first.transform[4]) < font * 2 &&
        owner.items.some((key) => {
          const [number, index] = key.split(':').map(Number),
            item = raw.items[index]
          return (
            number === page.page &&
            item &&
            Math.abs(item.transform[5] - baseline) > font * 0.75 &&
            Math.abs(item.transform[5] - baseline) < font * 3
          )
        })
    )
    const words = new Set<string>()
    for (const owner of context) {
      if (
        !owner.items.every((key, at) => {
          const [number, index] = key.split(':').map(Number),
            item = raw.items[index]
          return (
            number === page.page &&
            valid(raw, item) &&
            owner.originalStrings[at] === item.str &&
            page.blocks.filter((b) => b.items.includes(key)).length === 1
          )
        })
      )
        return false
      for (const key of owner.items) {
        const item = raw.items[Number(key.split(':')[1])]
        if (
          Math.abs(item.height - font) < font * 0.05 &&
          Math.abs(item.transform[5] - baseline) > font * 0.75 &&
          Math.abs(item.transform[5] - baseline) < font * 3 &&
          /^[A-Za-z ,.;:()0-9'’–-]+$/u.test(item.str)
        )
          for (const token of item.str.matchAll(/\b[A-Za-z]{2,}\b/gu))
            words.add(key + ':' + token.index)
      }
    }
    if (words.size < 6) return false
  } else {
    let end = indices[0] - 1
    while (end >= 0 && !raw.items[end].str.trim()) end--
    const previous = raw.items[end]
    if (
      !valid(raw, previous) ||
      !previous.hasEOL ||
      previous.fontName !== first.fontName ||
      Math.abs(previous.height - font) >= font * 0.05 ||
      /[.!?:;][”’"')\]]?$/u.test(previous.str) ||
      !/[a-z]{2,}$/u.test(previous.str)
    )
      return false
    let start = end
    while (start > 0 && !raw.items[start - 1].hasEOL) start--
    if (end - start > 48) return false
    const prior = raw.items.slice(start, end + 1).filter((i) => i.str.trim()),
      gap = previous.transform[5] - baseline
    if (
      !prior.length ||
      gap < font * 0.75 ||
      gap > font * 2 ||
      Math.abs(Math.min(...prior.map((i) => i.transform[4])) - first.transform[4]) > font * 0.15 ||
      (prior
        .filter(
          (i) =>
            i.fontName === first.fontName &&
            Math.abs(i.height - font) < font * 0.05 &&
            Math.abs(i.transform[5] - previous.transform[5]) < font * 0.05
        )
        .map((i) => i.str)
        .join(' ')
        .match(/\b[a-z]{2,}\b/gu)?.length ?? 0) < 6
    )
      return false
    for (let at = start; at <= end; at++) {
      const item = raw.items[at]
      if (!item.str.trim()) continue
      const key = page.page + ':' + at,
        owners = page.blocks.filter((b) => b.items.includes(key))
      if (
        !valid(raw, item) ||
        owners.length !== 1 ||
        owners[0].tableCell ||
        owners[0].risks.some((r) => r !== 'possible-continuation') ||
        owners[0].originalStrings[owners[0].items.indexOf(key)] !== item.str
      )
        return false
    }
    const preceding = page.blocks.filter((b) => b.items.includes(page.page + ':' + end))
    if (preceding.length !== 1 || preceding[0].sourceOnly || preceding[0].preserve) return false
  }
  const right = last.transform[4] + last.width,
    low = Math.min(...selected.map((i) => i.transform[5] + i.fontDescent! * i.height)),
    high = Math.max(...selected.map((i) => i.transform[5] + i.fontAscent! * i.height))
  if (
    raw.items.some((item, at) => {
      if (indices.includes(at) || !item.str.trim()) return false
      if (
        item.width !== 0 &&
        (item.transform[4] >= right || item.transform[4] + item.width <= first.transform[4])
      )
        return false
      if (!valid(raw, item, true)) return true
      return (
        item.transform[5] + item.fontDescent! * item.height < high &&
        item.transform[5] + item.fontAscent! * item.height > low
      )
    })
  )
    return false
  if (proofPart) {
    // A local three-part proof marker, not a general Roman-label or function exception.
    const parent = raw.items
      .flatMap((item, index) =>
        index < indices[0] &&
        /^Proof of (?:Proposition|Theorem|Lemma|Corollary) \d+(?:\.\d+)*\.$/u.test(item.str)
          ? [{ item, index }]
          : []
      )
      .at(-1)
    const peers = raw.items.flatMap((item, index) =>
      index > indices[0] && /^Parts \(ii\) and \(iii\)\.$/u.test(item.str) ? [{ item, index }] : []
    )
    if (!parent || peers.length !== 1) return false
    const peer = peers[0]
    if (
      !ownerAt(parent.index, true) ||
      !ownerAt(peer.index, true) ||
      [parent.item, peer.item].some(
        (item) =>
          !valid(raw, item) ||
          item.fontName !== first.fontName ||
          Math.abs(item.height - font) >= font * 0.05 ||
          Math.abs(item.transform[4] - first.transform[4]) > font * 0.15
      ) ||
      parent.item.transform[5] <= baseline ||
      peer.item.transform[5] >= baseline ||
      raw.items
        .slice(parent.index + 1, peer.index)
        .some(
          (item, at) =>
            item.str.trim() &&
            (!valid(raw, item) ||
              !ownerAt(parent.index + 1 + at) ||
              /^Proof(?: of)?\b/u.test(item.str))
        )
    )
      return false
    const following = raw.items.findIndex((item, index) => index > peer.index && !!item.str.trim())
    return (
      following > peer.index &&
      !!ownerAt(following, true) &&
      raw.items[following].transform[4] > peer.item.transform[4] + peer.item.width &&
      Math.abs(raw.items[following].transform[5] - peer.item.transform[5]) < font * 0.05
    )
  }
  const labels = rawPages.flatMap((p) =>
    p.rotation !== 0
      ? []
      : p.items.flatMap((item, index) =>
          item.str === labelText &&
          item.transform[4] > p.width * 0.7 &&
          valid(p, item) &&
          item.fontName === (whole ? first : selected[1]).fontName &&
          Math.abs(item.height - font) < font * 0.05 &&
          (!lead ||
            (() => {
              const owners = layoutPages
                .find((page) => page.page === p.page)
                ?.blocks.filter((b) => b.items.includes(p.page + ':' + index))
              return (
                owners?.length === 1 &&
                owners[0].items.length === 1 &&
                owners[0].source === labelText
              )
            })())
            ? [{ p, item, index }]
            : []
        )
  )
  if (labels.length !== 1) return false
  const target = labels[0],
    targetPage = layoutPages.find((p) => p.page === target.p.page),
    key = target.p.page + ':' + target.index
  if (!targetPage) return false
  const targetOwners = targetPage.blocks.filter((b) => b.items.includes(key))
  if (
    targetOwners.length !== 1 ||
    targetOwners[0].tableCell ||
    targetOwners[0].items.length !== 1 ||
    targetOwners[0].source !== labelText ||
    targetOwners[0].originalStrings[targetOwners[0].items.indexOf(key)] !== labelText
  )
    return false
  const labelRight = target.item.transform[4] + target.item.width,
    peers = rawPages
      .filter((p) => p.width === target.p.width && p.rotation === 0)
      .flatMap((p) =>
        p.items.filter(
          (i) =>
            /^\(\d{1,6}\)$/u.test(i.str) &&
            valid(p, i) &&
            i.fontName === target.item.fontName &&
            Math.abs(i.transform[4] + i.width - labelRight) < font * 0.1
        )
      )
  if (new Set(peers.map((i) => i.str)).size < 3) return false
  const labelTop =
      target.p.height - target.item.transform[5] - target.item.fontAscent! * target.item.height,
    labelBottom =
      target.p.height - target.item.transform[5] - target.item.fontDescent! * target.item.height
  return targetPage.blocks.some(
    (b) =>
      b !== block &&
      b !== targetOwners[0] &&
      !b.tableCell &&
      /[=≤≥]/u.test(b.source) &&
      symbolicExpression(b.source) &&
      [b.rect.x, b.rect.y, b.rect.right, b.rect.bottom].every(Number.isFinite) &&
      b.rect.x >= 0 &&
      b.rect.y >= 0 &&
      b.rect.right <= target.p.width &&
      b.rect.bottom <= target.p.height &&
      b.items.every((key, at) => {
        const [number, index] = key.split(':').map(Number),
          item = target.p.items[index]
        return (
          number === target.p.page &&
          valid(target.p, item, true) &&
          b.originalStrings[at] === item.str &&
          targetPage.blocks.filter((owner) => owner.items.includes(key)).length === 1
        )
      }) &&
      b.rect.x < target.item.transform[4] - font * 2 &&
      b.rect.bottom > labelTop &&
      b.rect.y < labelBottom &&
      b.rect.right < target.item.transform[4] - font * 2
  )
}

function nativeEquationReferenceProse(
  block: LayoutPage['blocks'][number],
  page: LayoutPage,
  rawPages: PdfLayoutPage[],
  layoutPages: LayoutPage[]
): boolean {
  if (nativeWrappedEquationReferenceTail(block, page, rawPages, layoutPages)) return true
  const match = /^[A-Za-z]{3,} \((\d+\.\d+)\)$/u.exec(block.source)
  if (
    !match ||
    block.tableCell ||
    block.lines.length !== 1 ||
    block.sourceOnly ||
    block.risks.length
  )
    return false
  const raw = rawPages.find((raw) => raw.page === page.page)
  if (!raw || raw.rotation !== 0) return false
  const indices = block.items.map((key) => Number(key.split(':')[1])).sort((a, b) => a - b)
  if (indices.length !== 2) return false
  const [word, ref] = indices.map((index) => raw.items[index])
  if (
    !word ||
    !ref ||
    !/^[A-Za-z]{3,}$/u.test(word.str) ||
    ref.str !== '(' + match[1] + ')' ||
    !word.fontName
  )
    return false
  const font = word.height,
    y = word.transform[5]
  const valid = (item: PdfLayoutPage['items'][number]): boolean =>
    item.dir === 'ltr' &&
    !!item.fontName &&
    item.width > 0 &&
    font > 0 &&
    [...item.transform, item.width, item.height].every(Number.isFinite) &&
    item.transform[0] > 0 &&
    item.transform[3] > 0 &&
    Math.abs(item.transform[1]) < 0.001 &&
    Math.abs(item.transform[2]) < 0.001 &&
    Math.abs(item.height - font) < font * 0.05 &&
    Math.abs(item.transform[5] - y) < font * 0.05
  if (!valid(word) || !valid(ref) || word.hasEOL) return false
  let previous = word,
    words = 0
  const used = new Set([indices[0]])
  for (let index = indices[0] + 1; index < raw.items.length; index++) {
    const item = raw.items[index]
    if (!item.str.trim()) {
      if (item.hasEOL) break
      continue
    }
    if (
      !valid(item) ||
      previous.hasEOL ||
      item.transform[4] - previous.transform[4] - previous.width < -font * 0.05 ||
      item.transform[4] - previous.transform[4] - previous.width > font * 0.8
    )
      break
    if (used.size === 1 && index !== indices[1]) return false
    if (index === indices[1] || /^\(\d+\.\d+\)$/u.test(item.str)) {
      used.add(index)
      previous = item
      continue
    }
    if (!/^[A-Za-z\s,.;'’-]+$/u.test(item.str) || item.fontName !== word.fontName) break
    const owners = page.blocks.filter((b) => b.items.includes(page.page + ':' + index))
    if (
      owners.length !== 1 ||
      owners[0].tableCell ||
      owners[0].sourceOnly ||
      owners[0].risks.some((r) => r === 'formula-extraction' || r === 'metadata-extraction')
    )
      return false
    words += (item.str.match(/[A-Za-z]{2,}/gu) ?? []).length
    used.add(index)
    previous = item
  }
  if (words < 3) return false
  if (
    raw.items.some(
      (item, index) =>
        !used.has(index) &&
        item.str.trim() &&
        item.transform[4] < previous.transform[4] + previous.width &&
        item.transform[4] + item.width > word.transform[4] &&
        Math.abs(item.transform[5] - y) < font * 0.5
    )
  )
    return false
  const targets = layoutPages.flatMap((p) =>
    p.blocks
      .filter(
        (b) => b.source === '(' + match[1] + ')' && b.items.length === 1 && b.rect.x > p.width * 0.7
      )
      .map((b) => ({ page: p, block: b }))
  )
  if (targets.length !== 1) return false
  const target = targets[0],
    label = target.block
  const peers = layoutPages
    .filter((p) => p.width === target.page.width)
    .flatMap((p) => p.blocks)
    .filter(
      (b) =>
        /^\(\d+\.\d+\)$/u.test(b.source) &&
        b.items.length === 1 &&
        Math.abs(b.rect.right - label.rect.right) < font * 0.1
    )
  if (new Set(peers.map((b) => b.source)).size < 3) return false
  return target.page.blocks.some(
    (b) =>
      b !== label &&
      b.rect.right < label.rect.x - font * 2 &&
      b.rect.bottom > label.rect.y &&
      b.rect.y < label.rect.bottom &&
      /[=≤≥]/u.test(b.source) &&
      symbolicExpression(b.source)
  )
}

// Classify the existing prefix owner only. Its original row remains split,
// including every citation/script Source and independently protected formula.
function nativeAlphabeticCitationLeadIn(
  block: LayoutPage['blocks'][number],
  page: LayoutPage,
  rawPages: PdfLayoutPage[]
): boolean {
  // A separate closed locator citation, not a proper-name or bracket whitelist.
  const located = /^[A-Z][a-z]{1,19} \[$/u.test(block.source)
  if (
    block.items.length !== 1 ||
    block.lines.length !== 1 ||
    block.tableCell ||
    block.sourceOnly ||
    block.preserve ||
    block.risks.length ||
    (!located && !/^[a-z]{3,20} \[$/u.test(block.source)) ||
    /^(?:sin|cos|tan|log|ln|exp|min|max|argmin|argmax|det|relu|softmax|sigmoid|norm|var) /u.test(
      located ? block.source.toLowerCase() : block.source
    )
  )
    return false
  const raw = rawPages.find((p) => p.page === page.page)
  if (!raw || raw.rotation !== 0 || !raw.nativeSectionFontEvidence?.complete) return false
  const index = Number(block.items[0].split(':')[1]),
    first = raw.items[index]
  if (!first || first.str !== block.source || first.hasEOL || !first.fontName) return false
  const font = first.height
  const valid = (item: PdfLayoutTextItem, foreignZeroAdvance = false): boolean => {
    const witness =
      raw.nativeSectionFontEvidence?.complete &&
      raw.nativeSectionFontEvidence.fonts[item.fontName ?? '']
    return (
      !!witness &&
      witness.nativeMetrics &&
      witness.ascent === item.fontAscent &&
      witness.descent === item.fontDescent &&
      item.fontVertical === false &&
      item.dir === 'ltr' &&
      item.transform.length === 6 &&
      [...item.transform, item.width, item.height, item.fontAscent, item.fontDescent].every(
        Number.isFinite
      ) &&
      (item.width > 0 || (foreignZeroAdvance && item.width === 0)) &&
      item.height > 0 &&
      item.transform[0] > 0 &&
      Math.abs(item.transform[0] - item.height) < item.height * 0.05 &&
      item.transform[3] === item.height &&
      item.transform[1] === 0 &&
      item.transform[2] === 0 &&
      (!located ||
        (item.transform[4] >= 0 &&
          item.transform[4] + item.width <= raw.width &&
          item.transform[5] + item.fontDescent! * item.height >= 0 &&
          item.transform[5] + item.fontAscent! * item.height <= raw.height))
    )
  }
  const body = (item: PdfLayoutTextItem): boolean =>
    valid(item) &&
    item.fontName === first.fontName &&
    Math.abs(item.height - font) < font * 0.05 &&
    Math.abs(item.transform[5] - first.transform[5]) < font * 0.05
  if (!body(first)) return false
  const end = raw.items.findIndex((item, at) => at >= index && item.hasEOL)
  if (end < index || end - index > 48) return false
  const row = raw.items
    .slice(index, end + 1)
    .map((item, offset) => ({ item, index: index + offset }))
    .filter(({ item }) => item.str.trim())
  if (
    row.some(
      ({ item }) =>
        item.fontName === first.fontName &&
        Math.abs(item.height - font) < font * 0.05 &&
        Math.abs(item.transform[5] - first.transform[5]) >= font * 0.05
    )
  )
    return false
  const locator =
    /^, (?:Theorem|Lemma|Proposition|Corollary|Section) \d{1,4}(?:\.\d{1,3}){0,3}\],(?: |$)/u
  const close = row.findIndex(({ item }) =>
    located
      ? locator.test(item.str)
      : /^\][.,;:]? (?:[A-Za-z]{2,}\b|a [a-z]{3,}(?: [a-z]{3,}){2,}\b)/u.test(item.str)
  )
  if (close < 2 || close > 12 || !body(row[close].item)) return false
  const reference = row.slice(1, close)
  const bibliographyKeys =
    /^[A-Z][A-Za-z]{1,11}\+?\d{2,4}[a-z]?(?:,[A-Z][A-Za-z]{1,11}\+?\d{2,4}[a-z]?)*$/u
  if (!bibliographyKeys.test(reference.map(({ item }) => item.str).join(''))) return false
  if (located) {
    if (row.some(({ item }) => !valid(item))) return false
    const suffix = row
      .slice(close)
      .filter(({ item }) => body(item))
      .map(({ item }, at) => (at === 0 ? item.str.replace(locator, '') : item.str))
      .join(' ')
    if ((suffix.match(/\b[a-z]{2,}\b/gu)?.length ?? 0) < 6) return false
  }
  const citation = row.slice(0, close + 1)
  for (const [at, { item }] of citation.entries()) {
    const previous = citation[at - 1]?.item,
      next = citation[at + 1]?.item
    if (!body(item)) {
      // Only the original raised plus between the author letters and year.
      if (
        !valid(item) ||
        item.str !== '+' ||
        !previous ||
        !next ||
        !/^[A-Z][A-Za-z]{1,11}$/u.test(previous.str) ||
        !/^\d{2,4}[a-z]?$/u.test(next.str) ||
        !body(previous) ||
        !body(next) ||
        item.height < font * 0.6 ||
        item.height >= font * 0.85 ||
        item.transform[5] - first.transform[5] < font * 0.2 ||
        item.transform[5] - first.transform[5] > font * 0.5
      )
        return false
    }
    if (
      previous &&
      (item.transform[4] - previous.transform[4] - previous.width < -font * 0.05 ||
        item.transform[4] - previous.transform[4] - previous.width > font * 0.5)
    )
      return false
  }
  let priorEnd = index - 1
  while (priorEnd >= 0 && !raw.items[priorEnd].str.trim()) priorEnd--
  const previous = raw.items[priorEnd]
  if (
    !previous?.hasEOL ||
    !valid(previous) ||
    previous.fontName !== first.fontName ||
    (!located && /[.!?:;][”’"')\]]?$/u.test(previous.str))
  )
    return false
  let priorStart = priorEnd
  while (priorStart > 0 && !raw.items[priorStart - 1].hasEOL) priorStart--
  if (priorEnd - priorStart > 48) return false
  const prior = raw.items.slice(priorStart, priorEnd + 1)
  if (located && prior.some((item) => item.str.trim() && !valid(item))) return false
  // A complete linked author/year citation can finish an unfinished prose row.
  // It supplies context only; that citation's original owner is never released.
  const closedReferenceContext = (() => {
    if (previous.str !== ']') return false
    const parts = prior.filter((item) => item.str.trim()),
      open = parts.findLastIndex((item) => / \[$/u.test(item.str))
    if (open < 0 || open >= parts.length - 2) return false
    const tail = parts.slice(open),
      key = tail
        .slice(1, -1)
        .map((item) => item.str)
        .join('')
    return (
      bibliographyKeys.test(key) &&
      tail.every((item, at) => {
        const preceding = tail[at - 1]
        return (
          valid(item) &&
          item.fontName === first.fontName &&
          Math.abs(item.height - font) < font * 0.05 &&
          Math.abs(item.transform[5] - previous.transform[5]) < font * 0.05 &&
          (!preceding ||
            (item.transform[4] - preceding.transform[4] - preceding.width >= -font * 0.05 &&
              item.transform[4] - preceding.transform[4] - preceding.width < font * 0.5))
        )
      })
    )
  })()
  // The native sentence ending before "By <author>'s" proves only that prose
  // tail. Earlier =0/variables/negations keep their independent original roles.
  const authorPossessiveContext = /(?:^|[.!?]\s+)By \p{Lu}[\p{L}’'-]{1,39}['’]s$/u.test(
    previous.str
  )
  if (
    !located &&
    !/[a-z]{2,}[-‐]?$/u.test(previous.str) &&
    !closedReferenceContext &&
    !authorPossessiveContext
  )
    return false
  const gap = previous.transform[5] - first.transform[5]
  if (
    gap < font * 0.75 ||
    gap > font * 2 ||
    Math.abs(
      Math.min(...prior.filter((i) => i.str.trim()).map((i) => i.transform[4])) - first.transform[4]
    ) >
      font * 0.15 ||
    (prior
      .filter(
        (i) =>
          i.fontName === first.fontName &&
          (!located ||
            (Math.abs(i.height - font) < font * 0.05 &&
              Math.abs(i.transform[5] - previous.transform[5]) < font * 0.05))
      )
      .map((i) => i.str)
      .join(' ')
      .match(/\b[a-z]{2,}\b/gu)?.length ?? 0) < 6
  )
    return false
  const owned = new Set<number>()
  for (let at = priorStart; at <= end; at++) {
    const item = raw.items[at]
    if (!item.str.trim()) continue
    const key = page.page + ':' + at,
      owners = page.blocks.filter((b) => b.items.includes(key))
    if (
      owners.length !== 1 ||
      owners[0].tableCell ||
      owners[0].risks.some((risk) => risk !== 'possible-continuation') ||
      owners[0].originalStrings[owners[0].items.indexOf(key)] !== item.str
    )
      return false
    owned.add(at)
  }
  if (
    [priorEnd, row[close].index].some((at) =>
      page.blocks.some((b) => b.items.includes(page.page + ':' + at) && b.sourceOnly)
    )
  )
    return false
  // Use the actual font envelopes, not an invented half-em baseline window.
  // A neighboring extensible operator can have a very different native ascent.
  const right = row[close].item.transform[4] + row[close].item.width
  const low = Math.min(
      ...citation.map(({ item }) => item.transform[5] + item.fontDescent! * item.height)
    ),
    high = Math.max(
      ...citation.map(({ item }) => item.transform[5] + item.fontAscent! * item.height)
    )
  return !raw.items.some((item, at) => {
    if (owned.has(at) || !item.str.trim()) return false
    // A foreign zero-advance mark is never empty paint or an X-domain proof.
    // Only its actual font/transform's strictly separate Y-domain can exclude it.
    if (item.width === 0) {
      if (!valid(item, true)) return true
      return (
        item.transform[5] + item.fontDescent! * item.height < high &&
        item.transform[5] + item.fontAscent! * item.height > low
      )
    }
    if (item.transform[4] >= right || item.transform[4] + item.width <= first.transform[4])
      return false
    if (!valid(item)) return true
    return (
      item.transform[5] + item.fontDescent! * item.height < high &&
      item.transform[5] + item.fontAscent! * item.height > low
    )
  })
}

// A short author-year citation can close prose before the next sentence on the same row.
function nativeAuthorYearSentenceTail(
  block: LayoutPage['blocks'][number],
  page: LayoutPage,
  rawPages: PdfLayoutPage[]
): boolean {
  if (
    block.tableCell ||
    block.sourceOnly ||
    block.risks.length ||
    block.lines.length !== 1 ||
    block.items.length !== 1 ||
    !/^[a-z]{4,} \[[A-Z]{2,4}\d{2}\]\.$/u.test(block.source)
  )
    return false

  const raw = rawPages.find((candidate) => candidate.page === page.page)
  if (!raw || raw.rotation !== 0) return false

  const index = Number(block.items[0].split(':')[1]),
    [before, tail, space, after] = raw.items.slice(index - 1, index + 3)
  if (
    ![before, tail, after].every(nativeHorizontalSourceItem) ||
    tail.str !== block.source ||
    before.hasEOL !== true ||
    tail.hasEOL !== false ||
    !/^ +$/u.test(space?.str ?? '') ||
    space.hasEOL !== false ||
    space.dir !== 'ltr' ||
    space.height !== 0 ||
    space.transform.length !== 6 ||
    ![space.width, ...space.transform].every(Number.isFinite) ||
    space.transform[1] !== 0 ||
    space.transform[2] !== 0 ||
    !/[a-z]{3,} [a-z]{3,}$/u.test(before.str) ||
    !/^[A-Z][a-z]+ (?:[a-z]{2,} ){2}/u.test(after.str)
  )
    return false

  const h = tail.height,
    [, , , , x, y] = tail.transform,
    right = x + tail.width,
    pitch = before.transform[5] - y,
    gap = after.transform[4] - right
  if (
    ![before, after].every((item) => item.fontName === tail.fontName && item.height === h) ||
    space.fontName !== tail.fontName ||
    Math.abs(space.transform[5] - y) > h * 0.03 ||
    Math.abs(space.transform[4] - right) > h * 0.03 ||
    Math.abs(space.width - gap) > h * 0.03 ||
    Math.abs(after.transform[5] - y) > h * 0.03 ||
    pitch < h ||
    pitch > h * 1.5 ||
    gap < h * 0.25 ||
    gap > h * 0.8 ||
    before.width < h * 15 ||
    before.transform[4] <= x + h * 2
  )
    return false

  const neighbors = [index - 1, index + 2].map((at) =>
    page.blocks.filter((owner) => owner.items.includes(`${page.page}:${at}`))
  )
  const domain = nativeProseProofDomain([tail])
  return (
    neighbors.every(
      ([owner, duplicate]) =>
        owner &&
        !duplicate &&
        !owner.tableCell &&
        !owner.sourceOnly &&
        owner.lines.length >= 3 &&
        owner.risks.every((risk) => risk === 'possible-continuation') &&
        Math.abs(owner.rect.x - x) < h * 0.03
    ) &&
    Math.abs(neighbors[0][0].rect.right - before.transform[4] - before.width) < h * 0.03 &&
    !!domain &&
    !raw.items.some((item) => item !== tail && nativeProseRowOverlap(item, domain))
  )
}

function nativeSquareCitationProse(
  block: LayoutPage['blocks'][number],
  page: LayoutPage,
  rawPages: PdfLayoutPage[]
): boolean {
  if (
    block.items.length !== 1 ||
    block.lines.length !== 1 ||
    block.tableCell ||
    block.sourceOnly ||
    block.risks.length
  )
    return false
  if (
    !/\[\d+\]/u.test(block.source) ||
    !/^[A-Za-z ,.'’-]+$/u.test(block.source.replace(/\[\d+\]/gu, '')) ||
    !/^[A-Za-z]{3,}/u.test(block.source)
  )
    return false
  const raw = rawPages.find((p) => p.page === page.page)
  if (!raw || raw.rotation !== 0) return false
  const index = Number(block.items[0].split(':')[1]),
    current = raw.items[index]
  if (!current || current.str !== block.source || !current.hasEOL || !current.fontName) return false
  const font = current.height,
    x = current.transform[4],
    y = current.transform[5]
  const preceding = raw.items
    .map((item, index) => ({ item, index }))
    .slice(0, index)
    .filter((x) => x.item.str.trim())
    .slice(-2)
  if (preceding.length !== 2) return false
  const [peer, previous] = preceding.map((x) => x.item)
  const valid = (item: PdfLayoutPage['items'][number]): boolean =>
    item.dir === 'ltr' &&
    item.hasEOL === true &&
    item.fontName === current.fontName &&
    [...item.transform, item.width, item.height].every(Number.isFinite) &&
    font > 0 &&
    item.width > 0 &&
    item.transform[0] > 0 &&
    item.transform[3] > 0 &&
    Math.abs(item.transform[1]) < 0.001 &&
    Math.abs(item.transform[2]) < 0.001 &&
    Math.abs(item.height - font) < font * 0.05
  if (
    Math.abs(previous.transform[4] - x) > font * 0.05 ||
    peer.transform[4] < x - font * 0.05 ||
    peer.transform[4] > x + font * 1.5 ||
    ![peer, previous, current].every(valid) ||
    /[.!?:;][”’"')\]]?$/u.test(previous.str.trim())
  )
    return false
  const gap = previous.transform[5] - y,
    oldGap = peer.transform[5] - previous.transform[5]
  if (
    gap < font * 0.75 ||
    gap > font * 2 ||
    Math.abs(gap - oldGap) > font * 0.05 ||
    current.width > previous.width + font * 0.05 ||
    Math.abs(peer.transform[4] + peer.width - previous.transform[4] - previous.width) > font * 0.05
  )
    return false
  for (const { item, index } of preceding) {
    if ((item.str.match(/[A-Za-z]{3,}/gu) ?? []).length < 6 || symbolicExpression(item.str))
      return false
    const owners = page.blocks.filter((b) => b.items.includes(page.page + ':' + index))
    if (
      owners.length !== 1 ||
      owners[0].tableCell ||
      owners[0].sourceOnly ||
      owners[0].risks.some((r) => r === 'formula-extraction' || r === 'metadata-extraction')
    )
      return false
  }
  const used = new Set([...preceding.map((x) => x.index), index])
  return !raw.items.some(
    (item, i) =>
      !used.has(i) &&
      item.str.trim() &&
      item.transform[4] < x + previous.width &&
      item.transform[4] + item.width > x &&
      item.transform[5] > y - font * 0.5 &&
      item.transform[5] < peer.transform[5] + font * 0.5
  )
}

// Font/metric source bounds only; no glyph repaint or citation reconstruction.
function nativeReferenceText(items: PdfLayoutTextItem[]): boolean {
  return (
    items.length > 0 &&
    items.length <= 4096 &&
    !!nativeProseProofDomain(items) &&
    items.every(
      (i) =>
        nativeContentsUpright(i) &&
        i.width > 0 &&
        !!i.fontName &&
        i.fontAscent! > 0 &&
        i.fontAscent! <= 1 &&
        i.fontDescent! >= -1 &&
        i.fontDescent! <= 0
    )
  )
}

function nativeReferenceRows(
  items: PdfLayoutTextItem[],
  allowOverprintedAccent = false,
  allowOverprintedGrave = false,
  allowLocatorPeriod = false
): PdfLayoutTextItem[][] | undefined {
  if (nativeReferenceText(items))
    return nativeOrderedRows(
      items,
      allowOverprintedAccent,
      allowOverprintedGrave,
      allowLocatorPeriod
    )
}

// A printed Python listing can continue over page headers. Preserve its native
// rows only when the docstring and executable entry point bound a fixed-pitch block.
function nativePythonListingItems(pages: PdfLayoutPage[]): Set<string> {
  const quoted = /^(?:"""|''')$/u,
    importLine = /^from [A-Za-z_]\w*(?:\.[A-Za-z_]\w*)* import [A-Za-z_]/u,
    entryPoint = /^if __name__ == (["'])__main__\1:$/u,
    x = (item: PdfLayoutTextItem): number => item.transform[4],
    y = (item: PdfLayoutTextItem): number => item.transform[5]
  const visible = (page: PdfLayoutPage): { item: PdfLayoutTextItem; key: string }[] =>
    page.items.flatMap((item, i) => (item.str.trim() ? [{ item, key: `${page.page}:${i}` }] : []))
  for (const [at, page] of pages.entries()) {
    if (page.rotation || !page.items.some((item) => quoted.test(item.str))) continue
    const first = visible(page),
      start = first.findIndex(
        ({ item }, i) =>
          quoted.test(item.str) && /^[\w-]+\.py(?: \(.*\)\.)?$/u.test(first[i - 1]?.item.str ?? '')
      )
    if (start < 1) continue
    const opening = first[start].item,
      caption = first[start - 1].item,
      em = opening.height,
      advance = opening.width / 3,
      rail = x(opening),
      pitch = em * 1.2,
      near = (a: number, b: number): boolean => Math.abs(a - b) < em * 0.05
    if (
      ![caption, opening].every(nativeHorizontalSourceItem) ||
      !near(x(caption), rail) ||
      caption.fontName === opening.fontName ||
      y(caption) - y(opening) < em ||
      y(caption) - y(opening) > em * 1.4 ||
      advance < em * 0.45 ||
      advance > em * 0.62
    )
      continue
    const owners = new Set<string>(),
      rows: PdfLayoutTextItem[][] = []
    for (let n = at; n < Math.min(at + 3, pages.length); n++) {
      const current = pages[n],
        continued = n !== at,
        raw = continued ? visible(current) : first,
        startAt = continued ? 2 : start,
        stop = raw.findIndex(({ item }, i) => i >= startAt && item.str === 'References'),
        cells = raw.slice(startAt, stop < 0 ? undefined : stop),
        words = cells.map(({ item }) => item),
        [top, bottom] = [words[0], words.at(-1)]
      if (
        !top ||
        !bottom ||
        current.rotation ||
        current.page !== page.page + n - at ||
        current.width !== page.width ||
        current.height !== page.height ||
        (continued &&
          (!raw
            .slice(0, 2)
            .some(({ item }) => item.str === String(current.page) && item.width < em) ||
            !raw
              .slice(0, 2)
              .every(
                ({ item }) =>
                  nativeHorizontalSourceItem(item) &&
                  item.height < em &&
                  item.fontName !== opening.fontName &&
                  near(y(item), y(raw[0].item)) &&
                  y(item) > current.height * 0.9 &&
                  y(item) - y(top) > em * 1.75
              ) ||
            y(top) < current.height * 0.83)) ||
        (stop < 0 && y(bottom) > current.height * 0.13) ||
        words.some(
          (item) =>
            !nativeHorizontalSourceItem(item) ||
            !near(item.height, em) ||
            x(item) < rail - em * 0.05 ||
            x(item) + item.width > current.width * 0.95 ||
            Math.abs(item.width / [...item.str].length - advance) > advance * 0.02
        )
      )
        break
      const currentRows = nativeOrderedRows(words)
      if (
        !currentRows ||
        currentRows.some(([item], row) => {
          if (!row) return false
          const gap = y(currentRows[row - 1][0]) - y(item)
          return (
            gap < pitch * 0.95 || gap > pitch * 3.05 || !near(gap, Math.round(gap / pitch) * pitch)
          )
        })
      )
        break
      for (const { key } of cells) owners.add(key)
      rows.push(...currentRows)
      if (stop < 0) continue
      const text = rows.map((row) => row.map((item) => item.str).join('')),
        close = text.indexOf(opening.str, 1),
        last = text.length - 1,
        definition = text[last].slice(0, -2),
        bibliography = raw[stop].item
      if (
        close > 1 &&
        close + 3 < last &&
        !text.slice(close + 1).includes(opening.str) &&
        importLine.test(text[close + 1]) &&
        entryPoint.test(text[last - 1]) &&
        /^[A-Za-z_]\w*\(\)$/u.test(text[last]) &&
        text.slice(close + 2, last - 1).some((line) => line.startsWith(`def ${definition}(`)) &&
        [rows[close][0], rows[close + 1][0], rows[last - 1][0], bottom].every(
          (item) => item.fontName === opening.fontName
        ) &&
        [rows[close][0], rows[close + 1][0], rows[last - 1][0]].every((item) =>
          near(x(item), rail)
        ) &&
        x(bottom) > rail + em &&
        near(y(rows[last - 1][0]) - y(bottom), pitch) &&
        nativeHorizontalSourceItem(bibliography) &&
        bibliography.fontName !== opening.fontName &&
        bibliography.height > em &&
        y(bottom) - y(bibliography) > em * 2
      )
        return owners
      break
    }
  }
  return new Set()
}

function nativeOrderedRows(
  items: PdfLayoutTextItem[],
  allowOverprintedAccent = false,
  allowOverprintedGrave = false,
  allowLocatorPeriod = false
): PdfLayoutTextItem[][] | undefined {
  const rows: PdfLayoutTextItem[][] = []
  for (const item of items) {
    const row = rows.at(-1),
      last = row?.at(-1)
    if (last && Math.abs(last.transform[5] - item.transform[5]) < item.height * 0.01) {
      const overlap = last.transform[4] + last.width - item.transform[4]
      if (
        overlap > item.height * 0.05 &&
        !(
          allowLocatorPeriod &&
          overlap < item.height * 0.07 &&
          item.str === '.' &&
          item.hasEOL &&
          item.fontName === last.fontName &&
          nativeReferencePreprintLocator.test(last.str)
        ) &&
        !(
          allowOverprintedAccent &&
          overlap < item.height * 0.6 &&
          item.transform[4] > last.transform[4] &&
          /^[\p{L}]/u.test(item.str) &&
          (/[˚¨˝]$/u.test(last.str) || (allowOverprintedGrave && /\p{Ll}`$/u.test(last.str)))
        )
      )
        return
      row!.push(item)
    } else {
      if (last && item.transform[5] >= last.transform[5] - item.height * 0.5) return
      rows.push([item])
    }
  }
  return rows
}

// The second column of a complete decimal bibliography may be above its heading.
// Only assign ownership to native runs inside its closed, independently numbered records.
function nativeTerminalDecimalReferenceContinuation(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): LayoutUnit[] {
  const page = pages.at(-1)
  if (!page || page.rotation || page.page !== pageCount) return []
  const middle = page.width / 2
  const headings = units.filter(
    (unit) =>
      /^References$/iu.test(unit.source) &&
      unit.preserve === 'reference' &&
      unit.fragments.length === 1 &&
      unit.fragments[0].page === page.page &&
      unit.fragments[0].rect.right < middle
  )
  if (headings.length !== 1) return []
  const heading = headings[0]
  const anchor = Number(heading.items.at(-1)?.split(':')[1])
  const entries = page.items.flatMap((item, index) =>
    index > anchor && item.str.trim() ? [{ item, index, key: `${page.page}:${index}` }] : []
  )
  const separateNumbers = entries[0]?.item.str === '1.'
  if (!separateNumbers) {
    const folio = entries.pop()
    if (
      !folio ||
      folio.item.str !== String(page.page) ||
      Math.abs(folio.item.transform[4] + folio.item.width / 2 - middle) > page.width * 0.03 ||
      folio.item.transform[5] > page.height * 0.1 ||
      !units.some(
        (unit) => unit.sourceOnly && unit.items.length === 1 && unit.items[0] === folio.key
      )
    )
      return []
  }
  const split = entries.findIndex(({ item }) => item.transform[4] > middle)
  if (split <= 0) return []
  const left = entries.slice(0, split),
    otherColumn = entries.slice(split)
  const caption =
    separateNumbers &&
    units.find(
      (unit) =>
        !unit.sourceOnly &&
        /^Fig\. 1\. \p{Lu}/u.test(unit.source) &&
        unit.fragments.length === 1 &&
        unit.fragments[0].page === page.page &&
        unit.fragments[0].rect.x > middle &&
        otherColumn.some(({ key }) => unit.items[0] === key)
    )
  const captionAt = caption ? otherColumn.findIndex(({ key }) => key === caption.items[0]) : -1
  const right = captionAt >= 0 ? otherColumn.slice(0, captionAt) : otherColumn
  const beforeCaption = captionAt >= 0
  const size = left[0].item.height
  // Some templates print the complete initial and surname at the hanging rail.
  // Reuse the independently protected lead and tail when validating that format.
  const wideHanging =
    separateNumbers &&
    !beforeCaption &&
    left[1]?.item.transform[4] - left[0].item.transform[4] > size * 2.2
  const authors =
    /^\p{Lu}\.(?:[-–]\p{Lu}\.)?(?: \p{Lu}\.){0,3} (?:(?:da|de|del|van|von) )?\p{Lu}\p{Ll}+/u
  const longerRecordEnd =
    /(?:\([^()]*\b(?:18|19|20)\d{2}\), pp\. \d{1,4}[–-]\d{1,4}\.|\b(?:18|19|20)\d{2}\), \d{1,2}(?:st|nd|rd|th) ed\.)$/u
  const mark = separateNumbers ? /^([1-9]\d{0,2})\.$/u : /^([1-9]\d{0,2})\.\s+\p{Lu}\./u
  type Marker = { index: number; number: number; item: PdfLayoutTextItem }
  const starts = (lane: typeof entries): Marker[] =>
    lane.flatMap((part, index) => {
      const m = mark.exec(part.item.str)
      return m ? [{ index, number: Number(m[1]), item: part.item }] : []
    })
  const first = starts(left),
    continued = starts(right)
  const recordsClose = (lane: typeof entries, markers: Marker[]): boolean =>
    markers.every((marker, n) => {
      const record = lane.slice(marker.index, markers[n + 1]?.index)
      const text = record.map(({ item }) => item.str).join(' ')
      if (!separateNumbers) return /\((?:18|19|20)\d{2}\)\.\s*\(docu(?:-\s*)?ment\)$/u.test(text)
      const number = marker.item,
        author = record[1]?.item,
        offset = author && author.transform[4] - number.transform[4]
      return (
        !!author &&
        !number.hasEOL &&
        author.fontName === number.fontName &&
        (wideHanging
          ? authors.test(author.str)
          : beforeCaption
            ? /^\p{Lu}\.(?: \p{Lu}\.){0,2} \p{Lu}\p{Ll}+/u.test(author.str)
            : /^(?:\p{Lu}\.){1,3}$/u.test(author.str)) &&
        Math.abs(author.transform[5] - number.transform[5]) < size * 0.01 &&
        offset >= size * (wideHanging ? 2.2 : beforeCaption ? 1.8 : 0.8) &&
        offset <= size * (wideHanging ? 2.5 : beforeCaption ? 2.2 : 1.6) &&
        (/(?:\(|\s)(?:18|19|20)\d{2}\)\.$/u.test(text) ||
          (wideHanging && longerRecordEnd.test(text)))
      )
    })
  if (
    first.length < (beforeCaption ? 8 : 4) ||
    (beforeCaption ? continued.length !== 2 : continued.length < 3) ||
    first[0].index !== 0 ||
    continued[0].index !== 0 ||
    [...first, ...continued].some(
      ({ number, item }, index) => number !== index + 1 || item.fontName !== left[0].item.fontName
    ) ||
    left.some(({ item }) => item.transform[4] + item.width >= middle) ||
    right.some(({ item }) => item.transform[4] <= middle) ||
    left.at(-1)!.item.transform[5] > page.height * 0.15 ||
    right[0].item.transform[5] < page.height * 0.87 ||
    page.height - right[0].item.transform[5] >= heading.fragments[0].rect.y ||
    !recordsClose(left, beforeCaption ? first.slice(-2) : first) ||
    !recordsClose(right, continued)
  )
    return []
  const leftKeys = new Set(left.map(({ key }) => key))
  const protectedKeys = new Set(
    units
      .filter((unit) => unit.sourceOnly && unit.preserve === 'reference')
      .flatMap((unit) => unit.items)
  )
  if (
    [...leftKeys].some((key) => !protectedKeys.has(key)) ||
    // A list without a folio must close on independently preserved records.
    (separateNumbers &&
      !beforeCaption &&
      (continued.length < 6 ||
        continued.slice(-2).some((marker) => !protectedKeys.has(right[marker.index].key))))
  )
    return []
  const rows = nativeReferenceRows(right.map(({ item }) => item)),
    markers = new Set(continued.map(({ item }) => item)),
    hanging = rows?.find((row) => !markers.has(row[0]))?.[0].transform[4]
  const laneWidth = (lane: typeof entries): number =>
    lane.reduce((edge, { item }) => Math.max(edge, item.transform[4] + item.width), 0) -
    lane[0].item.transform[4]
  if (
    !rows ||
    hanging === undefined ||
    (beforeCaption
      ? rows.length !== 4 ||
        markers.has(rows[1][0]) ||
        !markers.has(rows[2][0]) ||
        markers.has(rows[3][0]) ||
        Math.abs(laneWidth(left) - laneWidth(right)) > size * 0.2 ||
        otherColumn[captionAt].item.transform[4] - right[0].item.transform[4] < size * 0.65 ||
        otherColumn[captionAt].item.transform[4] - right[0].item.transform[4] > size * 1.35 ||
        rows[3][0].transform[5] - otherColumn[captionAt].item.transform[5] < size * 1.6 ||
        rows[3][0].transform[5] - otherColumn[captionAt].item.transform[5] > size * 2.2
      : rows.filter((row) => !markers.has(row[0])).length < 4) ||
    rows.some(([item], index) => {
      const indent = hanging - item.transform[4],
        gap = index ? rows[index - 1][0].transform[5] - item.transform[5] : size * 1.2
      return (
        (item.fontName !== left[0].item.fontName &&
          !(separateNumbers && !markers.has(item) && /^\d{1,4}$/u.test(item.str))) ||
        Math.abs(item.height - size) > size * 0.03 ||
        gap < size * 1.05 ||
        gap > size * 1.45 ||
        (markers.has(item) ? indent < size || indent > size * 2.5 : Math.abs(indent) > size * 0.05)
      )
    })
  )
    return []
  const wanted = new Map(right.map(({ key, item }) => [key, item.str]))
  const owners = units.filter((unit) => unit.items.some((key) => wanted.has(key)))
  if (
    owners.some(
      (unit) =>
        unit.items.length !== unit.originalStrings.length ||
        unit.items.some((key, index) => wanted.get(key) !== unit.originalStrings[index])
    )
  )
    return []
  const keys = owners.flatMap((unit) => unit.items)
  return keys.length === wanted.size && new Set(keys).size === wanted.size
    ? owners.filter(
        (unit) =>
          !unit.sourceOnly ||
          (beforeCaption &&
            unit.preserve === 'formula' &&
            /^\d+, \d+ \((?:18|19|20)\d{2}\)\.$/u.test(unit.source))
      )
    : []
}

// A flush-left bibliography can turn into a higher column without repeating
// its heading. Match the closed records and the independently protected tail.
function nativeFlushDecimalReferenceContinuation(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): LayoutUnit[] {
  const page = pages.at(-1)
  if (!page || page.rotation || page.page !== pageCount) return []
  const splitX = page.width / 2,
    headings = units.filter(
      (unit) =>
        unit.source === 'REFERENCES' &&
        unit.sourceOnly &&
        unit.preserve === 'reference' &&
        unit.items.length === 1 &&
        unit.fragments.length === 1 &&
        unit.fragments[0].page === page.page &&
        unit.fragments[0].rect.right < splitX
    )
  if (headings.length !== 1) return []
  const [heading] = headings,
    anchor = Number(heading.items[0].split(':')[1]),
    label = page.items[anchor],
    runs = page.items.flatMap((item, n) =>
      n > anchor && item.str.trim() ? [{ item, key: `${page.page}:${n}` }] : []
    ),
    division = runs.findIndex(({ item }) => item.transform[4] > splitX),
    left = runs.slice(0, division),
    right = runs.slice(division),
    h = runs[0]?.item.height,
    near = (a: number, b: number): boolean => Math.abs(a - b) < h * 0.035,
    sourceReferenceKeys = new Set(
      units
        .filter((unit) => unit.sourceOnly && unit.preserve === 'reference')
        .flatMap((unit) => unit.items)
    )
  if (
    division <= 0 ||
    !h ||
    !nativeHorizontalSourceItem(label) ||
    label.str !== heading.source ||
    runs[0].item.str !== '1.' ||
    label.height < h * 1.2 ||
    label.height > h * 1.5 ||
    !near(label.transform[4], left[0].item.transform[4]) ||
    left.some(
      ({ item, key }) => item.transform[4] + item.width >= splitX || !sourceReferenceKeys.has(key)
    ) ||
    right.some(
      ({ item }) => item.transform[4] <= splitX || item.transform[4] + item.width > page.width
    ) ||
    left.at(-1)!.item.transform[5] > page.height * 0.13 ||
    right[0].item.transform[5] < page.height * 0.9 ||
    page.height - right[0].item.transform[5] >= heading.fragments[0].rect.y ||
    runs.some(({ item }) => !nativeHorizontalSourceItem(item) || !near(item.height, h))
  )
    return []
  const records = (lane: typeof runs): (typeof runs)[] | undefined => {
    const rows: (typeof runs)[] = [],
      rail = lane[0].item.transform[4],
      font = lane[0].item.fontName
    for (const run of lane) {
      const { item } = run,
        current = rows.at(-1),
        previous = current?.at(-1)?.item
      if (previous && Math.abs(item.transform[5] - previous.transform[5]) < h * 0.01) {
        const overlap = previous.transform[4] + previous.width - item.transform[4]
        if (
          overlap > h * 0.05 &&
          (overlap > h * 0.08 ||
            !(
              (/^\d+$/u.test(previous.str) && /^[-–]$/u.test(item.str)) ||
              (/^[-–]$/u.test(previous.str) && /^\d+$/u.test(item.str)) ||
              /^\p{L}\p{M}$/u.test(item.str.normalize('NFD'))
            ))
        )
          return
        current!.push(run)
        continue
      }
      const pitch = previous ? previous.transform[5] - item.transform[5] : h * 1.215
      if (
        !near(item.transform[4], rail) ||
        item.fontName !== font ||
        pitch < h * 1.19 ||
        pitch > h * 1.25
      )
        return
      rows.push([run])
    }
    const result: (typeof runs)[] = []
    for (const row of rows) {
      const parts = row.map(({ item }) => item)
      const marker = /^[1-9]\d{0,2}\.$/u.test(parts[0].str)
        ? 1
        : /^[1-9]$/u.test(parts[0].str) &&
            /^\d$/u.test(parts[1]?.str ?? '') &&
            parts[2]?.str === '.'
          ? 3
          : 0
      if (marker) {
        const author = parts[marker]
        if (
          !author ||
          !/^\p{Lu}\.$/u.test(author.str) ||
          author.fontName !== font ||
          author.transform[4] - rail < h * 0.8 ||
          author.transform[4] - rail > h * 1.65
        )
          return
        result.push([])
      }
      if (!result.length) return
      result.at(-1)!.push(...row)
    }
    return result
  }
  const first = records(left),
    rest = records(right)
  if (!first || first.length < 6 || !rest || rest.length < 8) return []
  const all = [...first, ...rest]
  if (
    all.some((record, n) => {
      const text = record.map(({ item }) => item.str).join(' ')
      const number = /^((?:\d ?){1,3})\./u.exec(text)?.[1].replaceAll(' ', '')
      return (
        Number(number) !== n + 1 || !text.includes('"') || !/\((?:18|19|20)\d{2}\)\.$/u.test(text)
      )
    }) ||
    rest.slice(-4).some((record) => record.some(({ key }) => !sourceReferenceKeys.has(key)))
  )
    return []
  const wanted = new Map(right.map(({ key, item }) => [key, item.str])),
    owners = units.filter((unit) => unit.items.some((key) => wanted.has(key))),
    keys = owners.flatMap((unit) => unit.items)
  return keys.length === wanted.size &&
    new Set(keys).size === wanted.size &&
    owners.every(
      (unit) =>
        !unit.figure && unit.items.every((key, n) => wanted.get(key) === unit.originalStrings[n])
    )
    ? owners.filter((unit) => !unit.sourceOnly)
    : []
}

// Page-count metadata can hang entirely left of a centered References heading.
function nativeNumberedReferencePageCountWraps(
  units: LayoutUnit[],
  pages: PdfLayoutPage[]
): LayoutUnit[] {
  return units.filter((wrap, index) => {
    const previous = units[index - 1],
      next = units[index + 1],
      page = pages[wrap.fragments[0]?.page - 1]
    if (
      wrap.sourceOnly ||
      wrap.preserve ||
      wrap.referenceBoundary ||
      wrap.risks.length ||
      wrap.items.length !== 1 ||
      wrap.fragments.length !== 1 ||
      !/^pages?, (?:to appear in|accepted by|in press in) \p{Lu}.*\.$/u.test(wrap.source) ||
      !page ||
      page.rotation ||
      ![previous, next].every(
        (unit) =>
          unit?.sourceOnly &&
          unit.preserve === 'reference' &&
          unit.fragments.length === 1 &&
          unit.fragments[0].page === page.page
      ) ||
      !/, \d{1,3}$/u.test(previous.source)
    )
      return false
    const ordinal = (unit: LayoutUnit): number =>
      Number(/^([1-9]\d*)\. \p{Lu}\./u.exec(unit.source)?.[1])
    if (ordinal(next) !== ordinal(previous) + 1) return false
    const prior = nativeReferenceItems(previous, pages),
      first = prior[0],
      last = prior.at(-1),
      [line] = nativeReferenceItems(wrap, pages),
      [following] = nativeReferenceItems(next, pages)
    if (!first || !last || !line || !following) return false
    const [x, y] = first.transform.slice(4),
      size = first.height,
      indent = line.transform[4] - x,
      pitch = y - line.transform[5]
    return (
      nativeReferenceText([first, last, line, following]) &&
      line.str === wrap.source &&
      line.str === wrap.originalStrings[0] &&
      last.hasEOL === true &&
      line.hasEOL === true &&
      page.items.indexOf(last) + 1 === page.items.indexOf(line) &&
      page.items.indexOf(line) + 1 === page.items.indexOf(following) &&
      [last, line, following].every(
        (item) => item.fontName === first.fontName && item.height === size
      ) &&
      Math.abs(last.transform[5] - y) < size * 0.05 &&
      Math.abs(following.transform[4] - x) < size * 0.05 &&
      Math.abs(line.transform[5] - following.transform[5] - pitch) < size * 0.08 &&
      line.transform[4] + line.width < last.transform[4] + last.width &&
      indent > size &&
      indent < size * 2 &&
      pitch > size &&
      pitch < size * 1.5
    )
  })
}

// Math Reviews locators can occupy the hanging row of a numbered reference.
function nativeMathReviewReferenceLocators(
  units: LayoutUnit[],
  pages: PdfLayoutPage[]
): LayoutUnit[] {
  const locator =
    /^(?:(?:No\. \d{1,4}, |(?:\d{1,4} )?\((?:18|19|20)\d{2}\), (?:no\. \d{1,4}, )?|no\. \d{1,4}, )?\d{1,6}(?:[-–]\d{1,6})?\. )?MR \d{5,8}$/u
  const ordinal = (item: PdfLayoutTextItem): number =>
    Number(/^([1-9]\d{0,2})\.(?: \p{Lu}|$)/u.exec(item.str)?.[1])
  return units.filter((wrap, index) => {
    const previous = units[index - 1],
      next = units[index + 1],
      page = pages[wrap.fragments[0]?.page - 1]
    if (
      !page ||
      page.rotation ||
      wrap.sourceOnly ||
      wrap.preserve ||
      wrap.referenceBoundary ||
      wrap.risks.length ||
      wrap.fragments.length !== 1 ||
      !locator.test(wrap.source) ||
      ![previous, next].every(
        (unit) =>
          unit?.sourceOnly &&
          unit.preserve === 'reference' &&
          unit.fragments.every((fragment) => fragment.page === page.page)
      )
    )
      return false
    const prior = nativeReferenceItems(previous, pages),
      last = prior.at(-1),
      closing = nativeReferenceItems(wrap, pages),
      [line] = closing,
      endOfLine = closing.at(-1),
      [following] = nativeReferenceItems(next, pages)
    if (!last || !line || !endOfLine || !following) return false
    const [x, y] = line.transform.slice(4),
      em = line.height,
      near = (a: number, b: number): boolean => Math.abs(a - b) < em * 0.07,
      first = prior.find((item) => near(item.transform[5], last.transform[5])),
      start = page.items.indexOf(last),
      end = page.items.indexOf(following),
      pitch = last.transform[5] - y
    if (!first || ordinal(following) !== ordinal(first) + 1) return false
    const packet = page.items.slice(start + 1, end).filter((item) => item.str.trim())
    return (
      nativeReferenceText([first, last, ...closing, following]) &&
      closing.length === wrap.items.length &&
      packet.length === closing.length &&
      closing.every(
        (part, n) => part === packet[n] && near(part.transform[5], y) && near(part.height, em)
      ) &&
      near(last.height, em) &&
      (last.fontName === first.fontName || /^\d{1,4}$/u.test(last.str)) &&
      [first, following].every(
        (item) => item.fontName === endOfLine.fontName && near(item.height, em)
      ) &&
      [first, following].every(
        (item) => x - item.transform[4] > em && x - item.transform[4] < em * 2
      ) &&
      near(y - following.transform[5], pitch) &&
      pitch > em &&
      pitch < em * 1.5 &&
      last.transform[4] + last.width - first.transform[4] > page.width * 0.65 &&
      units
        .slice(0, index - 1)
        .some(
          (unit) =>
            unit.preserve === 'reference' &&
            /^References$/iu.test(unit.source) &&
            unit.fragments.length === 1 &&
            unit.fragments[0].page === page.page
        )
    )
  })
}

// An indented locator can close its bracketed reference on the next native row.
function nativeAncillaryReferenceLocators(
  units: LayoutUnit[],
  pages: PdfLayoutPage[]
): LayoutUnit[] {
  return units.filter((wrap, index) => {
    const entry = units[index - 1],
      preceding = units[index - 2],
      page = pages[wrap.fragments[0]?.page - 1]
    if (
      !page ||
      page.rotation ||
      wrap.sourceOnly ||
      wrap.preserve ||
      wrap.referenceBoundary ||
      wrap.risks.length ||
      wrap.items.length !== 1 ||
      wrap.fragments.length !== 1 ||
      !/^file at arXiv:\d{4}\.\d{4,5}(?:v\d+)?\.$/u.test(wrap.source) ||
      ![entry, preceding].every(
        (unit) =>
          unit?.sourceOnly &&
          unit.preserve === 'reference' &&
          unit.fragments.length === 1 &&
          unit.fragments[0].page === page.page
      ) ||
      !/\bAvailable as an ancillary$/u.test(entry.source)
    )
      return false
    const ordinal = (unit: LayoutUnit): number =>
      Number(/^\[(\d+)\] \p{Lu}/u.exec(unit.source)?.[1])
    if (ordinal(entry) !== ordinal(preceding) + 1) return false
    const [before] = nativeReferenceItems(preceding, pages),
      [last] = nativeReferenceItems(entry, pages),
      [line] = nativeReferenceItems(wrap, pages)
    if (entry.items.length !== 1 || !before || !last || !line) return false
    const [x, y] = last.transform.slice(4),
      size = last.height,
      indent = line.transform[4] - x,
      pitch = y - line.transform[5],
      lineIndex = page.items.indexOf(line),
      eol = page.items[lineIndex + 1]
    return (
      nativeReferenceText([before, last, line]) &&
      last.str === entry.source &&
      line.str === wrap.source &&
      line.str === wrap.originalStrings[0] &&
      last.hasEOL === true &&
      (line.hasEOL === true || (eol?.str === '' && eol.hasEOL === true)) &&
      page.items.indexOf(last) + 1 === lineIndex &&
      [before, line].every((item) => item.fontName === last.fontName && item.height === size) &&
      Math.abs(before.transform[4] - x) < size * 0.05 &&
      Math.abs(before.transform[5] - y - pitch) < size * 0.08 &&
      line.transform[4] + line.width < x + last.width &&
      indent > size &&
      indent < size * 2 &&
      pitch > size &&
      pitch < size * 1.5
    )
  })
}

// A centered heading followed by closed citation-key records can leave their hanging rows unowned.
function nativeDatedKeyReferenceTails(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): LayoutUnit[] {
  const page = pages.at(-1)
  if (!page || page.page !== pageCount || page.rotation) return []
  const headings = units.filter(
    (unit) =>
      unit.sourceOnly &&
      unit.preserve === 'reference' &&
      unit.source === 'References' &&
      unit.items.length === 1 &&
      unit.fragments.length === 1 &&
      unit.fragments[0].page === page.page
  )
  if (headings.length !== 1) return []
  const [title] = nativeReferenceItems(headings[0], pages)
  if (!title || !nativeHorizontalSourceItem(title)) return []
  const items = page.items.filter((item) => item.str.trim())
  const rows = nativeReferenceRows(items.slice(items.indexOf(title) + 1))
  if (!rows || rows.length < 8) return []
  const [affiliation, contact] = rows.slice(-2)
  const bibliography = rows.slice(0, -2)
  const [first] = bibliography[0]
  const [last] = bibliography.at(-1)!
  const [left, top] = first.transform.slice(4)
  const em = first.height
  const pitch = top - bibliography[1][0].transform[5]
  const near = (a: number, b: number): boolean => Math.abs(a - b) <= em * 0.06
  if (
    Math.abs(title.transform[4] + title.width / 2 - page.width / 2) > em * 0.15 ||
    title.fontName === first.fontName ||
    title.height < em * 1.1 ||
    title.transform[5] - top < em * 1.6 ||
    title.transform[5] - top > em * 2.4 ||
    pitch < em ||
    pitch > em * 1.5 ||
    affiliation.length !== 1 ||
    !/^\p{Lu}[\p{L} .,&’'-]{8,100}$/u.test(affiliation[0].str) ||
    last.transform[5] - affiliation[0].transform[5] < pitch * 1.5 ||
    !near(affiliation[0].transform[4], contact[0].transform[4]) ||
    !near(affiliation[0].transform[5] - contact[0].transform[5], pitch) ||
    !/^Email address\s*:\s*\S+@\S+$/iu.test(contact.map((item) => item.str).join(' '))
  )
    return []

  const markers = new Set<string>()
  const hanging = new Set<PdfLayoutTextItem>()
  let open: string | undefined
  let hangingX: number | undefined
  for (const [index, row] of bibliography.entries()) {
    const lead = row[0]
    const marker = /^\[([\p{L}]{1,6}(\d{2})[a-z]?)\](?:\s|$)/u.exec(lead.str)
    const end = /(?:18|19|20)(\d{2})[a-z]?\.$/u.exec(row.at(-1)!.str)?.[1]
    if (!near(top - lead.transform[5], index * pitch) || row.some((item) => !near(item.height, em)))
      return []
    if (marker) {
      if (
        open ||
        markers.has(marker[1]) ||
        !near(lead.transform[4], left) ||
        lead.fontName !== first.fontName ||
        (end && end !== marker[2])
      )
        return []
      markers.add(marker[1])
      open = end ? undefined : marker[2]
    } else {
      hangingX ??= lead.transform[4]
      if (
        !open ||
        end !== open ||
        hangingX - left < em * 2 ||
        hangingX - left > em * 6 ||
        !near(lead.transform[4], hangingX)
      )
        return []
      open = undefined
      for (const item of row) hanging.add(item)
    }
  }
  if (open || markers.size < 4 || hanging.size < 2) return []

  const keys = new Set(
    page.items.flatMap((item, index) => (hanging.has(item) ? [page.page + ':' + index] : []))
  )
  const counts = new Map<string, number>()
  for (const unit of units)
    for (const key of unit.items) if (keys.has(key)) counts.set(key, (counts.get(key) ?? 0) + 1)
  return units.filter(
    (unit) =>
      !unit.sourceOnly &&
      !unit.preserve &&
      !unit.figure &&
      !unit.referenceBoundary &&
      unit.fragments.length === 1 &&
      unit.items.length > 0 &&
      unit.items.every((key) => counts.get(key) === 1)
  )
}

// A flush continuation can finish the journal name of a closed numbered record.
function nativeWrappedJournalContinuations(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): LayoutUnit[] {
  const page = pages.at(-1)
  if (!page || page.page !== pageCount || page.rotation) return []
  const onPage = (unit: LayoutUnit | undefined): unit is LayoutUnit =>
    !!unit &&
    unit.fragments.length > 0 &&
    unit.fragments.every((fragment) => fragment.page === page.page)
  const headings = units.filter(
    (unit) => onPage(unit) && unit.preserve === 'reference' && /^References$/iu.test(unit.source)
  )
  if (headings.length !== 1) return []
  const anchor = units.indexOf(headings[0])
  const matchesJournal = (wrap: LayoutUnit, index: number): boolean => {
    const entry = units[index - 1]
    if (
      !onPage(entry) ||
      entry.preserve !== 'reference' ||
      !/^\[[1-9]\d{0,2}\] \p{Lu}/u.test(entry.source) ||
      (wrap.items.length !== 2 && wrap.items.length !== 3)
    )
      return false
    const before = nativeReferenceItems(entry, pages)
    const closing = nativeReferenceItems(wrap, pages)
    const [marker] = before
    const journal = before.at(-1)
    const [nameTail, volume] = closing
    const publication = closing.at(-1)
    const styledVolume =
      closing.length === 3 &&
      /^\p{Lu}[\p{L} .]{3,25}$/u.test(nameTail.str) &&
      /^\d{1,4}$/u.test(volume.str) &&
      volume.fontName !== nameTail.fontName &&
      volume.fontName !== marker?.fontName &&
      /^\((?:18|19|20)\d{2}\), \d{1,6}[-–]\d{1,6}\.$/u.test(publication?.str ?? '')
    const fullLocator =
      publication &&
      /^, \d{1,4}\(\d{1,3}\):\d{1,6}[-–]\d{1,6}, (?:18|19|20)\d{2}\.$/u.test(publication.str)
    if (
      before.length < 2 ||
      !journal ||
      !publication ||
      (closing.length !== 2 && !styledVolume) ||
      !nativeReferenceText([...before, ...closing]) ||
      (!styledVolume && !/^\p{L}{2,24}$/u.test(nameTail.str)) ||
      (!styledVolume && !fullLocator && !/^, (?:18|19|20)\d{2}\.$/u.test(publication.str)) ||
      nameTail.fontName !== journal.fontName ||
      nameTail.fontName === marker.fontName ||
      publication.fontName !== marker.fontName ||
      !journal.hasEOL ||
      nameTail.hasEOL
    )
      return false
    const em = marker.height
    const near = (a: number, b: number): boolean => Math.abs(a - b) < em * 0.06
    const [left, y] = marker.transform.slice(4)
    const indent = nameTail.transform[4] - left
    const pitch = y - nameTail.transform[5]
    const from = page.items.indexOf(marker)
    const until = page.items.indexOf(publication)
    const packet = page.items.slice(from, until + 1).filter((item) => item.str.trim())
    if (
      !before.every((item) => near(item.transform[5], y)) ||
      ![...before, ...closing].every((item) => near(item.height, em)) ||
      !closing.every(
        (part, index) =>
          near(part.transform[5], nameTail.transform[5]) &&
          (index === 0 ||
            Math.abs(
              part.transform[4] - closing[index - 1].transform[4] - closing[index - 1].width
            ) <
              em * (styledVolume ? 0.4 : 0.06))
      ) ||
      indent < em * (styledVolume ? 0.4 : 1) ||
      indent > em * (styledVolume ? 0.7 : 2) ||
      pitch < em * 1.15 ||
      pitch > em * 1.4 ||
      journal.transform[4] + journal.width - left < page.width * 0.5 ||
      packet.length !== before.length + closing.length ||
      [...before, ...closing].some((item, n) => item !== packet[n]) ||
      (!publication.hasEOL && !(page.items[until + 1]?.str === '' && page.items[until + 1]?.hasEOL))
    )
      return false
    // A complete volume/issue/pages/year locator and the next numbered
    // reference also prove the continuation when the journal appears once.
    const following = units[index + 1]
    const number = Number(/^\[([1-9]\d{0,2})\]/u.exec(entry.source)?.[1])
    const followingMarker =
      onPage(following) &&
      following.preserve === 'reference' &&
      following.source.startsWith(`[${number + 1}] `) &&
      nativeReferenceItems(following, pages)[0]
    if (
      followingMarker &&
      (fullLocator || styledVolume) &&
      /^\p{Lu}[\p{L} .’-]+$/u.test(journal.str) &&
      (journal.str.endsWith('-') ? /^\p{Ll}/u : /^\p{Lu}/u).test(nameTail.str) &&
      nativeReferenceText([followingMarker]) &&
      followingMarker.fontName === marker.fontName &&
      near(followingMarker.height, em) &&
      near(followingMarker.transform[4], left) &&
      near(nameTail.transform[5] - followingMarker.transform[5], pitch) &&
      page.items.slice(until + 1).find((item) => item.str.trim()) === followingMarker
    )
      return true
    if (styledVolume || index <= anchor + 2) return false
    const name = journal.str.endsWith('-')
      ? journal.str.slice(0, -1) + nameTail.str
      : journal.str + ' ' + nameTail.str
    return units
      .slice(anchor + 1, index - 1)
      .some(
        (peer) =>
          onPage(peer) &&
          peer.preserve === 'reference' &&
          /^\[[1-9]\d{0,2}\] \p{Lu}/u.test(peer.source) &&
          nativeReferenceItems(peer, pages).some(
            (item) =>
              item.str === name && item.fontName === nameTail.fontName && near(item.height, em)
          )
      )
  }
  return units.filter((wrap, index) => {
    if (
      index <= anchor + 1 ||
      !onPage(wrap) ||
      wrap.fragments.length !== 1 ||
      wrap.sourceOnly ||
      wrap.preserve ||
      wrap.referenceBoundary ||
      wrap.risks.length
    )
      return false
    if (matchesJournal(wrap, index)) return true
    if (index <= anchor + 2) return false
    if (
      !/^\p{Lu}[\p{L} .]{2,36},\s*Volume\s+\d{1,4},\s*\d{1,6}[-–]\d{1,6} \((?:19|20)\d{2}\)\.?$/u.test(
        wrap.source
      )
    )
      return false
    const [entry, journal, following] = [units[index - 2], units[index - 1], units[index + 1]]
    if (
      ![entry, journal, following].every((unit) => onPage(unit) && unit.sourceOnly) ||
      journal.preserve !== 'reference' ||
      !/[”"],\s*\p{Lu}\p{L}{2,19}$/u.test(journal.source)
    )
      return false
    const before = [...nativeReferenceItems(entry, pages), ...nativeReferenceItems(journal, pages)],
      closing = nativeReferenceItems(wrap, pages),
      [next] = nativeReferenceItems(following, pages),
      [marker] = before,
      last = before.at(-1)
    if (!marker || !last || !closing.length || !next) return false
    const number = (item: PdfLayoutTextItem): number =>
        Number(/^\[([1-9]\d*)\]$/u.exec(item.str)?.[1]),
      em = marker.height,
      [left, y] = marker.transform.slice(4),
      [line] = closing,
      pitch = y - line.transform[5],
      near = (a: number, b: number): boolean => Math.abs(a - b) < em * 0.08,
      firstIndex = page.items.indexOf(marker),
      nextIndex = page.items.indexOf(next),
      packet = [...before, ...closing, next]
    return (
      number(next) === number(marker) + 1 &&
      nativeReferenceText(packet) &&
      packet.every((part) => near(part.height, em)) &&
      closing.every(
        (part) => part.fontName === marker.fontName && near(part.transform[5], line.transform[5])
      ) &&
      next.fontName === marker.fontName &&
      before.every((part) => near(part.transform[5], y)) &&
      near(line.transform[4], left) &&
      near(next.transform[4], left) &&
      near(line.transform[5] - next.transform[5], pitch) &&
      pitch > em &&
      pitch < em * 1.5 &&
      last.transform[4] + last.width - left > page.width * 0.65 &&
      closing.at(-1)!.transform[4] + closing.at(-1)!.width - left < page.width * 0.45 &&
      packet.every(
        (part, n) => n === 0 || page.items.indexOf(part) > page.items.indexOf(packet[n - 1])
      ) &&
      page.items.slice(firstIndex, nextIndex + 1).filter((item) => item.str.trim()).length ===
        packet.length &&
      wrap.items.every((key) => units.filter((unit) => unit.items.includes(key)).length === 1)
    )
  })
}

// A compact numbered bibliography may fill the right column before a separate
// full-title bibliography. Validate the complete native records in both lanes.
function nativeCompactDecimalReferenceColumns(
  units: LayoutUnit[],
  pages: PdfLayoutPage[]
): LayoutUnit[] {
  const owners: LayoutUnit[] = []
  const marker = /^([1-9]\d{0,2})\.$/u
  const recordEnd = /\b[A-Za-z]{0,5}\d+\s+\((?:18|19|20)\d{2}\)\.$/u
  const bookEnd =
    /\((?:\p{Lu}[\p{L}'’.-]* ){1,8}(?:Press|Publishing|Publishers), (?:18|19|20)\d{2}\)\.$/u
  const printedYear = /\(((?:18|19|20)\d{2})\)\.$/u
  const authorPrefix = (text: string): string | undefined => /^([^,]+),/u.exec(text)?.[1]
  for (const heading of units) {
    if (
      heading.preserve !== 'reference' ||
      !/^References$/iu.test(heading.source) ||
      heading.items.length !== 1 ||
      heading.fragments.length !== 1
    )
      continue
    const [fragment] = heading.fragments,
      page = pages[fragment.page - 1],
      next = pages[fragment.page],
      titleIndex = Number(heading.items[0].split(':')[1]),
      title = page?.items[titleIndex]
    if (
      !page ||
      !next ||
      page.rotation ||
      next.rotation ||
      fragment.rect.right >= page.width / 2 ||
      !nativeHorizontalSourceItem(title)
    )
      continue
    const expanded = units.find(
      (unit) =>
        unit.preserve === 'reference' &&
        /^(?:References with full titles|Full References)$/iu.test(unit.source) &&
        unit.fragments.length === 1 &&
        unit.fragments[0].page === next.page &&
        unit.fragments[0].rect.y < next.height * 0.15
    )
    if (!expanded) continue
    let entries = page.items.flatMap((item, index) =>
      index > titleIndex && item.str.trim() ? [{ item, key: `${page.page}:${index}` }] : []
    )
    const middle = page.width / 2,
      split = entries.findIndex(({ item }) => item.transform[4] > middle)
    if (split <= 0) continue
    const fullTitle = /^Full References$/iu.test(expanded.source)
    const boundedFullTitle = fullTitle && marker.test(entries[split].item.str)
    const paired = fullTitle && !boundedFullTitle
    const expandedRows = paired
      ? nativeReferenceRows(
          next.items
            .slice(Number(expanded.items.at(-1)!.split(':')[1]) + 1)
            .filter((item) => item.str.trim()),
          true
        )
      : undefined
    const detailed = expandedRows?.flatMap((row, index) => (marker.test(row[0].str) ? [index] : []))
    if (paired && (!expandedRows || !detailed || detailed[0] !== 0)) continue
    if (paired) {
      const offset = entries.slice(split).findIndex(({ item }) => marker.test(item.str))
      if (offset <= 0) continue
      const figureKeys = entries.slice(split, split + offset).map(({ key }) => key)
      const caption = units.find(
        (unit) =>
          unit.fragments.length === 1 &&
          unit.fragments[0].page === page.page &&
          /^Fig(?:ure)?\.? [1-9]\d*[.:] /u.test(unit.source) &&
          terminal(unit.source) &&
          unit.items.length === figureKeys.length &&
          unit.items.every((key, index) => key === figureKeys[index])
      )
      if (!caption) continue
      const box = caption.fragments[0].rect,
        lead = entries[split + offset].item,
        gap = page.height - lead.transform[5] - box.bottom
      if (
        Math.abs(lead.transform[4] - box.x) >= lead.height * 0.15 ||
        gap <= 0 ||
        gap >= lead.height * 2
      )
        continue
      entries = [...entries.slice(0, split), ...entries.slice(split + offset)]
    }
    const left = entries.slice(0, split).map(({ item }) => item),
      right = entries.slice(split).map(({ item }) => item),
      font = left[0].height
    if (
      Math.abs(left[0].transform[4] - title.transform[4]) > font * 0.1 ||
      title.transform[5] - left[0].transform[5] < font ||
      title.transform[5] - left[0].transform[5] > font * 3 ||
      left.some((item) => item.transform[4] + item.width >= middle) ||
      right.some(
        (item) => item.transform[4] <= middle || item.transform[4] + item.width > page.width
      ) ||
      left.at(-1)!.transform[5] > page.height * 0.15 ||
      right[0].transform[5] < page.height * (paired ? 0.6 : 0.87)
    )
      continue
    const completeLane = (
      lane: PdfLayoutTextItem[],
      previous: number,
      minimum: number,
      matchesExpandedRecord?: (number: number, author: string, citation: string) => boolean
    ): number => {
      const rows = nativeReferenceRows(lane, true)
      if (!rows) return 0
      const margin = lane[0].transform[4],
        hang = rows[0][1]?.transform[4] ?? margin,
        starts = rows.flatMap((row, index) => (marker.test(row[0].str) ? [index] : []))
      if (
        starts.length < minimum ||
        starts[0] !== 0 ||
        hang - margin < font ||
        hang - margin > font * 3
      )
        return 0
      if (
        rows.some(([item, imprint], index) => {
          const gap = index ? rows[index - 1][0].transform[5] - item.transform[5] : font * 1.3
          const wrappedBookTitle =
            rows[index].length === 2 &&
            rows[index - 1]?.at(-1)?.fontName === item.fontName &&
            imprint.fontName === left[0].fontName &&
            bookEnd.test(imprint.str)
          return (
            (item.fontName !== left[0].fontName &&
              !/^\d{1,4}(?:[-–]\d{1,4})?$/u.test(item.str) &&
              !wrappedBookTitle) ||
            Math.abs(item.height - font) > font * 0.06 ||
            gap < font ||
            gap > font * 1.6 ||
            Math.abs(item.transform[4] - (marker.test(item.str) ? margin : hang)) > font * 0.12
          )
        })
      )
        return 0
      const valid = starts.every((start, index) => {
        const [label, author] = rows[start],
          record = rows
            .slice(start, starts[index + 1])
            .flat()
            .map((item) => item.str)
            .join(' ')
        const position = previous + index
        const detailIndex = detailed?.[position]
        const detail = detailIndex === undefined ? undefined : expandedRows?.[detailIndex]
        const imprint =
          detailIndex === undefined
            ? undefined
            : expandedRows
                ?.slice(detailIndex, detailed?.[position + 1])
                .flat()
                .map((item) => item.str)
                .join(' ')
        const year = printedYear.exec(record)?.[1]
        const authorName = authorPrefix(author?.str ?? '')
        const sameRecord =
          !!detail &&
          detail[0].str === label.str &&
          !!authorName &&
          authorName === authorPrefix(detail[1]?.str ?? '') &&
          !!year &&
          year === printedYear.exec(imprint ?? '')?.[1]
        return (
          Number(marker.exec(label.str)?.[1]) === previous + index + 1 &&
          !!author &&
          Math.abs(author.transform[4] - hang) < font * 0.12 &&
          (matchesExpandedRecord
            ? matchesExpandedRecord(position + 1, author.str, record)
            : /^\p{Lu}(?:[.-]|, (?=\p{Lu}))/u.test(author.str) &&
              (paired ? sameRecord : recordEnd.test(record) || bookEnd.test(record)))
        )
      })
      return valid ? starts.length : 0
    }
    const leftCount = boundedFullTitle ? 0 : completeLane(left, 0, 2)
    const rightCount = leftCount ? completeLane(right, leftCount, 3) : 0
    if (!rightCount) {
      if (paired) continue
      if (
        boundedFullTitle &&
        !nativeHorizontalSourceItem(next.items[Number(expanded.items[0].split(':')[1])])
      )
        continue
      // A locally protected lead and later record bound the missing run. The
      // separately protected expanded records identify each citation in it.
      const present = new Set(
        units
          .filter((unit) => unit.sourceOnly && unit.preserve === 'reference')
          .flatMap((unit) => unit.items)
      )
      const leftMarks = left.filter((item) => marker.test(item.str))
      const stop = entries.findIndex(
        ({ item, key }, index) => index > split && marker.test(item.str) && present.has(key)
      )
      if (
        leftMarks.length < 2 ||
        left[0] !== leftMarks[0] ||
        leftMarks.some((item, index) => Number(marker.exec(item.str)?.[1]) !== index + 1) ||
        !entries.slice(0, split).every(({ key }) => present.has(key)) ||
        stop < 0
      )
        continue
      const detailStart = Number(expanded.items.at(-1)!.split(':')[1])
      const copies = new Map<number, string>()
      let number = 0
      for (const unit of units) {
        if (
          !unit.sourceOnly ||
          unit.preserve !== 'reference' ||
          unit.fragments.some((part) => part.page !== next.page) ||
          Number(unit.items[0].split(':')[1]) <= detailStart
        )
          continue
        const start = /^([1-9]\d{0,2})\.\s*(\p{Lu}.*)$/u.exec(unit.source)
        if (start) {
          const following = Number(start[1])
          if (following !== number + 1) break
          number = following
        }
        if (number)
          copies.set(number, (copies.get(number) ?? '') + ' ' + (start?.[2] ?? unit.source).trim())
      }
      const tightAuthor = (text: string): string | undefined =>
        authorPrefix(text)?.normalize('NFKC').replace(/\s+/gu, '')
      const recovered = completeLane(
        right.slice(0, stop - split),
        leftMarks.length,
        3,
        (n, author, citation) => {
          const detailed = copies.get(n)?.trim()
          const name = tightAuthor(author)
          const year = printedYear.exec(citation)?.[1]
          return (
            !!detailed &&
            !!name &&
            !!year &&
            name === tightAuthor(detailed) &&
            year === printedYear.exec(detailed)?.[1] &&
            recordEnd.test(citation)
          )
        }
      )
      if (
        !recovered ||
        Number(marker.exec(entries[stop].item.str)?.[1]) !== leftMarks.length + recovered + 1
      )
        continue
      entries = entries.slice(split, stop)
    } else if (paired && leftCount + rightCount !== detailed?.length) continue
    const wanted = new Map(entries.map(({ key, item }) => [key, item.str])),
      matched = units.filter((unit) => unit.items.some((key) => wanted.has(key))),
      keys = matched.flatMap((unit) => unit.items)
    if (
      keys.length === wanted.size &&
      new Set(keys).size === wanted.size &&
      matched.every((unit) =>
        unit.items.every((key, index) => wanted.get(key) === unit.originalStrings[index])
      )
    )
      owners.push(...matched.filter((unit) => !unit.sourceOnly))
  }
  return owners
}

// A headed numbered bibliography can continue in the right column above its title.
function nativeClosedNumberedReferenceColumns(
  heading: LayoutUnit,
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): boolean {
  const fragment = heading.fragments[0],
    page = pages[fragment.page - 1],
    title = nativeReferenceItems(heading, pages)
  if (
    !page ||
    page.page !== pageCount ||
    !nativeReferenceCensus(page, page.nativeReferenceEvidence) ||
    heading.fragments.length !== 1 ||
    title.length < 1 ||
    title.length > 2 ||
    !/^References$/iu.test(title.map((i) => i.str).join('')) ||
    fragment.rect.right >= page.width / 2
  )
    return false
  const first = Number(heading.items[0].split(':')[1]),
    last = Number(heading.items.at(-1)!.split(':')[1]),
    prefix = page.items.slice(first, last + 1).filter((item) => item.str.trim()),
    packet = page.items.slice(last + 1).filter((item) => item.str.trim()),
    split = packet.findIndex((item) => item.transform[4] > page.width / 2),
    left = packet.slice(0, split),
    right = packet.slice(split),
    size = packet[0]?.height
  if (
    prefix.some((item, n) => item !== title[n]) ||
    prefix.length !== title.length ||
    !size ||
    !left.length ||
    !right.length ||
    packet.some(
      (item) =>
        Math.abs(item.height - size) > size * 0.03 ||
        item.transform[4] < 0 ||
        item.transform[4] + item.width > page.width
    ) ||
    left.some((item) => item.transform[4] + item.width >= page.width / 2) ||
    right.some((item) => item.transform[4] <= page.width / 2) ||
    page.height - right[0].transform[5] >= fragment.rect.y
  )
    return false
  // Each complete citation ends in a URL. Running title/venue matter has
  // already been excluded by the native interval following this heading.
  const leftRows = nativeReferenceRows(left, true),
    rightRows = nativeReferenceRows(right, true)
  if (leftRows?.length && rightRows?.length) {
    const mark = /^\[(\d{1,4})\](?:$|\s+\p{L})/u
    const leftMarks = leftRows.filter((row) => mark.test(row[0].str)),
      rightMarks = rightRows.filter((row) => mark.test(row[0].str))
    const marks = [...leftMarks, ...rightMarks]
    // An archive locator can close the last left entry on the opening right row.
    const compactArchive =
      leftMarks.length === 3 &&
      rightMarks.length >= 6 &&
      /\barXiv:(\d{4}\.\d{4,5})(?:v\d+)?\s+\[[a-z.]+\]\s+https?:\/\/arxiv\.org\/abs\/\1(?:v\d+)?$/iu.test(
        rightRows[0].map((item) => item.str).join(' ')
      )
    if (
      leftRows[0] === leftMarks[0] &&
      rightRows[0] !== rightMarks[0] &&
      (compactArchive || leftMarks.length >= 4) &&
      rightMarks.length >= 2 &&
      (compactArchive || leftRows.at(-1)![0].transform[5] < page.height * 0.16) &&
      page.height - rightRows[0][0].transform[5] < page.height * 0.16 &&
      marks.every((row, index) => Number(mark.exec(row[0].str)?.[1]) === index + 1)
    ) {
      const records: PdfLayoutTextItem[][][] = []
      let valid = true
      for (const [lane, starts] of [
        [leftRows, leftMarks],
        [rightRows, rightMarks]
      ]) {
        const marker = starts[0][0],
          margin = marker.transform[4],
          firstSeparate = starts.find((row) => row[0].str.endsWith(']')),
          hanging = firstSeparate?.[1]?.transform[4] ?? NaN
        if (
          !(hanging - margin >= size && hanging - margin <= size * 3) ||
          starts.some(
            (row) =>
              row[0].fontName !== leftMarks[0][0].fontName ||
              (/^\[\d+\]$/u.test(row[0].str) &&
                (!row[1] ||
                  !/^\p{L}/u.test(row[1].str) ||
                  Math.abs(row[1].transform[4] - hanging) > size * 0.15))
          ) ||
          lane.some((row) => {
            const item = row[0],
              expected = mark.test(item.str) ? margin : hanging
            if (compactArchive && item.str.endsWith(']') && mark.test(item.str))
              return Math.abs(item.transform[4] + item.width - margin - marker.width) > size * 0.15
            return Math.abs(item.transform[4] - expected) > size * 0.15
          })
        ) {
          valid = false
          break
        }
        for (const row of lane) {
          if (mark.test(row[0].str)) records.push([])
          records.at(-1)!.push(row)
        }
      }
      if (
        valid &&
        records.every((record) => {
          const parts = record.flat(),
            text = parts.map((item) => item.str).join(' '),
            last = parts.at(-1)!.str.trim(),
            previous = parts.at(-2)?.str.trim() ?? ''
          return (
            /\b(?:18|19|20)\d{2}\b|\[n\. d\.\]/u.test(text) &&
            (/https?:\/\/[^\s<>]+$/iu.test(last) ||
              (/^\d+[.\d]+$/u.test(last) && /https?:\/\/[^\s<>]+\/$/iu.test(previous)) ||
              (compactArchive &&
                (/\bdoi:\s*10\.\d{4,9}\/\S+$/iu.test(last) ||
                  /(?:^|[ .])Accessed \p{Lu}\p{Ll}+ (?:19|20)\d{2}\.$/u.test(last) ||
                  (/^[a-z]{2,12}\/\S+$/iu.test(last) &&
                    /https?:\/\/[a-z0-9][a-z0-9.-]*\.$/iu.test(previous)))))
          )
        })
      )
        return true
    }
  }
  const markers = packet.flatMap((item, index) =>
    /^\[(\d{1,4})\]$/u.test(item.str) ? [index] : []
  )
  if (
    markers.length < 8 ||
    markers[0] !== 0 ||
    markers.filter((index) => index < split).length < 3 ||
    markers.filter((index) => index > split).length < 3 ||
    markers.includes(split) ||
    markers.some(
      (index, n) =>
        packet[index].str !== `[${n + 1}]` || packet[index].fontName !== packet[0].fontName
    )
  )
    return false
  return markers.every((index, n) => {
    const marker = packet[index],
      author = packet[index + 1],
      end = packet[(markers[n + 1] ?? packet.length) - 1]
    return (
      !!author &&
      author.transform[4] - marker.transform[4] >= size &&
      author.transform[4] - marker.transform[4] <= size * 3 &&
      Math.abs(author.transform[5] - marker.transform[5]) < size * 0.01 &&
      /^\p{Lu}\.\s*/u.test(author.str) &&
      /\b(?:18|19|20)\d{2}\.$/u.test(end.str.trim())
    )
  })
}

// A headed bibliography on the last page with native text can cross the
// columns. Each column must independently contain whole bracketed records.
function nativeCompactBracketedReferenceContinuation(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): LayoutUnit[] {
  if (pages.length !== pageCount || pages.some((p, i) => p.page !== i + 1)) return []
  const pageIndex = pages.findLastIndex((p) => p.items.some((i) => i.str.trim())),
    page = pages[pageIndex]
  if (!page || page.rotation !== 0 || pages.length - pageIndex > 2) return []
  const middle = page.width / 2
  const candidates = units.filter(
    (u) =>
      u.preserve === 'reference' &&
      (u.source === 'References' || /^[1-9]\d?\. REFERENCES$/u.test(u.source)) &&
      u.items.length <= 2 &&
      u.fragments.length === 1 &&
      u.fragments[0].page === page.page &&
      u.fragments[0].rect.right < middle
  )
  const compactHeadings = candidates.filter((u) =>
    u.source === 'References'
      ? u.fragments[0].rect.y > page.height * 0.68
      : u.fragments[0].rect.y < page.height * 0.25
  )
  const legacyHeadings = compactHeadings.length
    ? compactHeadings
    : candidates.filter(
        (u) => u.source === 'References' && u.fragments[0].rect.y > page.height * 0.55
      )
  // A terminal numbered hanging bibliography can start higher in its left column.
  const dated = legacyHeadings.length === 0 && page.page === pageCount
  const headings = dated
    ? candidates.filter(
        (u) =>
          u.source === 'References' &&
          u.fragments[0].rect.y > page.height * 0.24 &&
          u.fragments[0].rect.y <= page.height * 0.55
      )
    : legacyHeadings
  if (headings.length !== 1) return []
  const numbered = headings[0].source !== 'References'
  const headingRuns = nativeReferenceItems(headings[0], pages)
  const title = headingRuns.at(-1)
  if (!title) return []
  const index = page.items.indexOf(title)
  if (index < 0) return []
  const packet = page.items.slice(index + 1).filter((i) => i.str.trim()),
    split = packet.findIndex((i) => i.transform[4] > middle),
    left = packet.slice(0, split),
    right = packet.slice(split),
    font = left[0]?.height,
    body = left[0]?.fontName
  if (
    split < 2 ||
    !right.length ||
    !font ||
    !body ||
    !nativeHorizontalSourceItem(title) ||
    (numbered
      ? headingRuns.length !== 2 ||
        title.str !== 'REFERENCES' ||
        !nativeHorizontalSourceItem(headingRuns[0]) ||
        `${headingRuns[0].str} ${title.str}` !== headings[0].source ||
        Math.abs(headingRuns[0].transform[5] - title.transform[5]) > font * 0.05 ||
        headingRuns[0].fontName !== title.fontName
      : headingRuns.length !== 1 || title.str !== 'References') ||
    title.fontName === body ||
    (numbered ? Math.abs(title.height - font) > font * 0.025 : title.height <= font * 1.05) ||
    title.transform[5] - left[0].transform[5] < font ||
    title.transform[5] - left[0].transform[5] > font * 2.4 ||
    page.height - right[0].transform[5] > page.height * 0.16 ||
    left.some((i) => i.transform[4] + i.width >= middle) ||
    right.some((i) => i.transform[4] <= middle) ||
    packet.some(
      (i) =>
        !nativeHorizontalSourceItem(i) ||
        i.height !== font ||
        i.transform[4] < 0 ||
        i.transform[4] + i.width > page.width
    )
  )
    return []
  const lanes = [left, right].map((items) => nativeOrderedRows(items, true))
  const publicationDate = /(?:\(|, )(?:19|20)\d{2}\)/u
  const journalEnd =
    /, [A-Z]?\d{1,5}(?:\(\d{1,4}\))?:[A-Z]?\d+(?:[–-][A-Z]?\d+)?, (?:19|20)\d{2}(?:\.$|, [^.!?]+https?:\/\/[^\s]+\s*\.$)/u
  const terminalJournalColumns =
    !numbered &&
    page.page === pageCount &&
    left.at(-1)!.transform[5] < page.height * 0.16 &&
    right[0].transform[5] > page.height * 0.9 &&
    Math.abs(left[0].transform[4] - title.transform[4] - font * 0.5) < font * 0.1
  const readLanes = (journal: boolean): boolean => {
    let number = 1
    return lanes.every((rows, lane) => {
      if (!rows || rows.length < 4) return false
      const indent = rows[0][0].transform[4],
        records: string[][] = []
      let hanging: number | undefined
      for (const [n, row] of rows.entries()) {
        const first = row[0],
          x = first.transform[4],
          bracket = /^\[(\d{1,3})\]\s+\p{Lu}/u.exec(first.str),
          gap = n ? rows[n - 1][0].transform[5] - first.transform[5] : font
        if (
          gap < font * 0.95 ||
          gap > font * (numbered && bracket ? 2.25 : 1.55) ||
          (!numbered &&
            !journal &&
            first.fontName !== body &&
            !/^(?:https?:|[a-z0-9._-]+[./])/iu.test(first.str))
        )
          return false
        if (bracket) {
          if (
            Number(bracket[1]) !== number++ ||
            first.fontName !== body ||
            Math.abs(x - indent) > font * 0.52
          )
            return false
          records.push([])
        } else {
          if (!records.length || x - indent < font || x - indent > font * 2.5) return false
          hanging ??= x
          if (Math.abs(x - hanging) > font * 0.05) return false
        }
        records.at(-1)!.push(row.map((i) => i.str).join(' '))
      }
      const completed = records.map((p) => p.join(' '))
      if (numbered)
        return (
          records.length >= 5 &&
          records.every((p) => p.length > 1) &&
          completed.every((text) => /\b(?:19|20)\d{2}\b/u.test(text) && terminal(text)) &&
          completed.some((text) => /\b(?:in Proc\.|IEEE|Ph\.D\.|(?:pp|vol)\.)/u.test(text))
        )
      if (journal) {
        const citations = completed.filter((text) => journalEnd.test(text))
        // Numbered explanations may occupy otherwise continuous journal lanes.
        return (
          records.length >= (lane ? 8 : 4) &&
          records.every((record) => record.length > 1) &&
          citations.length >= records.length * 0.75 &&
          completed.every(
            (text) =>
              journalEnd.test(text) ||
              (lane === 1 &&
                /^\[\d{1,3}\] (?:The|We|While|When|Although) \p{L}+/u.test(text) &&
                /\. \p{Lu}/u.test(text) &&
                terminal(text))
          )
        )
      }
      return (
        records.length >= (lane ? 5 : 2) &&
        records.every((p) => p.length > 1) &&
        completed.every((text) => publicationDate.test(text) || /https?:\/\//u.test(text)) &&
        completed.filter((text) => publicationDate.test(text)).length >= completed.length - 1 &&
        completed.some((text) => /\b10\.\d{4,9}\s*\//u.test(text))
      )
    })
  }
  const readPublicationYearLanes = (): boolean => {
    let ordinal = 1
    return lanes.every((rows, lane) => {
      if (!rows?.length) return false
      const indent = rows[0][0].transform[4]
      const starts = new Map<number, number>()
      const records: string[][] = []
      let hanging: number | undefined
      for (const [at, parts] of rows.entries()) {
        const first = parts[0],
          x = first.transform[4]
        const gap = at ? rows[at - 1][0].transform[5] - first.transform[5] : font * 1.14
        const bracket = /^\[([1-9]\d{0,2})\](?: (\p{Lu}.*))?$/u.exec(first.str)
        if (gap < font * 1.04 || gap > font * 1.28) return false
        if (bracket) {
          if (Number(bracket[1]) !== ordinal++ || first.fontName !== body) return false
          const key = bracket[1].length
          const start = starts.get(key) ?? x
          if (Math.abs(x - start) > font * 0.06 || Math.abs(x - indent) > font * 0.58) return false
          starts.set(key, start)
          if (!bracket[2] && (!parts[1] || !/^\p{Lu}/u.test(parts[1].str))) return false
          records.push([])
        } else {
          if (!records.length || x - indent < font * 1.45 || x - indent > font * 2.2) return false
          hanging ??= x
          if (Math.abs(x - hanging) > font * 0.06) return false
        }
        records.at(-1)!.push(parts.map((part) => part.str).join(' '))
      }
      const years = records.map((record) => {
        const text = record.join(' ')
        const year = /\. ((?:18|19|20)\d{2})\. \p{Lu}/u.exec(text)?.[1]
        return year && terminal(text) && record.length >= 2 ? { year, text } : undefined
      })
      return (
        records.length >= (lane ? 5 : 3) &&
        years.every((entry) => entry !== undefined) &&
        years.filter(({ year, text }) => text.includes(`(${year})`)).length >= records.length / 2
      )
    })
  }

  if (
    dated
      ? Math.abs(left[0].transform[4] - title.transform[4] - font * 0.5) > font * 0.1 ||
        right[0].transform[5] <= title.transform[5] + font * 4 ||
        !readPublicationYearLanes()
      : !(terminalJournalColumns && readLanes(true)) &&
        !(compactHeadings.length && readLanes(false))
  )
    return []
  const rightNative = new Set(right)
  const keys = new Set(
    page.items.flatMap((part, n) => (rightNative.has(part) ? [page.page + ':' + n] : []))
  )
  const owners = units.filter((u) => u.items.some((key) => keys.has(key)))
  const counts = new Map<string, number>()
  for (const owner of owners)
    for (const key of owner.items) counts.set(key, (counts.get(key) ?? 0) + 1)
  const writable = owners.filter((u) => !u.sourceOnly && !u.preserve)
  if (
    counts.size !== keys.size ||
    (dated && [...counts.values()].some((count) => count !== 1)) ||
    owners.some(
      (u) =>
        u.referenceBoundary ||
        u.figure ||
        u.fragments.some((f) => f.page !== page.page || f.rect.x <= middle) ||
        u.items.some(
          (k, i) =>
            !keys.has(k) ||
            (dated && page.items[Number(k.split(':')[1])]?.str !== u.originalStrings[i])
        )
    ) ||
    writable.some((u) => u.items.some((key) => counts.get(key) !== 1))
  )
    return []
  return writable
}

// One open numbered entry can cross the gutter before the first complete record.
function retainNativeBracketedReferenceSeam(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): void {
  const page = pages.at(-1)
  if (!page || page.rotation || pages.length !== pageCount) return
  const middle = page.width / 2
  const heading = units.findIndex(
    (u) =>
      u.source === 'References' &&
      u.preserve === 'reference' &&
      u.items.length === 1 &&
      u.fragments.length === 1 &&
      u.fragments[0].page === page.page &&
      u.fragments[0].rect.right < middle
  )
  if (heading < 0) return
  const [title] = nativeReferenceItems(units[heading], pages)
  if (!nativeHorizontalSourceItem(title)) return
  const x = (item: PdfLayoutTextItem): number => item.transform[4]
  const y = (item: PdfLayoutTextItem): number => item.transform[5]
  const ordinal = /^\[([1-9]\d{0,2})\]/u
  const published = /\. (?:19|20)\d{2}[a-z]?\. /u
  for (let i = heading + 2; i + 5 < units.length; i++) {
    const [prior, tail, locator, entry, next, witness] = units.slice(i, i + 6)
    const previous = units[i - 1]
    const n = Number(ordinal.exec(prior.source)?.[1])
    const records = [prior, entry, next, witness]
    if (
      !Number.isSafeInteger(n) ||
      n < 2 ||
      previous.preserve !== 'reference' ||
      !previous.source.startsWith(`[${n - 1}] `) ||
      ![prior, next, witness].every((u) => u.sourceOnly && u.preserve === 'reference') ||
      [tail, entry].some((u) => u.sourceOnly || u.preserve || u.figure || u.referenceBoundary) ||
      !locator.sourceOnly ||
      locator.preserve !== 'literal' ||
      !/^\d{1,6}\.$/u.test(locator.source) ||
      !/\. In .+\b(?:19|20)\d{2}\b.+\.$/u.test(tail.source) ||
      !/\p{L}$/u.test(prior.source) ||
      records.some((u, j) => !u.source.startsWith(`[${n + j}] `) || !published.test(u.source)) ||
      [prior, tail, locator, entry, next, witness].some(
        (u, j) =>
          u.fragments.length !== 1 ||
          u.fragments[0].page !== page.page ||
          (j === 0 ? u.fragments[0].rect.right >= middle : u.fragments[0].rect.x <= middle)
      )
    )
      continue
    const claimed = new Set([...tail.items, ...entry.items])
    if (units.some((u) => u !== tail && u !== entry && u.items.some((key) => claimed.has(key))))
      continue
    const owners = [prior, tail, locator, entry, next, witness]
    const groups = owners.map((u) => nativeReferenceItems(u, pages))
    const ink = groups.flat()
    const index = page.items.indexOf(ink[0])
    if (
      groups[2].length !== 1 ||
      groups.some(
        (part, slot) =>
          !part.length ||
          part.length !== owners[slot].originalStrings.length ||
          part.some((item, j) => item.str !== owners[slot].originalStrings[j])
      ) ||
      !ink.every(nativeHorizontalSourceItem) ||
      index < 0
    )
      continue
    const actual = page.items
      .slice(index, page.items.indexOf(ink.at(-1)!) + 1)
      .filter((item) => item.str.trim())
    if (actual.length !== ink.length || actual.some((item, j) => item !== ink[j])) continue
    const [[left, leftName], tailInk, [number], entryInk, nextInk, witnessInk] = groups
    const [right, rightName] = entryInk
    const em = left.height,
      near = (a: number, b: number): boolean => Math.abs(a - b) < em * 0.06
    const rows = nativeOrderedRows([...tailInk, number, ...entryInk, ...nextInk, ...witnessInk])
    const nominated = new Set([...tailInk, ...entryInk])
    if (
      !leftName ||
      !rightName ||
      !rows ||
      rows.length < 6 ||
      rows.some(
        ([head]) => nominated.has(head) && head !== right && !near(x(head), x(rightName))
      ) ||
      y(tailInk[0]) <= y(title) ||
      y(groups[0].at(-1)!) >= y(title) ||
      !near(x(rightName) - x(right), x(leftName) - x(left)) ||
      ![tailInk[0], number, rightName, nextInk[1], witnessInk[1]].every(
        (item) => item && near(x(item), x(rightName)) && item.fontName === rightName.fontName
      ) ||
      !groups[0].every((item) => x(item) + item.width < middle) ||
      ink.some((item) => !near(item.height, em)) ||
      ![groups[0], entryInk, nextInk, witnessInk].every(
        ([mark], j) =>
          mark.str === `[${n + j}]` &&
          mark.fontName === left.fontName &&
          (j === 0 || near(x(mark), x(right)))
      ) ||
      rows.slice(1).some(([row], j) => {
        const pitch = y(rows[j][0]) - y(row)
        return pitch < em || pitch > em * 1.35
      })
    )
      continue
    for (const u of [tail, entry]) Object.assign(u, { sourceOnly: true, preserve: 'reference' })
  }
}

// The last bracketed entry can carry its typeset book title over the column turn.
function retainNativeTerminalBookTitleTail(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): void {
  const page = pages.at(-1)
  const [previous, left, header, tail, folio] = units.slice(-5)
  if (!page || page.rotation || pages.length !== pageCount || !folio) return
  const n = Number(/^\[([1-9]\d*)\] /u.exec(left.source)?.[1])
  const middle = page.width / 2
  if (
    !(n >= 2) ||
    !previous.source.startsWith(`[${n - 1}] `) ||
    ![previous, left].every((u) => u.sourceOnly && u.preserve === 'reference') ||
    tail.sourceOnly ||
    tail.preserve ||
    tail.figure ||
    tail.referenceBoundary ||
    tail.fragments.length !== 1 ||
    header.items.length !== 1 ||
    folio.items.length !== 1 ||
    [left, header, tail, folio].some((u) => u.fragments.some((f) => f.page !== page.page)) ||
    folio.source !== String(page.page) ||
    !folio.sourceOnly ||
    !/\bin: \p{Lu}\p{L}+$/u.test(left.source) ||
    !/, Eds\., \p{Lu}[\p{L} .&-]+, (?:19|20)\d{2}\.$/u.test(tail.source) ||
    !units.some(
      (u) =>
        u.source === 'References' &&
        u.preserve === 'reference' &&
        u.fragments.length === 1 &&
        u.fragments[0].page === page.page &&
        u.fragments[0].rect.right < middle
    )
  )
    return
  const leftInk = nativeReferenceItems(left, pages),
    rightInk = nativeReferenceItems(tail, pages)
  const [marker, lead, intro, title] = leftInk,
    [one, two, titleEnd, editors, publisher] = rightInk
  const [running] = nativeReferenceItems(header, pages),
    [number] = nativeReferenceItems(folio, pages)
  const keys = new Set([...left.items, ...tail.items])
  const ink = [...leftInk, ...rightInk],
    strings = [...left.originalStrings, ...tail.originalStrings]
  if (
    leftInk.length !== 4 ||
    rightInk.length !== 5 ||
    ![...leftInk, ...rightInk, running, number].every(nativeHorizontalSourceItem) ||
    units.some((u) => u !== left && u !== tail && u.items.some((key) => keys.has(key))) ||
    ink.some((item, index) => item.str !== strings[index])
  )
    return
  const x = (i: PdfLayoutTextItem): number => i.transform[4]
  const y = (i: PdfLayoutTextItem): number => i.transform[5]
  const em = marker.height,
    near = (a: number, b: number): boolean => Math.abs(a - b) < em * 0.25
  if (
    marker.str !== `[${n}]` ||
    !intro.str.endsWith('in:') ||
    !editors.str.startsWith(', ') ||
    ![one, two, titleEnd].every((item) => item.fontName === title.fontName) ||
    title.fontName === marker.fontName ||
    ![lead, intro, editors, publisher, running, number].every(
      (item) => item.fontName === marker.fontName
    ) ||
    ink.some((item) => !near(item.height, em)) ||
    !near(y(intro), y(title)) ||
    y(title) > page.height * 0.13 ||
    x(title) + title.width >= middle ||
    !near(x(title) + title.width, x(lead) + lead.width) ||
    x(one) <= middle ||
    y(one) < page.height * 0.88 ||
    !near(lead.width, one.width) ||
    x(running) < x(one) ||
    y(running) - y(one) < em * 2 ||
    !near(x(number) + number.width / 2, middle) ||
    y(number) > page.height * 0.07 ||
    ![two, titleEnd, publisher].every((item) => near(x(item), x(one))) ||
    !nativeOrderedRows(rightInk)?.every(
      ([first], index, rows) => !index || near(y(rows[index - 1][0]) - y(first), em * 1.2)
    ) ||
    !near(y(editors), y(titleEnd)) ||
    !near(x(editors), x(titleEnd) + titleEnd.width)
  )
    return
  const end = page.items.indexOf(title)
  const rest = page.items.slice(end + 1).filter((item) => item.str.trim())
  const expected = [...rightInk, number]
  if (end < 0 || rest.length !== expected.length || rest.some((item, at) => item !== expected[at]))
    return
  Object.assign(tail, { sourceOnly: true, preserve: 'reference' })
}

// A small-caps bibliography with independent bracket glyphs may continue at the top
// of the opposite column. Its dated records close both native lanes.
function retainNativeSplitBracketedReferences(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): void {
  const page = pages.at(-1)
  if (
    !page ||
    page.rotation ||
    pages.length !== pageCount ||
    pages.some((p, index) => p.page !== index + 1) ||
    page.items.length > 4096
  )
    return
  const middle = page.width / 2,
    headings = units.filter(
      (u) =>
        u.source === 'REFERENCES' &&
        u.sourceOnly &&
        u.preserve === 'reference' &&
        u.items.length === 2 &&
        u.fragments.length === 1 &&
        u.fragments[0].page === page.page &&
        u.fragments[0].rect.right < middle
    )
  if (headings.length !== 1) return
  const heading = nativeReferenceItems(headings[0], pages)
  if (heading.length !== 2 || !nativeReferenceText(heading)) return
  const [initial, rest] = heading,
    titleY = rest.transform[5],
    em = rest.height,
    headingEnd = page.items.indexOf(rest),
    entries = page.items.flatMap((item, index) =>
      index > headingEnd && item.str.trim() ? [{ item, index }] : []
    ),
    split = entries.findIndex(({ item }) => item.transform[4] > middle),
    left = entries.slice(0, split).map(({ item }) => item),
    right = entries.slice(split).map(({ item }) => item)
  if (
    initial.str !== 'R' ||
    rest.str !== 'EFERENCES' ||
    initial.fontName !== rest.fontName ||
    initial.height < em * 1.2 ||
    initial.height > em * 1.4 ||
    Math.abs(initial.transform[5] - titleY) > em * 0.01 ||
    Math.abs(initial.transform[4] + initial.width - rest.transform[4]) > em * 0.1 ||
    split < 2 ||
    !right.length ||
    left[0].fontName !== rest.fontName ||
    Math.abs(
      initial.transform[4] + rest.transform[4] + rest.width - left[0].transform[4] - middle
    ) >
      em * 1.4 ||
    titleY - left[0].transform[5] < em * 1.5 ||
    titleY - left[0].transform[5] > em * 2.4 ||
    left.at(-1)!.transform[5] > page.height * 0.12 ||
    right[0].transform[5] < page.height * 0.84 ||
    left.some((i) => i.transform[4] + i.width >= middle) ||
    right.some((i) => i.transform[4] <= middle) ||
    entries.some(
      ({ item: i }) =>
        i.height !== em ||
        i.transform[4] < 0 ||
        i.transform[4] + i.width > page.width ||
        i.transform[5] - em < 0 ||
        i.transform[5] + em > page.height
    )
  )
    return

  let ordinal = 1
  for (const lane of [left, right]) {
    const rows = nativeReferenceRows(lane, true)
    if (!rows || rows.length < 6) return
    const markerRight = lane[0].transform[4] + lane[0].width,
      indent = rows[0][1]?.transform[4],
      records: PdfLayoutTextItem[][][] = []
    if (!Number.isFinite(indent) || indent - markerRight < em * 0.3 || indent - markerRight > em)
      return
    for (const [index, row] of rows.entries()) {
      const head = row[0],
        marker = /^\[([1-9]\d{0,2})\]$/u.exec(head.str),
        pitch = index ? rows[index - 1][0].transform[5] - head.transform[5] : em
      if (pitch < em * 0.95 || pitch > em * 1.45) return
      if (marker) {
        if (
          Number(marker[1]) !== ordinal++ ||
          head.fontName !== rest.fontName ||
          Math.abs(head.transform[4] + head.width - markerRight) > em * 0.05 ||
          !row[1] ||
          Math.abs(row[1].transform[4] - indent) > em * 0.05 ||
          !/^(?:\p{Lu}\.|[—–]{2,})/u.test(row[1].str)
        )
          return
        records.push([row.slice(1)])
      } else {
        if (!records.length || Math.abs(head.transform[4] - indent) > em * 0.05) return
        records.at(-1)!.push(row)
      }
    }
    if (
      records.length < 3 ||
      records.some((record) => {
        const parts = record.flat()
        return (
          record.length < 2 ||
          !/,\s*(?:19|20)\d{2}\.$/u.test(parts.map((item) => item.str.trim()).join(' ')) ||
          !parts.some((item) => item.fontName !== rest.fontName && /\p{L}{2}/u.test(item.str))
        )
      })
    )
      return
  }

  const native = new Map(
      entries.slice(split).map(({ item, index }) => [`${page.page}:${index}`, item.str])
    ),
    owners = units.filter((u) => u.items.some((key) => native.has(key))),
    claimed = new Set<string>()
  for (const u of owners) {
    if (
      u.referenceBoundary ||
      u.figure ||
      u.items.length !== u.originalStrings.length ||
      u.fragments.some((f) => f.page !== page.page || f.rect.x <= middle) ||
      u.items.some((key, index) => {
        if (claimed.has(key) || native.get(key) !== u.originalStrings[index]) return true
        claimed.add(key)
        return false
      })
    )
      return
  }
  if (claimed.size !== native.size) return
  for (const owner of owners)
    if (!owner.sourceOnly) Object.assign(owner, { sourceOnly: true, preserve: 'reference' })
}

// A complete hanging author-date column can precede its heading vertically.
// Numbered and mixed lanes still need their own native packet proofs.
function nativeAuthorDateReferenceColumn(heading: LayoutUnit, pages: PdfLayoutPage[]): boolean {
  const fragment = heading.fragments[0],
    page = pages[fragment.page - 1]
  if (
    !page ||
    page.page !== fragment.page ||
    page.rotation !== 0 ||
    heading.items.length !== 1 ||
    heading.fragments.length !== 1 ||
    fragment.rect.right >= page.width / 2
  )
    return false
  const index = Number(heading.items[0].split(':')[1])
  const right = page.items
    .slice(index + 1)
    .filter((item) => item.str.trim() && item.transform[4] > page.width / 2)
  const left = page.items
    .slice(index + 1)
    .filter(
      (item) =>
        item.str.trim() &&
        item.transform[4] < page.width / 2 &&
        page.height - item.transform[5] > fragment.rect.bottom
    )
  return [left, right].every((items) => {
    if (!nativeReferenceText(items)) return false
    const first = items[0],
      font = first.height,
      origin = first.transform[4]
    let lastY = Infinity,
      rows = 0,
      record = '',
      records = 0
    const complete = (): boolean => rows > 1 && /(?:, |\. )(?:19|20)\d{2}[a-z]?\./u.test(record)
    for (const item of items) {
      const [x, y] = item.transform.slice(4),
        indent = x - origin
      if (Math.abs(item.height - font) > font * 0.03 || y > lastY + font * 0.01) return false
      if (lastY - y > font * 0.01) {
        if (Math.abs(indent) < font * 0.12) {
          if (record) {
            if (!complete()) return false
            records++
          }
          if (!/^\p{Lu}/u.test(item.str)) return false
          record = ''
          rows = 0
        } else if (!record || indent < font * 0.8 || indent > font * 1.5) return false
        rows++
        lastY = y
      }
      record += (record ? ' ' : '') + item.str
    }
    return records >= 2 && complete()
  })
}

// A terminal bibliography is set from its left heading down and then from the
// top of the right column. The right lane must consist of closed author records.
function nativeTerminalHangingReferenceColumns(
  heading: LayoutUnit,
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): boolean {
  const page = pages.at(-1),
    fragment = heading.fragments[0]
  if (
    !page ||
    page.rotation ||
    page.page !== pageCount ||
    !/^(?:References|Bibliography)$/iu.test(heading.source) ||
    heading.items.length !== 1 ||
    heading.fragments.length !== 1 ||
    fragment.page !== page.page ||
    fragment.rect.right >= page.width / 2
  )
    return false
  const index = Number(heading.items[0].split(':')[1])
  const title = page.items[index]
  if (!nativeHorizontalSourceItem(title)) return false
  const packet = page.items.slice(index + 1).filter((item) => item.str.trim())
  const middle = page.width / 2
  const turn = packet.findIndex((item) => item.transform[4] > middle)
  if (turn < 4) return false
  const left = packet.slice(0, turn),
    right = packet.slice(turn),
    em = left[0].height
  const footer = right.at(-1)!
  if (
    footer.transform[5] < page.height * 0.1 &&
    right.length > 2 &&
    right.at(-2)!.transform[5] - footer.transform[5] > em * 4 &&
    new RegExp('\\bpage ' + page.page + ' of ' + pageCount + '$', 'iu').test(footer.str)
  )
    right.pop()
  const [leftStart, rightStart] = [left[0], right[0]]
  if (
    title.fontName === leftStart.fontName ||
    title.height < em * 1.05 ||
    Math.abs(title.transform[4] - leftStart.transform[4]) > em * 0.05 ||
    title.transform[5] - leftStart.transform[5] < em ||
    title.transform[5] - leftStart.transform[5] > em * 2.4 ||
    rightStart.transform[5] < Math.max(page.height * 0.86, title.transform[5] + em * 4) ||
    left.at(-1)!.transform[5] > page.height * 0.13 ||
    leftStart.transform[4] > page.width * 0.23 ||
    rightStart.transform[4] - middle > em * 2
  )
    return false

  const author =
    /^\p{Lu}[\p{L}\p{M}’'.-]*(?: \p{Lu}[\p{L}\p{M}’'.-]*){0,3}, (?:\p{Lu}\.|\p{Lu}[\p{L}’'.-]+, \p{Lu}\.)/u
  const publicationYear = /\. (?:18|19|20)\d{2}[a-z]?, (\S.*)$/u
  const locator = /(?:[,:]\s*[A-Z]?\d+[A-Z]?(?:[.\u2013-][A-Z]?\d+[A-Z]?)*|\))\.?$/u
  const records = (items: PdfLayoutTextItem[], column: number): string[] => {
    const rows = nativeReferenceRows(items, true)
    if (!rows || rows.length < 4) return []
    const origin = rows[0][0].transform[4]
    const result: string[] = []
    let hanging: number | undefined
    let wraps = 0
    for (const [at, row] of rows.entries()) {
      const [x, y] = row[0].transform.slice(4)
      const gap = at ? rows[at - 1][0].transform[5] - y : em * 1.12
      if (
        gap < em * 1.03 ||
        gap > em * 1.3 ||
        (at < rows.length - 1 && !row.at(-1)!.hasEOL) ||
        row.some(
          (item) =>
            item.fontName !== leftStart.fontName ||
            Math.abs(item.height - em) > em * 0.02 ||
            item.transform[4] < origin - em * 0.05 ||
            item.transform[4] + item.width > (column === 0 ? middle : page.width)
        )
      )
        return []
      const text = row.map((item) => item.str).join(' ')
      if (Math.abs(x - origin) < em * 0.05) result.push(text)
      else {
        if (!result.length || x - origin < em || x - origin > em * 1.6) return []
        hanging ??= x
        if (Math.abs(x - hanging) > em * 0.05) return []
        result[result.length - 1] += ' ' + text
        wraps++
      }
    }
    return result.length >= 4 &&
      wraps >= 2 &&
      result.every((record) => {
        const publication = publicationYear.exec(record)?.[1]
        return (
          author.test(record) &&
          publication &&
          (locator.test(publication) || /^in (?:[^\s]+\s+){4,}[^\s]+$/u.test(publication))
        )
      }) &&
      result.filter((record) => locator.test(record)).length >= result.length - 2
      ? result
      : []
  }
  const leftRecords = records(left, 0),
    rightRecords = records(right, 1)
  return (
    !!leftRecords.length && !!rightRecords.length && rightRecords[0][0] > leftRecords.at(-1)![0]
  )
}

// A low left-hand heading can introduce compact references that continue above it on the right.
function nativeCompactAuthorDateContinuation(
  heading: LayoutUnit,
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): string[] {
  if (
    !heading.sourceOnly ||
    heading.preserve !== 'reference' ||
    !/^(?:References|Bibliography)$/iu.test(heading.source) ||
    heading.items.length !== 1 ||
    heading.fragments.length !== 1
  )
    return []
  const fragment = heading.fragments[0],
    page = pages[fragment.page - 1],
    index = Number(heading.items[0].split(':')[1]),
    title = page?.items[index]
  if (
    !page ||
    page.page !== fragment.page ||
    page.rotation !== 0 ||
    !title ||
    title.str !== heading.source ||
    !nativeHorizontalSourceItem(title) ||
    title.transform[5] > page.height * 0.2 ||
    title.transform[4] + title.width > page.width / 2
  )
    return []
  // A lower right column can start inside the page midpoint after a full-width figure.
  const middle = page.width / 2,
    after = page.items.slice(index + 1),
    rightAt = after.findIndex(
      (part) =>
        part.str.trim() &&
        (part.transform[4] > middle ||
          (page.page === pageCount &&
            part.transform[4] >= middle - part.height &&
            part.transform[5] > title.transform[5] + part.height * 4 &&
            part.transform[5] < page.height / 2))
    ),
    rightStart = after[rightAt],
    font = rightStart?.height,
    insetRail = rightStart?.transform[4] <= middle
  if (
    !font ||
    title.fontName === rightStart.fontName ||
    rightStart.transform[5] <= title.transform[5] + font * 3
  )
    return []
  const left = after.slice(0, rightAt).filter((part) => part.str.trim())
  if (
    !left.length ||
    Math.abs(title.transform[4] - left[0].transform[4] + (insetRail ? 0 : font * 0.5)) >
      font * 0.2 ||
    (insetRail && (title.height < font * 1.1 || left.at(-1)!.transform[5] > page.height * 0.08))
  )
    return []
  // The continuation may have an independent colophon. Require definite outdent and vertical gap.
  const rightEnd = after.findIndex(
    (part, at) =>
      at > rightAt && part.str.trim() && part.transform[4] < rightStart.transform[4] - font * 0.3
  )
  const right = after
    .slice(rightAt, rightEnd < 0 ? undefined : rightEnd)
    .filter((part) => part.str.trim())
  if (
    rightEnd >= 0 &&
    !(insetRail && after.slice(rightEnd).every((part) => part.transform[5] < page.height * 0.05)) &&
    (after[rightEnd].transform[4] < rightStart.transform[4] - font ||
      right.at(-1)!.transform[5] - after[rightEnd].transform[5] <= font * 2)
  )
    return []
  const rightItems = new Set(right)
  const domain = nativeProseProofDomain(right)
  if (
    !domain ||
    page.items.some(
      (part) => part.str.trim() && !rightItems.has(part) && nativeProseRowOverlap(part, domain)
    )
  )
    return []
  const records = (items: PdfLayoutTextItem[], edge: number): string[] => {
    // A grave accent can overprint the first letter of the second run of a citation.
    const rows = nativeReferenceRows(items, true, insetRail)
    if (!rows?.length) return []
    const x = rows[0][0].transform[4]
    const entries: string[] = []
    for (const [at, row] of rows.entries()) {
      const indent = row[0].transform[4] - x
      const gap = at ? rows[at - 1][0].transform[5] - row[0].transform[5] : font
      if (
        gap < font * 0.9 ||
        gap > font * 1.5 ||
        (!row.at(-1)!.hasEOL && !(insetRail && at === rows.length - 1)) ||
        row.some(
          (part) =>
            part.fontName !== rightStart.fontName ||
            Math.abs(part.height - font) > font * 0.03 ||
            part.transform[4] < x - font * 0.05 ||
            part.transform[4] + part.width > edge
        )
      )
        return []
      const text = row.map((part) => part.str).join(' ')
      if (Math.abs(indent) < font * 0.05) entries.push(text)
      else if (
        entries.length &&
        (insetRail
          ? Math.abs(indent - font) < font * 0.06
          : indent > font * 0.35 && indent < font * 0.7)
      )
        entries[entries.length - 1] += ' ' + text
      else return []
    }
    return entries.every(
      (entry) =>
        /^\p{Lu}[\p{L}’'-]+ (?:[\p{Lu}][\p{L}-]+ )?[A-Z]\./u.test(entry) &&
        (/[,.] (?:19|20)\d{2}[a-z]?, (?:arXiv:\d{4}\.\d{4,5}|.+(?:, [A-Z]?\d+[.]?| submitted))$/u.test(
          entry
        ) ||
          (insetRail &&
            edge < middle &&
            /[,.] (?:19|20)\d{2}[a-z]?, in .+, pp?\. \d+(?:[–-]\d+)?[.]?$/u.test(entry)))
    )
      ? entries
      : []
  }
  const leftRecords = records(left, insetRail ? rightStart.transform[4] - font * 0.8 : middle),
    rightRecords = records(right, page.width)
  if (
    leftRecords.length < 3 ||
    rightRecords.length < 4 ||
    (insetRail &&
      !rightRecords.every((record) =>
        /, (?:19|20)\d{2}[a-z]?, [\p{L}.& ]+, \d+, [A-Z]?\d+[.]?$/u.test(record)
      )) ||
    !rightRecords.some((record) => right.some((part) => part.str === record)) ||
    rightRecords[0][0] <= leftRecords.at(-1)![0]
  )
    return []
  return after.flatMap((part, at) =>
    rightItems.has(part) ? [`${page.page}:${index + at + 1}`] : []
  )
}

// A terminal bibliography can end with a separate typesetting credit. The
// smaller right-hand records can start above the established left heading.
function nativeTerminalAuthorDateBeforeColophon(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): string[] {
  const page = pages.at(-1)
  if (!page || page.rotation || page.page !== pageCount) return []
  const middle = page.width / 2
  const headings = units.filter(
    (unit) =>
      unit.sourceOnly &&
      unit.preserve === 'reference' &&
      /^(?:references|bibliography)$/iu.test(unit.source) &&
      unit.items.length === 1 &&
      unit.fragments.length === 1 &&
      unit.fragments[0].page === page.page &&
      unit.fragments[0].rect.right < middle
  )
  if (headings.length !== 1) return []
  const heading = headings[0]
  const anchor = Number(heading.items[0].split(':')[1])
  const title = page.items[anchor]
  if (!nativeHorizontalSourceItem(title)) return []
  const packet = page.items.flatMap((item, index) =>
    index > anchor && item.str.trim() ? [{ item, key: `${page.page}:${index}` }] : []
  )
  const turn = packet.findIndex(({ item }) => item.transform[4] >= middle)
  const colophon = packet.findIndex(
    ({ item }, i) =>
      i > turn && /^This (?:paper|article) (?:has been|was) typeset\b/iu.test(item.str)
  )
  const compact = colophon - turn === 3
  if (turn < 4 || (!compact && colophon - turn < 6)) return []
  const left = packet.slice(0, turn)
  const right = packet.slice(turn, colophon)
  const [start, last, credit] = [right[0].item, right.at(-1)!.item, packet[colophon].item]
  const [x, top] = start.transform.slice(4)
  const em = start.height
  const leftStart = left[0].item
  const leftTail = left.findLast(
    ({ item }) => Math.abs(item.transform[4] - leftStart.transform[4]) < em * 0.05
  )!.item
  const preserved = new Set(
    units
      .filter((unit) => unit.sourceOnly && unit.preserve === 'reference')
      .flatMap((unit) => unit.items)
  )
  if (
    title.height < em * 1.05 ||
    title.fontName === start.fontName ||
    Math.abs(title.transform[4] - leftStart.transform[4]) > em * 0.05 ||
    title.transform[5] - leftStart.transform[5] < em * 1.2 ||
    title.transform[5] - leftStart.transform[5] > em * 2.4 ||
    leftStart.fontName !== start.fontName ||
    left.at(-1)!.item.transform[5] > page.height * 0.12 ||
    !left.every(({ key }) => preserved.has(key)) ||
    x - middle > em * 2 ||
    top < page.height * 0.85 ||
    top - title.transform[5] < em * 5 ||
    !nativeHorizontalSourceItem(credit) ||
    Math.abs(credit.transform[4] - x) > em * 0.05 ||
    last.transform[5] - credit.transform[5] < em * 2.4
  )
    return []
  const items = right.map(({ item }) => item)
  const domain = nativeProseProofDomain(items)
  const owned = new Set(items)
  if (
    !domain ||
    !nativeReferenceText(items) ||
    page.items.some(
      (item) => item.str.trim() && !owned.has(item) && nativeProseRowOverlap(item, domain)
    )
  )
    return []
  const rows = [...Map.groupBy(items, (item) => item.transform[5]).values()]
  const records: string[] = []
  let indent: number | undefined
  for (const [at, row] of rows.entries()) {
    const [first, suffix] = row
    const offset = first.transform[4] - x
    const pitch = at ? rows[at - 1][0].transform[5] - first.transform[5] : em * 1.25
    if (
      Math.abs(pitch - em * 1.25) > em * 0.08 ||
      row.length > 2 ||
      !row.at(-1)!.hasEOL ||
      row.some(
        (item) =>
          item.fontName !== start.fontName ||
          Math.abs(item.height - em) > em * 0.02 ||
          item.transform[4] + item.width > page.width
      ) ||
      (suffix &&
        (first.hasEOL ||
          !/\p{L}[´¨]$/u.test(first.str) ||
          !/^\p{Ll}/u.test(suffix.str) ||
          Math.abs(suffix.transform[4] - first.transform[4] - first.width) > em * 0.6))
    )
      return []
    const source = row.map((item) => item.str).join('')
    if (Math.abs(offset) < em * 0.05) records.push(source)
    else {
      if (!records.length || offset < em || offset > em * 2.2) return []
      indent ??= offset
      if (Math.abs(offset - indent) > em * 0.05) return []
      records[records.length - 1] += ' ' + source
    }
  }
  const author = /^\p{Lu}[\p{L}’'.-]*(?: [\p{L}’'.-]+){0,3} (?:\p{Lu}\. ?){1,4}(?:,|et al\.,)/u
  const publication = /, (?:18|19|20)\d{2}[a-z]?, [\p{L}&., ]+, \d{1,5}, [A-Z]?\d{1,9}\.?$/u
  if (compact) {
    const consecutive = /^(.+?,) .+, ((?:18|19|20)\d{2})b, /u.exec(records[0] ?? '')
    const preceding = /^(.+?,) .+, ((?:18|19|20)\d{2})a, /u.exec(leftTail.str)
    return records.length === 2 &&
      indent !== undefined &&
      preceding &&
      consecutive &&
      preceding[1] === consecutive[1] &&
      preceding[2] === consecutive[2] &&
      author.test(records[0]) &&
      author.test(records[1]) &&
      publication.test(records[0]) &&
      /, (?:18|19|20)\d{2}[a-z]?, arXiv e-prints, p\. arXiv:\d{4}\.\d{4,5}(?:v\d+)?$/u.test(
        records[1]
      ) &&
      records[1][0] > records[0][0]
      ? right.map(({ key }) => key)
      : []
  }
  return records.length >= 4 &&
    indent !== undefined &&
    records[0][0] >= leftTail.str[0] &&
    records.every((record) => author.test(record) && publication.test(record))
    ? right.map(({ key }) => key)
    : []
}

// A short journal-reference tail can wrap from the foot of the left column
// to the top of a right rail that starts just before the page midpoint.
function nativeTerminalJournalReferenceKeys(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): string[] {
  const page = pages.at(-1)
  if (!page || page.rotation || page.page !== pageCount) return []
  const middle = page.width / 2
  const headings = units.filter(
    (unit) =>
      unit.preserve === 'reference' &&
      /^(?:references|bibliography)$/iu.test(unit.source) &&
      unit.items.length === 1 &&
      unit.fragments.length === 1 &&
      unit.fragments[0].page === page.page &&
      unit.fragments[0].rect.right < middle
  )
  if (headings.length !== 1) return []
  const heading = headings[0],
    anchor = Number(heading.items[0].split(':')[1]),
    title = page.items[anchor]
  if (!nativeHorizontalSourceItem(title)) return []
  const entries = page.items.flatMap((item, index) =>
    index > anchor && item.str.trim() ? [{ item, key: `${page.page}:${index}` }] : []
  )
  const body = entries.filter(({ item }) => item.transform[5] >= page.height * 0.05)
  const turn = body.findIndex(
    ({ item }) =>
      item.transform[4] >= middle - item.height * 0.2 &&
      item.transform[5] > Math.max(page.height * 0.85, title.transform[5] + item.height)
  )
  if (turn < 2 || body.length - turn < 2) return []
  const left = body.slice(turn - 2, turn),
    right = body.slice(turn),
    font = right[0].item.height,
    rail = right[0].item.transform[4]
  const citation = /^\p{Lu}[\p{L}’'.-]+ (?:\p{Lu}\.){1,3}, .+$/u
  const journalLocator =
    /(?:, |\. )(?:18|19|20)\d{2}[a-z]?,? [\p{L}][\p{L} .]+, \d{1,5}, [A-Z]?\d{1,9}(?:[–-]\d{1,9})?\.$/u
  const closed = (lane: typeof body, x: number, edge: number): boolean =>
    nativeReferenceRows(lane.map(({ item }) => item))?.length === lane.length &&
    lane.every(({ item }, index) => {
      const [itemX, y] = item.transform.slice(4)
      const gap = index ? lane[index - 1].item.transform[5] - y : font * 1.25
      return (
        item.fontName === right[0].item.fontName &&
        Math.abs(item.height - font) < font * 0.03 &&
        Math.abs(itemX - x) < font * 0.08 &&
        itemX + item.width < edge &&
        item.hasEOL &&
        gap > font * 1.1 &&
        gap < font * 1.4 &&
        citation.test(item.str) &&
        journalLocator.test(item.str)
      )
    })
  const preservedKeys = new Set(
    units.filter((unit) => unit.preserve === 'reference').flatMap((unit) => unit.items)
  )
  if (
    rail > middle + page.width * 0.08 ||
    right.some(({ item }) => item.transform[5] < page.height * 0.8) ||
    left.at(-1)!.item.transform[5] > page.height * 0.1 ||
    !left.every(({ key }) => preservedKeys.has(key)) ||
    !closed(left, title.transform[4], rail) ||
    !closed(right, rail, page.width)
  )
    return []
  return right.map(({ key }) => key)
}

// Faux bold can paint the bibliography heading and journal volumes four times.
function nativeOverprintedReferenceSpan(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): LayoutUnit[] {
  const page = pages.at(-1)
  if (!page || page.page !== pageCount || page.rotation !== 0) return []
  const entries = page.items.flatMap((item, index) => (item.str.trim() ? [{ item, index }] : []))
  const at = entries.findIndex(({ item }) => /^(?:References|Bibliography)$/u.test(item.str))
  if (at < 0) return []
  const heading = entries.slice(at, at + 4).map(({ item }) => item)
  const [title] = heading,
    em = title.height,
    middle = page.width / 2
  const x = (item: PdfLayoutTextItem): number => item.transform[4]
  const y = (item: PdfLayoutTextItem): number => item.transform[5]
  const near = (a: number, b: number): boolean => Math.abs(a - b) < em * 0.05
  const sharesFace = (item: PdfLayoutTextItem): boolean =>
    item.fontName === title.fontName && near(item.height, em)
  const corners = new Set(heading.map((item) => `${x(item)}:${y(item)}`))
  if (
    heading.length !== 4 ||
    corners.size !== 4 ||
    new Set(heading.map(x)).size !== 2 ||
    new Set(heading.map(y)).size !== 2 ||
    heading.some(
      (item) =>
        item.str !== title.str ||
        !sharesFace(item) ||
        !near(item.width, title.width) ||
        !near(x(item), x(title)) ||
        !near(y(item), y(title))
    ) ||
    heading.slice(0, 3).some((item) => item.hasEOL) ||
    !heading[3].hasEOL ||
    x(title) < middle ||
    x(title) > middle + em * 2
  )
    return []
  const packet = entries.slice(at + 4).map(({ item }) => item)
  if (
    packet.length < 16 ||
    packet.length > 1000 ||
    !nativeReferenceText([...heading, ...packet]) ||
    packet.some(
      (item) => !sharesFace(item) || x(item) <= x(title) || x(item) + item.width > page.width
    )
  )
    return []
  const rows: PdfLayoutTextItem[][] = []
  for (const item of packet) {
    const last = rows.at(-1)
    if (last && near(y(last[0]), y(item))) last.push(item)
    else rows.push([item])
  }
  const markerRail = x(rows[0][0]),
    bodyRail = x(rows[0][1] ?? rows[0][0])
  if (
    markerRail - x(title) > em * 1.2 ||
    bodyRail - markerRail < em ||
    bodyRail - markerRail > em * 3
  )
    return []
  let prior = title,
    closed = true,
    number = 0,
    hasVolume = false
  for (const [index, row] of rows.entries()) {
    const [first, second] = row,
      pitch = y(prior) - y(first)
    if (pitch < em || pitch > em * 1.25 || (index < rows.length - 1 && !row.at(-1)!.hasEOL))
      return []
    prior = first
    if (near(x(first), markerRail)) {
      if (
        !closed ||
        first.str !== `${++number}.` ||
        !second ||
        !near(x(second), bodyRail) ||
        !/^\p{Lu}\.(?:[ -]|\p{Lu})/u.test(second.str + ' ')
      )
        return []
      closed = false
      hasVolume = false
    } else if (closed || !near(x(first), bodyRail)) return []
    hasVolume ||= row.some((item, n) => {
      const next = row[n + 1],
        suffix = row[n + 2]
      return (
        /^\d{1,4}$/u.test(item.str) &&
        next?.str === item.str &&
        suffix?.str.startsWith(item.str + ',') &&
        near(x(item), x(next)) &&
        near(x(item), x(suffix)) &&
        near(item.width, next.width) &&
        x(item) !== x(next) &&
        y(item) === y(next) &&
        y(item) !== y(suffix)
      )
    })
    closed = /\((?:18|19|20)\d{2}\)\.$/u.test(row.at(-1)!.str)
    if (closed && !hasVolume) return []
  }
  if (!closed || number < 3) return []
  const keys = new Set(entries.slice(at).map(({ index }) => `${page.page}:${index}`))
  const owners = units.filter((unit) => unit.items.some((key) => keys.has(key)))
  const owned = owners.flatMap((unit) => unit.items)
  return owned.length === keys.size &&
    new Set(owned).size === keys.size &&
    owned.every((key) => keys.has(key)) &&
    owners.every((unit) => !unit.figure)
    ? owners
    : []
}

// A reference heading can share its owner with a raised ordinal on the next line.
// Three closed entries on the same native rail establish the bibliography boundary.
function nativeRaisedBibliographyStart(
  entries: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): boolean {
  const [first, second, third] = entries
  const closed = (text: string): boolean => /\d{1,8} \((?:18|19|20)\d{2}\)\.$/u.test(text)
  if (
    !third ||
    !pageCount ||
    pages.length !== pageCount ||
    !/^REFERENCES 1\p{Lu}\./u.test(first.source) ||
    !/^2\p{Lu}\./u.test(second.source) ||
    !/^3\p{Lu}\./u.test(third.source) ||
    entries.some(
      (unit) =>
        unit.fragments.length !== 1 || unit.figure || unit.referenceBoundary || !closed(unit.source)
    )
  )
    return false
  const page = pages[first.fragments[0].page - 1]
  if (
    !page ||
    page.page < pageCount - 1 ||
    page.rotation ||
    first.fragments[0].rect.x > page.width * 0.15 ||
    entries.some((unit) => unit.fragments[0].page !== page.page)
  )
    return false
  const [title, marker, name] = nativeReferenceItems(first, pages)
  if (
    ![title, marker, name].every(nativeHorizontalSourceItem) ||
    title.str !== 'REFERENCES' ||
    title.fontName === name.fontName ||
    title.height < name.height * 1.08 ||
    title.height > name.height * 1.18
  )
    return false
  const em = name.height
  const x = (item: PdfLayoutTextItem): number => item.transform[4]
  const y = (item: PdfLayoutTextItem): number => item.transform[5]
  const near = (a: number, b: number): boolean => Math.abs(a - b) < em * 0.05
  const raised = (number: PdfLayoutTextItem, author: PdfLayoutTextItem): boolean =>
    [number, author].every(nativeHorizontalSourceItem) &&
    /^[1-9]\d{0,2}$/u.test(number.str) &&
    number.fontName === marker.fontName &&
    author.fontName === name.fontName &&
    number.fontName !== author.fontName &&
    near(number.height, marker.height) &&
    near(author.height, em) &&
    number.height > em * 0.55 &&
    number.height < em * 0.73 &&
    near(x(author), x(number) + number.width) &&
    y(number) - y(author) > em * 0.24 &&
    y(number) - y(author) < em * 0.39 &&
    /^\p{Lu}\. (?:\p{Lu}\. )?\p{Lu}\p{Ll}{2,},/u.test(author.str)
  const packet = entries.flatMap((unit) => nativeReferenceItems(unit, pages))
  const start = page.items.indexOf(title)
  const finish = page.items.indexOf(packet.at(-1)!)
  const visible = page.items.slice(start, finish + 1).filter((item) => item.str.trim())
  const titleGap = y(title) - y(name)
  if (
    !near(x(title), x(marker)) ||
    titleGap <= em * 1.3 ||
    titleGap >= em * 1.65 ||
    packet.length !== visible.length ||
    visible.some((item, i) => item !== packet[i]) ||
    entries.some((unit, i) => {
      const [number, author] = nativeReferenceItems(unit, pages).slice(i === 0 ? 1 : 0)
      return !raised(number, author) || number.str !== String(i + 1) || !near(x(number), x(marker))
    })
  )
    return false

  // The higher right column belongs to the same bibliography only when its
  // first line closes the left column's final citation before numbering resumes.
  const later = page.items.slice(finish + 1).filter((item) => item.str.trim())
  const turn = later.findIndex((item) => x(item) > page.width / 2)
  const leftEnd = later[turn - 1]
  const rightStart = later[turn]
  if (
    turn < 1 ||
    ![leftEnd, rightStart].every(nativeHorizontalSourceItem) ||
    closed(leftEnd.str) ||
    y(leftEnd) > page.height * 0.15 ||
    y(rightStart) < page.height * 0.85 ||
    !near(leftEnd.height, em) ||
    !near(rightStart.height, em)
  )
    return false

  const left = later.slice(0, turn)
  const right = later.slice(turn)
  const lastOrdinal = left.findLast(
    (item, i) => near(x(item), x(marker)) && raised(item, left[i + 1])
  )
  const firstOrdinalAt = right.findIndex(
    (item, i) => near(x(item), x(rightStart)) && raised(item, right[i + 1])
  )
  const firstOrdinal = right[firstOrdinalAt]
  const nextOrdinal = right
    .slice(firstOrdinalAt + 1)
    .find((item, i) => near(x(item), x(rightStart)) && raised(item, right[firstOrdinalAt + i + 2]))
  return (
    !!lastOrdinal &&
    !!firstOrdinal &&
    !!nextOrdinal &&
    firstOrdinalAt > 0 &&
    closed(right[firstOrdinalAt - 1].str) &&
    Number(lastOrdinal.str) + 1 === Number(firstOrdinal.str) &&
    Number(firstOrdinal.str) + 1 === Number(nextOrdinal.str)
  )
}

// An explicit native References heading can share a grouped owner with its
// first entry. Keep that complete owner and the closed hanging span intact;
// neither an author-shaped paragraph nor an unbounded suffix establishes it.
function nativeHeadedReferenceSpan(
  units: LayoutUnit[],
  pages: PdfLayoutPage[],
  pageCount: number | undefined
): LayoutUnit[] {
  const native = (u: LayoutUnit): PdfLayoutTextItem[] => nativeReferenceItems(u, pages)
  const footer = (u: LayoutUnit): boolean =>
    u.fragments.length === 1 &&
    /^\d+$/u.test(u.source) &&
    !!pages[u.fragments[0].page - 1] &&
    u.fragments[0].rect.y > pages[u.fragments[0].page - 1].height * 0.9 &&
    Math.abs(
      (u.fragments[0].rect.x + u.fragments[0].rect.right) / 2 -
        pages[u.fragments[0].page - 1].width / 2
    ) < u.fragments[0].rect.font
  const ownership = new Map<string, number>()
  for (const unit of units)
    for (const key of unit.items) ownership.set(key, (ownership.get(key) ?? 0) + 1)
  const passes: LayoutUnit[][] = []
  for (const [index, unit] of units.entries()) {
    if (unit.preserve === 'reference' || unit.fragments.length !== 1) continue
    const items = native(unit),
      title = items[0],
      first = items[1],
      start = unit.fragments[0]
    if (
      !title ||
      !first ||
      !/^(?:References|Bibliography)$/u.test(title.str) ||
      !nativeReferenceText(items) ||
      title.fontName === first.fontName ||
      Math.abs(title.height - first.height) > title.height * 0.02 ||
      Math.abs(title.transform[4] - first.transform[4]) > title.height * 0.05 ||
      title.transform[5] - first.transform[5] < title.height ||
      title.transform[5] - first.transform[5] > title.height * 1.6
    )
      continue
    const page = pages[start.page - 1]
    if (
      page &&
      page.page === pageCount &&
      pages.length === pageCount &&
      !page.rotation &&
      !unit.figure &&
      !unit.referenceBoundary &&
      unit.items.every((key) => ownership.get(key) === 1) &&
      nativeTerminalHeadedReferenceOwner(unit, items, page)
    ) {
      passes.push([unit])
      continue
    }
    const end = units.findIndex((candidate, n) => {
      if (
        n <= index ||
        n - index > 256 ||
        candidate.fragments.length !== 1 ||
        candidate.risks.length ||
        candidate.kind !== 'heading-candidate'
      )
        return false
      const a = native(candidate),
        r = candidate.fragments[0],
        p = pages[r.page - 1]
      return (
        !!p &&
        r.page > start.page &&
        r.page <= start.page + 8 &&
        r.rect.y < p.height * 0.16 &&
        a.length === 1 &&
        /^[\p{Lu}][\p{L} ]{3,70}$/u.test(candidate.source) &&
        a[0].fontName === title.fontName &&
        Math.abs(a[0].height - title.height) < title.height * 0.02 &&
        Math.abs(a[0].transform[4] - title.transform[4]) < title.height * 0.05 &&
        nativeReferenceText(a) &&
        p.items
          .filter((i) => i.str.trim())
          .every((i) => i === a[0] || i.transform[5] < a[0].transform[5] - title.height * 0.5)
      )
    })
    if (end < 0) continue
    const boundary = units[end],
      body = units[end + 1]
    if (
      !body ||
      body.fragments.length !== 1 ||
      body.kind !== 'prose-candidate' ||
      body.risks.length ||
      body.fragments[0].page !== boundary.fragments[0].page ||
      wordCount(body.source) < 40 ||
      !terminal(body.source)
    )
      continue
    const bodyItems = native(body),
      b = body.fragments[0],
      h = boundary.fragments[0]
    if (
      !nativeReferenceText(bodyItems) ||
      bodyItems.some(
        (i) =>
          i.fontName !== first.fontName || Math.abs(i.height - first.height) > first.height * 0.02
      ) ||
      b.rect.y - h.rect.bottom < first.height * 0.5 ||
      b.rect.y - h.rect.bottom > first.height * 3 ||
      b.rect.right - b.rect.x < pages[b.page - 1].width * 0.5 ||
      b.rect.x < title.transform[4] - first.height * 0.05 ||
      b.rect.x > title.transform[4] + first.height * 4
    )
      continue
    const span = units.slice(index, end).filter((u) => !footer(u)),
      packet = span.flatMap(native),
      keys = new Set(span.flatMap((u) => u.items))
    if (
      span.length < 6 ||
      packet.length > 4096 ||
      packet.length !== keys.size ||
      !nativeReferenceText(packet) ||
      span.some((u) => u.items.some((k) => ownership.get(k) !== 1))
    )
      continue
    let valid = true,
      starts = 0,
      wraps = 0
    for (const page of pages.slice(start.page - 1, h.page - 1)) {
      const owned = span
        .flatMap((u) => u.items)
        .filter((k) => k.startsWith(page.page + ':'))
        .map((k) => Number(k.split(':')[1]))
        .sort((a, b) => a - b)
      const text = owned.map((n) => page.items[n]),
        rows = nativeReferenceRows(text),
        domain = nativeProseProofDomain(text)
      if (
        !owned.length ||
        !rows ||
        !domain ||
        domain.x < 0 ||
        domain.y < 0 ||
        domain.right > page.width ||
        domain.bottom > page.height ||
        page.items.some(
          (i, n) =>
            i.str.trim() && !keys.has(page.page + ':' + n) && nativeTextOverlapsProof(i, domain)
        ) ||
        page.items
          .slice(owned[0], owned.at(-1)! + 1)
          .some((i, n) => i.str.trim() && !keys.has(page.page + ':' + (owned[0] + n)))
      ) {
        valid = false
        break
      }
      for (const row of rows) {
        if (row[0] === title) {
          if (row.length !== 1) valid = false
          continue
        }
        const x = row[0].transform[4],
          left = title.transform[4],
          delta = x - left
        if (
          delta < -first.height * 0.05 ||
          row.some(
            (i) =>
              Math.abs(i.height - first.height) > first.height * 0.02 ||
              i.fontName === title.fontName
          )
        ) {
          valid = false
          break
        }
        if (Math.abs(delta) < first.height * 0.05) starts++
        else if (delta > first.height && delta < first.height * 3) wraps++
        else {
          valid = false
          break
        }
      }
    }
    if (valid && starts >= 3 && wraps >= 3) passes.push(span)
  }
  return passes.length === 1 ? passes[0] : []
}

// A flush bibliography in one owner needs a complete terminal text span and
// repeated citation evidence, since a heading can also introduce ordinary prose.
function nativeTerminalHeadedReferenceOwner(
  unit: LayoutUnit,
  items: PdfLayoutTextItem[],
  page: PdfLayoutPage
): boolean {
  const [title, first] = items,
    em = title.height,
    left = title.transform[4],
    headingIndex = Number(unit.items[0].split(':')[1]),
    suffix = page.items.slice(headingIndex).filter((item) => item.str.trim()),
    folio = suffix.pop()
  if (
    !folio ||
    folio.str !== String(page.page) ||
    folio.transform[5] > page.height * 0.08 ||
    Math.abs(folio.transform[4] - left) > em * 0.05 ||
    folio.fontName !== first.fontName ||
    suffix.length !== items.length ||
    suffix.some((item, index) => item !== items[index])
  )
    return false
  const rows = nativeReferenceRows(items)
  if (!rows || rows.length < 7 || rows[0].length !== 1) return false
  let named = 0,
    dated = 0,
    linked = 0
  for (const [index, row] of rows.slice(1).entries()) {
    const pitch = rows[index][0].transform[5] - row[0].transform[5],
      text = row.map((item) => item.str).join(' ')
    if (
      pitch < em ||
      pitch > em * 1.6 ||
      Math.abs(row[0].transform[4] - left) > em * 0.05 ||
      row.some(
        (item) =>
          Math.abs(item.height - em) > em * 0.06 ||
          item.fontName === title.fontName ||
          item.transform[4] + item.width > page.width
      )
    )
      return false
    if (/^(?:\p{Lu}\. *){1,4}\p{Lu}[\p{L}\p{M}’'-]+(?:,| )/u.test(text)) named++
    if (/\((?:19|20)\d{2}\)/u.test(text)) dated++
    if (/https?:\/\//u.test(text)) linked++
  }
  return named >= 4 && dated >= 4 && linked >= 2
}

// A supplement contents page has a separate title and a complete native
// destination lane. Keep each label/title row independent of adjacent entries.
function nativeSupplementContentsRows(page: PdfLayoutPage): Set<number> {
  const visible = page.items.filter((item) => item.str.trim()),
    first = visible[0],
    result = new Set<number>()
  if (
    page.rotation ||
    !/^Supplementary (?:Materials?|Information)$/iu.test(first?.str ?? '') ||
    first.transform[5] < page.height * 0.8
  )
    return result
  const contents = visible.findIndex((item) => /^(?:Table of )?Contents$/iu.test(item.str))
  if (contents < 1 || contents > 8) return result
  const banner = visible[contents],
    entry = visible[contents + 1]
  if (
    !entry ||
    banner.str.toLowerCase() !== entry.str.toLowerCase() ||
    Math.abs(banner.transform[4] + banner.width / 2 - page.width / 2) > banner.height * 0.1 ||
    banner.transform[5] - entry.transform[5] < banner.height ||
    banner.transform[5] - entry.transform[5] > banner.height * 3 ||
    entry.transform[4] > page.width * 0.2
  )
    return result
  const visibleRows = visible
    .slice(contents + 1)
    .filter(
      (item) =>
        !(
          item.transform[5] < page.height * 0.1 &&
          /^\d{1,3}$/u.test(item.str) &&
          Math.abs(item.transform[4] + item.width / 2 - page.width / 2) < item.height
        ) &&
        !(
          item.transform[0] === 0 &&
          item.transform[3] === 0 &&
          item.transform[1] > 0 &&
          item.transform[2] < 0 &&
          item.transform[4] < entry.transform[4] - entry.height
        )
    )
  if (!visibleRows.every(nativeHorizontalSourceItem)) return result
  const rows = nativeOrderedRows(visibleRows)
  if (!rows || rows.length < 7 || rows[0].length !== 2) return result
  const [contentsEntry, firstNumber] = rows[0],
    font = contentsEntry.height,
    pitch = contentsEntry.transform[5] - rows[1][0].transform[5],
    right = firstNumber.transform[4] + firstNumber.width
  if (pitch < font || pitch > font * 1.5 || right < page.width * 0.8 || right > page.width)
    return result
  let root = '@',
    child = 0,
    destination = 0
  const matched: PdfLayoutTextItem[] = []
  for (const [at, row] of rows.entries()) {
    const [label, title, number] = row,
      pageNumber = Number(row.at(-1)!.str)
    if (
      row.some(
        (item) =>
          item.fontName !== contentsEntry.fontName || Math.abs(item.height - font) > font * 0.01
      ) ||
      !/^[1-9]\d{0,2}$/u.test(row.at(-1)!.str) ||
      Math.abs(right - row.at(-1)!.transform[4] - row.at(-1)!.width) > font * 0.08 ||
      (at === 0 ? pageNumber !== 1 : pageNumber < destination || pageNumber > destination + 1) ||
      (at > 0 &&
        Math.abs(rows[at - 1][0].transform[5] - label.transform[5] - pitch) > font * 0.08) ||
      Math.abs(label.transform[4] - contentsEntry.transform[4]) > font * 0.05
    )
      return result
    destination = pageNumber
    if (!at) continue
    const marker = /^([A-Z])(?:\.([1-9]\d?))?$/u.exec(label.str)
    if (
      row.length !== 3 ||
      !number ||
      !marker ||
      !/^\p{Lu}[\p{L}\p{M}\d ’'()–-]{4,110}$/u.test(title.str) ||
      title.transform[4] - label.transform[4] < font * 2 ||
      right - title.transform[4] - title.width < font * 8
    )
      return result
    if (marker[2]) {
      if (marker[1] !== root || Number(marker[2]) !== ++child) return result
    } else {
      if (marker[1].charCodeAt(0) !== root.charCodeAt(0) + 1) return result
      root = marker[1]
      child = 0
    }
    matched.push(label)
  }
  if (root < 'C' || !rows.some(([label]) => label.str.includes('.'))) return result
  return new Set(matched.map((item) => page.items.indexOf(item)))
}

// A post-bibliography Contents page must point back to complete native section
// headings. Typography and dotted rows alone cannot close a bibliography.
function nativeReferenceContentsBoundary(
  unit: LayoutUnit,
  reference: LayoutUnit | undefined,
  pages: PdfLayoutPage[]
): boolean {
  if (
    !reference ||
    unit.source !== 'Contents' ||
    unit.kind !== 'heading-candidate' ||
    unit.risks.length ||
    unit.fragments.length !== 1
  )
    return false
  const native = (u: LayoutUnit): PdfLayoutTextItem[] => nativeReferenceItems(u, pages)
  const title = native(unit),
    ref = native(reference),
    fragment = unit.fragments[0],
    page = pages[fragment.page - 1],
    h = title[0]?.height
  if (
    title.length !== 1 ||
    !nativeReferenceText(title) ||
    !ref.length ||
    title[0].fontName !== ref[0].fontName ||
    Math.abs(h - reference.fragments[0].rect.font) > h * 0.02 ||
    fragment.page <= reference.fragments[0].page ||
    fragment.rect.y > page.height * 0.16 ||
    Math.abs(title[0].transform[4] - ref[0].transform[4]) > h * 0.05
  )
    return false
  const text = page.items
    .filter((i) => i.str.trim())
    .filter(
      (i) =>
        !(
          /^\d+$/u.test(i.str) &&
          i.transform[5] < page.height * 0.08 &&
          Math.abs(i.transform[4] + i.width / 2 - page.width / 2) < h
        )
    )
  const rows = nativeReferenceRows(text)
  const contentsDomain = nativeProseProofDomain(text)
  if (
    !rows ||
    rows[0].length !== 1 ||
    rows[0][0] !== title[0] ||
    rows.length < 6 ||
    !contentsDomain ||
    contentsDomain.x < 0 ||
    contentsDomain.y < 0 ||
    contentsDomain.right > page.width ||
    contentsDomain.bottom > page.height
  )
    return false
  const entries: { label: string; title: string; page: number; items: PdfLayoutTextItem[] }[] = [],
    size = rows[1][0].height,
    left = title[0].transform[4]
  const columns = new Map<number, number>([[0, left]])
  for (let n = 1; n < rows.length; n++) {
    const row = rows[n],
      last = row.at(-1)!,
      label = row[0].str
    if (row.some((i) => Math.abs(i.height - size) > size * 0.02) || size >= h / 1.15) return false
    const destination =
      /^[1-9]\d*$/u.test(last.str) && last.transform[4] > page.width * 0.75
        ? Number(last.str)
        : undefined
    const head = /^(?:[A-Z](?:\.\d+)*|[1-9]\d*(?:\.\d+)*)$/u.test(label)
    if (head) {
      const depth = label.split('.').length - 1
      const x = row[0].transform[4],
        column = columns.get(depth),
        parent = columns.get(depth - 1)
      if (
        row.length < 2 ||
        depth > 3 ||
        x > page.width * 0.35 ||
        (column !== undefined
          ? Math.abs(x - column) > size * 0.05
          : parent === undefined || x < parent + size * 0.5)
      )
        return false
      columns.set(depth, x)
      entries.push({
        label,
        title: row
          .slice(1, destination === undefined ? undefined : -1)
          .map((i) => i.str)
          .join(' ')
          .replace(/(?:\s*\.\s*){2,}/gu, ' ')
          .trim(),
        page: destination ?? 0,
        items: row
      })
    } else {
      const prior = entries.at(-1)
      if (
        !prior ||
        prior.page ||
        !prior.title.endsWith('-') ||
        row[0].transform[4] <= left + size * 0.5 ||
        !destination
      )
        return false
      prior.title =
        prior.title.slice(0, -1) +
        row
          .slice(0, -1)
          .map((i) => i.str)
          .join(' ')
      prior.page = destination
      prior.items.push(...row)
    }
  }
  if (
    new Set(entries.map((e) => e.label)).size !== entries.length ||
    entries.some((e) => !e.page || e.page > pages.length || !e.title || /[.!?]$/u.test(e.title))
  )
    return false
  let anchors = 0
  for (const e of entries.filter(
    (e) => /^[1-9]\d*$/u.test(e.label) && e.page < reference.fragments[0].page
  )) {
    const target = pages[e.page - 1]
    if (!target) continue
    const tt = target.items.filter((i) => i.str.trim()),
      matches = tt.flatMap((item, n) => {
        const pair = tt.slice(n, n + 2),
          r = nativeReferenceRows(pair)
        if (
          !r ||
          r.length !== 1 ||
          r[0][0].str !== e.label ||
          r[0]
            .slice(1)
            .map((i) => i.str)
            .join(' ') !== e.title ||
          r[0].some((i) => i.fontName !== title[0].fontName || Math.abs(i.height - h) > h * 0.02) ||
          Math.abs(item.transform[4] - left) > h * 0.05
        )
          return []
        const domain = nativeProseProofDomain(pair)!
        if (
          domain.x < 0 ||
          domain.y < 0 ||
          domain.right > target.width ||
          domain.bottom > target.height
        )
          return []
        return target.items.some(
          (i) => i.str.trim() && !pair.includes(i) && nativeTextOverlapsProof(i, domain)
        )
          ? []
          : [pair]
      })
    if (matches.length !== 1) continue
    anchors++
  }
  return anchors >= 3
}

const letterSpacedReferenceHeading = /^R +e +f +e +r +e +n +c +e +s$/iu

// Some centered bibliographies start with one hanging journal entry per column.
function nativePairedHangingJournals(
  unit: LayoutUnit,
  heading: LayoutUnit,
  pages: PdfLayoutPage[]
): boolean {
  const journal = /^\p{Lu}[\p{L}’& -]{5,55}, \d{1,5}, [A-Z]?\d{1,6}$/u
  if (
    unit.sourceOnly ||
    unit.preserve ||
    unit.risks.length ||
    !journal.test(unit.source) ||
    !/^References$/iu.test(heading.source) ||
    [heading, unit].some((owner) => owner.items.length !== 1 || owner.fragments.length !== 1)
  )
    return false
  const page = pages[heading.fragments[0].page - 1]
  if (!page || page.rotation || unit.fragments[0].page !== page.page) return false
  const [title] = nativeReferenceItems(heading, pages)
  const [tail] = nativeReferenceItems(unit, pages)
  if (!title || !tail) return false
  const [left, leftJournal, right, rightJournal] = page.items
    .slice(page.items.indexOf(title) + 1)
    .filter((item) => item.str.trim())
  const lead = /^\p{Lu}[\p{L}’'-]+, (?:\p{Lu}\. ?)+, .+\b(?:19|20)\d{2}[a-z]?, The$/u
  if (
    !left ||
    leftJournal !== tail ||
    !right ||
    !rightJournal ||
    !nativeReferenceText([title, left, tail, right, rightJournal]) ||
    title.str !== heading.source ||
    tail.str !== unit.source ||
    !lead.test(left.str) ||
    !lead.test(right.str) ||
    !journal.test(rightJournal.str) ||
    !left.hasEOL ||
    !right.hasEOL
  )
    return false
  const size = left.height
  const center = page.width / 2
  const [leftX, y] = left.transform.slice(4)
  const [tailX, tailY] = tail.transform.slice(4)
  const [rightX, rightY] = right.transform.slice(4)
  const [peerX, peerY] = rightJournal.transform.slice(4)
  return (
    Math.abs(title.transform[4] + title.width / 2 - center) < size * 0.08 &&
    title.height > size &&
    title.transform[5] - y > size &&
    title.transform[5] - y < size * 3 &&
    [tail, right, rightJournal].every(
      (item) => item.height === size && item.fontName === left.fontName
    ) &&
    leftX + left.width < center &&
    rightX > center &&
    tailX + tail.width < leftX + left.width &&
    peerX + rightJournal.width < rightX + right.width &&
    tailX - leftX > size * 0.8 &&
    tailX - leftX < size * 1.3 &&
    Math.abs(tailX - leftX - peerX + rightX) < size * 0.05 &&
    Math.abs(y - rightY) < size * 0.05 &&
    Math.abs(tailY - peerY) < size * 0.05 &&
    y - tailY > size &&
    y - tailY < size * 3
  )
}

// A short hanging row may sit left of a centered heading despite belonging to
// an entry between two native author-date leads in the same bibliography.
function nativeHangingAuthorDateTail(
  tail: LayoutUnit,
  entry: LayoutUnit | undefined,
  next: LayoutUnit | undefined,
  heading: LayoutUnit,
  pages: PdfLayoutPage[]
): boolean {
  const authorDate = /^\p{Lu}[\p{L}\p{M} ’'-]+, (?:\p{Lu}\. ?)+.*? \((?:19|20)\d{2}[a-z]?\)\. /u
  if (
    tail.sourceOnly ||
    tail.preserve ||
    tail.figure ||
    tail.risks.length ||
    entry?.preserve !== 'reference' ||
    !next ||
    !authorDate.test(entry.source) ||
    !authorDate.test(next.source) ||
    terminal(entry.source) ||
    !/^(?:\p{Lu}[\p{L}\p{M}’'-]+|[\p{L}][\p{L}\p{M} ’'-]+, \d+(?:\(\d+\))?, \d+(?:[-–]\d+)?)\.$/u.test(
      tail.source
    ) ||
    !/^References$/iu.test(heading.source)
  )
    return false
  const page = pages[heading.fragments[0].page - 1]
  if (
    !page ||
    page.rotation ||
    [heading, entry, tail, next].some(
      (unit) => unit.fragments.length !== 1 || unit.fragments[0].page !== page.page
    )
  )
    return false
  const [title] = nativeReferenceItems(heading, pages),
    lead = nativeReferenceItems(entry, pages),
    continuation = nativeReferenceItems(tail, pages),
    [following] = nativeReferenceItems(next, pages),
    [first] = lead,
    [start] = continuation
  if (!title || !first || !start || !following) return false

  const em = first.height,
    rise = first.transform[5] - start.transform[5],
    gap = start.transform[5] - following.transform[5],
    indent = start.transform[4] - first.transform[4],
    startIndex = page.items.indexOf(lead.at(-1)!),
    endIndex = page.items.indexOf(following),
    between = page.items.slice(startIndex + 1, endIndex).filter((item) => item.str.trim())
  return (
    nativeReferenceRows([...lead, ...continuation])?.length === 2 &&
    Math.abs(title.transform[4] + title.width / 2 - page.width / 2) < em * 0.05 &&
    title.transform[5] > first.transform[5] &&
    first.fontName === following.fontName &&
    Math.abs(first.transform[4] - following.transform[4]) < em * 0.05 &&
    [...lead, ...continuation, following].every((item) => Math.abs(item.height - em) < em * 0.05) &&
    indent > em &&
    indent <= em * 4 &&
    rise > em &&
    rise < em * 1.6 &&
    gap > rise &&
    gap <= em * 3 &&
    between.length === continuation.length &&
    between.every((item, index) => item === continuation[index])
  )
}

// A short hanging publication locator can fall entirely left of a centered heading.
function nativeHangingPublicationLocator(
  unit: LayoutUnit,
  entry: LayoutUnit | undefined,
  heading: LayoutUnit,
  pages: PdfLayoutPage[]
): boolean {
  const locator = /^\p{Lu}[\p{L} .-]{5,55}, ((?:19|20)\d{2})-[A-Z]\d{1,5}$/u.exec(unit.source)
  if (
    !locator ||
    unit.sourceOnly ||
    unit.preserve ||
    unit.risks.length ||
    entry?.preserve !== 'reference' ||
    !/^\p{Lu}[\p{L}’'-]+ (?:\p{Lu}\. ?)+, .+\b(?:19|20)\d{2}, \p{Lu}[\p{L} .-]+$/u.test(
      entry.source
    ) ||
    !entry.source.includes(` ${locator[1]}, `) ||
    !/^References$/iu.test(heading.source)
  )
    return false
  const page = pages[unit.fragments[0].page - 1]
  if (
    !page ||
    page.rotation !== 0 ||
    [unit, entry, heading].some(
      (part) =>
        part.fragments.length !== 1 ||
        part.fragments[0].page !== page.page ||
        part.items.length !== 1
    )
  )
    return false
  const [title] = nativeReferenceItems(heading, pages),
    [start] = nativeReferenceItems(entry, pages),
    [tail] = nativeReferenceItems(unit, pages)
  if (!title || !start || !tail || !nativeReferenceText([title, start, tail])) return false
  const [x, y] = start.transform.slice(4),
    [tailX, tailY] = tail.transform.slice(4),
    size = start.height
  return (
    title.str === heading.source &&
    start.str === entry.source &&
    tail.str === unit.source &&
    Math.abs(title.transform[4] + title.width / 2 - page.width / 2) < size * 0.05 &&
    title.height > size &&
    title.transform[5] - y > size &&
    title.transform[5] - y < size * 3 &&
    start.hasEOL === true &&
    tail.fontName === start.fontName &&
    tail.height === size &&
    y - tailY > size &&
    y - tailY < size * 1.6 &&
    tailX - x > size * 0.8 &&
    tailX - x < size * 1.3 &&
    x + start.width < page.width / 2 &&
    tailX + tail.width < x + start.width &&
    page.items.slice(page.items.indexOf(start) + 1).find((item) => item.str.trim()) === tail &&
    page.items.some(
      (peer) =>
        peer.fontName === start.fontName &&
        peer.height === size &&
        peer.transform[4] > page.width / 2 &&
        Math.abs(peer.transform[5] - y) < size * 0.05 &&
        /^\p{Lu}[\p{L}’'-]+, .+\b(?:19|20)\d{2}, [\p{L}.& ]+, \d+, \d+$/u.test(peer.str) &&
        nativeReferenceText([peer])
    )
  )
}

// A proved full-page centered heading is not the beginning of a right column.
// Keep both its original Source and the exemption for prose above the heading.
function nativeCenteredReferenceHeading(
  heading: LayoutUnit,
  units: LayoutUnit[],
  pages: PdfLayoutPage[]
): boolean {
  if (
    heading.items.length !== 1 ||
    heading.fragments.length !== 1 ||
    heading.originalStrings.length !== 1
  )
    return false
  const page = pages[heading.fragments[0].page - 1],
    items = nativeReferenceItems(heading, pages),
    item = items[0],
    evidence = page?.nativeReferenceEvidence
  if (
    !page ||
    page.rotation !== 0 ||
    !item ||
    item.str !== heading.source ||
    item.str !== heading.originalStrings[0] ||
    !nativeReferenceText(items) ||
    units.filter((unit) => unit.items.includes(heading.items[0])).length !== 1
  )
    return false
  const [x, y] = item.transform.slice(4)
  if (!Number.isFinite(page.width) || page.width <= 0 || x < 0 || x + item.width > page.width)
    return false
  const centerOffset = Math.abs(x + item.width / 2 - page.width / 2)
  if (
    centerOffset < item.height * 0.05 &&
    (item.str === 'REFERENCES' || letterSpacedReferenceHeading.test(item.str))
  ) {
    const index = Number(heading.items[0].split(':')[1])
    const below = page.items
      .slice(index + 1)
      .filter((next) => next.str.trim() && next.transform[5] < y - item.height * 0.5)
    if (letterSpacedReferenceHeading.test(item.str)) {
      const first = below[0]
      if (!first || y - first.transform[5] > item.height * 3) return false
      const labels = below.filter(
        (part) =>
          Math.abs(part.transform[4] - first.transform[4]) < item.height * 0.1 &&
          /^\[[A-Z][A-Za-z]+\d{2}[a-z]?\]$/u.test(part.str)
      )
      return labels[0] === first && labels.length >= 3 && nativeReferenceText(labels)
    }
    // Both lanes can wrap the year onto a hanging row before their publication locator.
    const middle = page.width / 2
    const turn = below.findIndex((part) => part.transform[4] > middle)
    const [leftStart, rightStart] = [below[0], below[turn]]
    const em = leftStart?.height ?? 0
    if (
      page !== pages.at(-1) &&
      turn >= 6 &&
      rightStart &&
      em < item.height * 0.95 &&
      leftStart.fontName !== item.fontName &&
      y - leftStart.transform[5] > em &&
      y - leftStart.transform[5] < em * 2.6 &&
      Math.abs(leftStart.transform[5] - rightStart.transform[5]) < em * 0.05 &&
      below.every((part) => part.fontName === leftStart.fontName && part.height === em) &&
      below.slice(turn).every((part) => part.transform[4] > middle)
    ) {
      const locator =
        /\b(?:doi: (?:10\.\d{4,9}\/\S+|(?:19|20)\d{2}\/\d{1,8})|arXiv:\d{4}\.\d{4,5}(?:v\d+)?)$/iu
      const left = below.slice(0, turn),
        right = below.slice(turn)
      if (
        [left, right].every(
          (lane) =>
            nativeReferenceText(lane) &&
            lane.filter((part) => /\bdoi: 10\.\d{4,9}\/\S+$/iu.test(part.str)).length >= 2
        ) &&
        nativeClosedAuthorDateRows(left, middle, locator) &&
        nativeClosedAuthorDateRows(right, page.width, locator)
      )
        return true
    }
    // A centered label and distinct, repeated author-year rows in both
    // smaller-type columns distinguish this from a right-column heading.
    return [false, true].every((right) => {
      const column = below.filter((part) => part.transform[4] > page.width / 2 === right)
      const first = column[0]
      if (!first || y - first.transform[5] >= item.height * 3 || first.height >= item.height)
        return false
      const onLead = (part: PdfLayoutTextItem): boolean =>
        Math.abs(part.transform[4] - first.transform[4]) < item.height * 0.1 &&
        part.fontName === first.fontName &&
        part.height === first.height
      const authorYear = /^\p{Lu}[\p{L}’'-]+, (?:\p{Lu}\. ?)+.+\b(?:19|20)\d{2}[a-z]?,/u
      const authors = column.filter((part) => onLead(part) && authorYear.test(part.str))
      if (first.fontName === item.fontName) {
        // A larger title can share a face with both smaller hanging citation lanes.
        const opposite = below.find((part) => part.transform[4] > page.width / 2 !== right)
        return (
          page === pages.at(-1) &&
          first.height < item.height * 0.95 &&
          opposite !== undefined &&
          Math.abs(opposite.transform[5] - first.transform[5]) < first.height * 0.05 &&
          nativeReferenceText(column) &&
          column.every(
            (part) =>
              part.fontName === first.fontName &&
              part.height === first.height &&
              part.transform[4] + part.width <= (right ? page.width : page.width / 2)
          ) &&
          column.filter((author, index) => {
            const tail = column[index + 1]
            if (!tail || !author.hasEOL || !onLead(author) || !authorYear.test(author.str))
              return false
            const pitch = author.transform[5] - tail.transform[5]
            return (
              Math.abs(tail.transform[4] - author.transform[4] - first.height) <
                first.height * 0.15 &&
              pitch > first.height &&
              pitch < first.height * 1.6 &&
              /\d+, \d+$/u.test(tail.str)
            )
          }).length >= 2
        )
      }
      if (authors.length >= 2) return nativeReferenceText(authors)
      // An accent can split the authors and year into separate native runs.
      // On the final page, repeated same-row initials and DOI wraps prove the rail.
      if (
        page !== pages.at(-1) ||
        !nativeReferenceText(column) ||
        column.some((part) => part.fontName !== first.fontName || part.height !== first.height)
      )
        return false
      const boundary = right ? page.width : page.width / 2
      if (
        nativeClosedAuthorDateRows(column, boundary) ||
        nativeSurnameInitialYearRows(column, boundary)
      )
        return true
      const splitAuthors = column.filter((part, at) => {
        if (!onLead(part) || part.hasEOL || !/^\p{Lu}[\p{L}’'-]+, (?:\p{Lu}\. ?)+/u.test(part.str))
          return false
        const [next, after] = column.slice(at + 1, at + 3)
        const accent = next && /^[´¨˚]$/u.test(next.str)
        const tail = accent ? after : next
        if (!tail?.hasEOL || tail.transform[5] !== part.transform[5]) return false
        const gap = tail.transform[4] - part.transform[4] - part.width
        return (
          tail.transform[4] > part.transform[4] &&
          gap < part.height * 0.5 &&
          gap > -part.height * (/[´¨˚]$/u.test(part.str) ? 0.6 : 0.2) &&
          (!accent ||
            (Math.abs(next.transform[5] - part.transform[5]) < part.height * 0.4 &&
              Math.abs(next.transform[4] - tail.transform[4]) < part.height * 0.4)) &&
          authorYear.test(part.str.trimEnd() + ' ' + tail.str)
        )
      })
      return (
        splitAuthors.length >= 2 &&
        column.filter(
          (part) =>
            part.fontName === first.fontName &&
            part.height === first.height &&
            Math.abs(part.transform[4] - first.transform[4] - first.height) < first.height * 0.15 &&
            /\bdoi: 10\.\d{4,9}\/\S+$/iu.test(part.str)
        ).length >= splitAuthors.length
      )
    })
  }
  const font = evidence?.complete && evidence.fonts[item.fontName!]
  return (
    /^(?:References|Bibliography)$/u.test(item.str) &&
    !!font &&
    font.nativeMetrics === true &&
    font.vertical === false &&
    item.fontVertical === false &&
    item.fontAscent === font.ascent &&
    item.fontDescent === font.descent &&
    centerOffset < item.height * 0.02
  )
}

// Column reading order can visit the first lane before its shared centered heading.
function retainNativeCenteredBibliographyLead(units: LayoutUnit[], pages: PdfLayoutPage[]): void {
  const page = pages.at(-1)
  if (!page || page.rotation !== 0) return
  const heading = units.find(
    (unit) =>
      unit.sourceOnly &&
      unit.preserve === 'reference' &&
      unit.source === 'REFERENCES' &&
      unit.fragments[0]?.page === page.page &&
      nativeCenteredReferenceHeading(unit, units, pages)
  )
  if (!heading) return

  const [title] = nativeReferenceItems(heading, pages)
  const headingIndex = page.items.indexOf(title)
  const middle = page.width / 2
  const entries = page.items.flatMap((item, index) =>
    index > headingIndex && item.str.trim() ? [[`${page.page}:${index}`, item] as const] : []
  )
  const split = entries.findIndex(([, item]) => item.transform[4] > middle)
  if (split < 1) return
  const left = entries.slice(0, split).map(([, item]) => item)
  const right = entries.slice(split).map(([, item]) => item)
  const first = left[0]
  if (
    title.transform[5] - first.transform[5] < first.height ||
    Math.abs(first.transform[5] - right[0].transform[5]) > first.height * 0.05 ||
    !nativeReferenceText(left) ||
    left.some((item) => item.fontName !== first.fontName || item.height !== first.height) ||
    (!nativeClosedAuthorDateRows(left, middle) &&
      !nativeSurnameInitialYearRows(left, middle) &&
      !nativeClosedAuthorDateRows(
        left,
        middle,
        /\b(?:19|20)\d{2}[a-z]?, [A-Z][A-Za-z.& ]{1,15}, \d{1,5}, [A-Z]?\d{1,8}$/u
      )) ||
    right.some((item) => item.transform[4] <= middle)
  )
    return

  const bibliography = new Map<string, PdfLayoutTextItem>(entries)
  const leftKeys = new Set<string>(entries.slice(0, split).map(([key]) => key))
  const owners = units.filter((unit) => unit.items.some((key) => bibliography.has(key)))
  const seen = new Set<string>()
  for (const owner of owners) {
    const isLeft = leftKeys.has(owner.items[0])
    if (
      owner.figure ||
      owner.referenceBoundary ||
      owner.fragments.length !== 1 ||
      owner.fragments[0].page !== page.page ||
      (!isLeft && (!owner.sourceOnly || owner.preserve !== 'reference')) ||
      (isLeft && owner.preserve && owner.preserve !== 'reference')
    )
      return
    for (const [index, key] of owner.items.entries()) {
      const item = bibliography.get(key)
      if (
        !item ||
        seen.has(key) ||
        leftKeys.has(key) !== isLeft ||
        item.str !== owner.originalStrings[index]
      )
        return
      seen.add(key)
    }
  }
  if (seen.size !== bibliography.size) return
  for (const owner of owners)
    if (leftKeys.has(owner.items[0]))
      Object.assign(owner, { sourceOnly: true, preserve: 'reference' })
}

// A centered bibliography heading can follow the first left citation in
// extracted column order. Confirm the native heading and its matching right lane.
function retainLeadingReferenceAtColumnTurn(units: LayoutUnit[], pages: PdfLayoutPage[]): void {
  const author = /^\p{L}[\p{L}\p{M} .’'´ˇ-]+, (?:\p{Lu}\. ?){1,3}/u
  const journal = /^[\p{L}.& ]+, \d{1,5}, [A-Z]?\d{1,9}$/u
  for (const [index, heading] of units.entries()) {
    if (
      heading.source !== 'REFERENCES' ||
      !heading.sourceOnly ||
      heading.preserve !== 'reference' ||
      heading.items.length !== 1 ||
      heading.fragments.length !== 1
    )
      continue
    const n = heading.fragments[0].page,
      page = pages[n - 1],
      lead = units[index - 1],
      [right, tail] = units.slice(index + 1, index + 3)
    if (
      !page ||
      page.rotation !== 0 ||
      page.page !== n ||
      !lead ||
      lead.sourceOnly ||
      lead.preserve ||
      lead.referenceBoundary ||
      lead.figure ||
      !author.test(lead.source) ||
      !journal.test(lead.source.split(/ (?:19|20)\d{2}, /u)[1] ?? '') ||
      !right?.sourceOnly ||
      right.preserve !== 'reference' ||
      !author.test(right.source) ||
      !/ (?:19|20)\d{2},$/u.test(right.source) ||
      !tail?.sourceOnly ||
      tail.preserve !== 'reference' ||
      !journal.test(tail.source) ||
      [lead, right, tail].some(
        (unit) => unit.fragments.length !== 1 || unit.fragments[0].page !== n
      )
    )
      continue
    const [title] = nativeReferenceItems(heading, pages),
      leftRow = nativeReferenceItems(lead, pages),
      [firstRight] = nativeReferenceItems(right, pages),
      [rightTail] = nativeReferenceItems(tail, pages)
    if (
      leftRow.length < 2 ||
      !nativeReferenceText(leftRow) ||
      ![title, firstRight, rightTail].every(nativeHorizontalSourceItem) ||
      right.items.length !== 1 ||
      tail.items.length !== 1
    )
      continue
    const [left] = leftRow,
      em = left.height,
      middle = page.width / 2,
      titleIndex = page.items.indexOf(title),
      leftIndex = page.items.indexOf(left),
      x = firstRight.transform[4],
      y = left.transform[5]
    if (
      Math.abs(title.transform[4] + title.width / 2 - middle) > em * 0.08 ||
      title.height < em * 1.07 ||
      title.fontName === left.fontName ||
      title.transform[5] - y < em * 1.3 ||
      title.transform[5] - y > em * 2.6 ||
      x <= middle ||
      Math.abs(firstRight.transform[5] - y) > em * 0.04 ||
      Math.abs(rightTail.transform[4] - x - em) > em * 0.15 ||
      firstRight.transform[5] - rightTail.transform[5] < em ||
      firstRight.transform[5] - rightTail.transform[5] > em * 2.2 ||
      [firstRight, rightTail, ...leftRow].some(
        (row) => row.fontName !== left.fontName || Math.abs(row.height - em) > em * 0.02
      ) ||
      leftRow.some(
        (row, offset) =>
          Math.abs(row.transform[5] - y) > em * 0.04 ||
          row.transform[4] + row.width >= middle ||
          page.items.indexOf(row) !== leftIndex + offset
      ) ||
      titleIndex < 0 ||
      titleIndex >= leftIndex ||
      page.items.slice(titleIndex + 1, leftIndex).some((row) => row.str.trim()) ||
      page.items.indexOf(firstRight) <= leftIndex + leftRow.length - 1 ||
      page.items[page.items.indexOf(firstRight) + 1] !== rightTail
    )
      continue
    Object.assign(lead, { sourceOnly: true, preserve: 'reference' })
  }
}

// Some terminal bibliographies omit commas between surnames and initials.
function nativeSurnameInitialYearRows(column: PdfLayoutTextItem[], rightBoundary: number): boolean {
  const first = column[0]
  const x = first.transform[4]
  const em = first.height
  const name = String.raw`\p{Lu}[\p{L}\p{M}’'-]+ (?:\p{Lu}\. ?){1,3}`
  const authorYear = new RegExp(
    String.raw`^${name}(?:, ${name})*, (?:19|20)\d{2}[a-z]?,(?: |$)`,
    'u'
  )
  let entries = 0
  let wraps = 0
  for (const [index, item] of column.entries()) {
    const offset = item.transform[4] - x
    const pitch = index ? column[index - 1].transform[5] - item.transform[5] : em
    if (pitch < em || pitch > em * 2.2 || item.transform[4] + item.width > rightBoundary)
      return false
    const author = authorYear.test(item.str)
    if (Math.abs(offset) < em * 0.1 && author) entries++
    else if (entries && Math.abs(offset - em) < em * 0.15 && !author) wraps++
    else return false
  }
  return entries >= 3 && wraps > 0
}

// Complete DOI-terminated author-date records establish the hanging rail even
// when an author or publication year crosses a native row boundary.
function nativeClosedAuthorDateRows(
  column: PdfLayoutTextItem[],
  rightBoundary: number,
  locator = /\bdoi: 10\.\d{4,9}\/\S+$/iu
): boolean {
  const first = column[0],
    x = first.transform[4],
    em = first.height,
    rows = [...Map.groupBy(column, (item) => item.transform[5]).values()]
  if (rows.length < 6) return false
  let entries = 0,
    record = ''
  const closed = (text: string): boolean =>
    /\b(?:19|20)\d{2}[a-z]?,/u.test(text) && locator.test(text)
  for (const [n, row] of rows.entries()) {
    const [lead, tail] = row,
      offset = lead.transform[4] - x,
      pitch = n ? rows[n - 1][0].transform[5] - lead.transform[5] : em,
      text = tail ? lead.str.slice(0, -1) + tail.str : lead.str
    if (
      pitch < em ||
      pitch > em * 2.6 ||
      row.length > 2 ||
      row.some((item) => item.transform[4] + item.width > rightBoundary) ||
      (tail &&
        (lead.hasEOL ||
          !tail.hasEOL ||
          !/[´¨˚]$/u.test(lead.str) ||
          !/^\p{Ll}/u.test(tail.str) ||
          Math.abs(tail.transform[4] - lead.transform[4] - lead.width) > em * 0.55))
    )
      return false
    if (Math.abs(offset) < em * 0.1) {
      if ((entries && !closed(record)) || !/^\p{Lu}[\p{L}’'-]+, (?:\p{Lu}\. ?)+/u.test(text))
        return false
      entries++
      record = text
    } else {
      if (!entries || locator.test(record) || tail || Math.abs(offset - em) > em * 0.15)
        return false
      record += ' ' + text
    }
  }
  return entries >= 3 && closed(record)
}

// A compact terminal bibliography may share its heading's paragraph owner and
// be split in the middle of a hanging citation. Keep the native rows together.
function retainNativeTerminalCitationRows(units: LayoutUnit[], pages: PdfLayoutPage[]): void {
  const page = pages.at(-1)
  if (!page || page.rotation) return
  const native = page.items.filter((item) => item.str.trim())
  const headingIndex = native.findLastIndex((item) => item.str === 'References')
  if (headingIndex < 1) return
  const bibliography = native.slice(headingIndex)
  const [heading, first] = bibliography
  if (!first || !bibliography.every(nativeHorizontalSourceItem)) return

  const em = first.height
  const x = first.transform[4]
  if (
    heading.height <= em ||
    heading.height > em * 1.25 ||
    Math.abs(heading.transform[4] - x) > em * 0.05 ||
    heading.transform[5] - first.transform[5] < em * 1.4 ||
    heading.transform[5] - first.transform[5] > em * 1.8 ||
    native[headingIndex - 1].transform[5] - heading.transform[5] < em * 2.5
  )
    return

  const rows = [...Map.groupBy(bibliography.slice(1), (item) => item.transform[5]).values()]
  const closed = /(?:,\s*[A-Z]?\d+|:\d{4}\.\d{4,5})$/u
  const authorDate = /^\p{Lu}[\p{L}\p{M} .´˝'’–-]+, \p{Lu}[\p{L}]*\..*\b(?:19|20)\d{2}[a-z]?,/u
  let open = false
  let entries = 0
  for (const [index, row] of rows.entries()) {
    const [lead] = row
    const offset = lead.transform[4] - x
    const pitch = index ? rows[index - 1][0].transform[5] - lead.transform[5] : em
    const text = row.map((item) => item.str.trim()).join(' ')
    if (
      pitch < em ||
      pitch > em * 1.4 ||
      row.some((item) => Math.abs(item.height - em) > em * 0.01)
    )
      return
    if (Math.abs(offset) < em * 0.05) {
      if (open || !authorDate.test(text)) return
      open = !closed.test(text)
      entries++
    } else {
      if (!open || offset < em * 1.5 || offset > em * 3 || !closed.test(text)) return
      open = false
    }
  }
  if (open || entries < 6 || rows.length <= entries) return

  const firstOwner = units.findIndex(
    (unit) =>
      !unit.sourceOnly &&
      /^References /u.test(unit.source) &&
      nativeReferenceItems(unit, pages)[0] === heading
  )
  if (firstOwner < 0) return
  const owners = units.slice(firstOwner, firstOwner + 2)
  if (
    owners.length !== 2 ||
    owners.some(
      (unit) =>
        unit.sourceOnly ||
        unit.preserve ||
        unit.figure ||
        unit.referenceBoundary ||
        unit.fragments.length !== 1 ||
        unit.fragments[0].page !== page.page
    )
  )
    return
  const owned = owners
    .flatMap((unit) => nativeReferenceItems(unit, pages))
    .filter((item) => item.str.trim())
  if (
    owned.length !== bibliography.length ||
    owned.some((item, index) => item !== bibliography[index])
  )
    return
  for (const owner of owners) Object.assign(owner, { sourceOnly: true, preserve: 'reference' })
}

// Sparse-page analysis inputs have no authority to establish a complete native
// reference interval. Refuse them rather than reading an unrelated page/index.
// A final contents row may continue alone above the next page's first section.
// Prove the whole preceding contents page, its destinations and the real heading.
function nativeSingleContentsTail(
  unit: LayoutUnit,
  units: LayoutUnit[],
  pages: PdfLayoutPage[]
): boolean {
  if (unit.fragments.length !== 1 || unit.items.length !== 1 || unit.originalStrings.length !== 1)
    return false
  const page = pages[unit.fragments[0].page - 1],
    previous = pages[unit.fragments[0].page - 2]
  if (
    !page ||
    !previous ||
    page.rotation !== 0 ||
    previous.rotation !== 0 ||
    page.page !== previous.page + 1 ||
    page.width !== previous.width ||
    page.height !== previous.height
  )
    return false
  const target = nativeReferenceItems(unit, pages)[0],
    h = target?.height
  if (
    !target ||
    !nativeContentsUpright(target) ||
    target.str !== unit.source ||
    target.str !== unit.originalStrings[0] ||
    !/^(?:References|Bibliography)$/u.test(target.str)
  )
    return false
  const rowsOf = (items: PdfLayoutTextItem[]): PdfLayoutTextItem[][] => {
    const rows: PdfLayoutTextItem[][] = []
    for (const item of items) {
      const row = rows.at(-1)
      if (row && Math.abs(row[0].transform[5] - item.transform[5]) < h * 0.01) row.push(item)
      else rows.push([item])
    }
    return rows
  }
  const sameSize = (item: PdfLayoutTextItem): boolean =>
    nativeContentsUpright(item) &&
    Math.abs(item.height - h) < h * 0.01 &&
    item.fontAscent === target.fontAscent &&
    item.fontDescent === target.fontDescent
  const current = page.items.filter((i) => i.str.trim()),
    number = current[1]
  if (
    current[0] !== target ||
    !number ||
    !sameSize(number) ||
    !/^[1-9]\d{0,3}$/u.test(number.str) ||
    Math.abs(number.transform[5] - target.transform[5]) > h * 0.01 ||
    target.transform[5] < page.height * 0.85 ||
    number.transform[4] < page.width * 0.75 ||
    number.transform[4] - target.transform[4] - target.width < h * 8
  )
    return false
  const destination = Number(number.str)
  if (destination <= page.page || destination > pages.length) return false
  const before = previous.items.filter((i) => i.str.trim()),
    head = before[0],
    folio = before.at(-1)!
  if (
    !head ||
    !sameSize(head) ||
    head.fontName !== target.fontName ||
    head.str !== 'CONTENTS' ||
    !sameSize(folio) ||
    folio.str !== String(previous.page) ||
    folio.transform[5] > previous.height * 0.08 ||
    Math.abs(folio.transform[4] + folio.width / 2 - previous.width / 2) > h ||
    head.transform[5] < previous.height * 0.85
  )
    return false
  const packet = before.slice(1, -1),
    rows = rowsOf(packet)
  if (
    rows.length < 8 ||
    packet.some((i) => !sameSize(i)) ||
    rows.some(
      (r, n) =>
        n &&
        (rows[n - 1][0].transform[5] - r[0].transform[5] < h * 0.9 ||
          rows[n - 1][0].transform[5] - r[0].transform[5] > h * 4)
    )
  )
    return false
  const entries: { text: string; destination: number; textItems: PdfLayoutTextItem[] }[] = []
  const right = number.transform[4] + number.width
  for (let n = 0; n < rows.length; n++) {
    const first = rows[n]
    if (!/^[IVXLCDM]+(?:\.[A-Z0-9]+)*\. \p{Lu}/u.test(first[0].str)) return false
    const textItems = [first[0]]
    let last = first.at(-1)!
    if (first.length === 1) {
      const continuation = rows[++n]
      if (
        !continuation ||
        continuation.length !== 2 ||
        !/^[a-z][a-z ]+$/u.test(continuation[0].str) ||
        continuation[0].fontName !== first[0].fontName ||
        continuation[0].transform[4] <= first[0].transform[4] + h * 0.5
      )
        return false
      textItems.push(continuation[0])
      last = continuation[1]
    } else if (first.length !== 2) return false
    if (
      !/^[1-9]\d{0,3}$/u.test(last.str) ||
      last.fontName !== number.fontName ||
      textItems.some((i) => i.fontName !== target.fontName && i.fontName !== number.fontName) ||
      Math.abs(last.transform[4] + last.width - right) > h * 0.05 ||
      last.transform[4] - textItems.at(-1)!.transform[4] - textItems.at(-1)!.width < h * 0.3 ||
      Number(last.str) > pages.length ||
      Number(last.str) < page.page ||
      (entries.length && Number(last.str) < entries.at(-1)!.destination)
    )
      return false
    entries.push({
      text: textItems.map((i) => i.str).join(' '),
      destination: Number(last.str),
      textItems
    })
  }
  if (
    entries.at(-1)!.destination > destination ||
    packet.at(-1)!.transform[5] > previous.height * 0.12
  )
    return false
  const owned = (p: PdfLayoutPage, items: PdfLayoutTextItem[]): boolean => {
    const keys = new Set(items.map((i) => p.page + ':' + p.items.indexOf(i))),
      owners = units.filter((u) => u.items.some((k) => keys.has(k)))
    return (
      owners.length > 0 &&
      owners.every(
        (u) =>
          u.items.every((k) => keys.has(k)) &&
          nativeReferenceItems(u, pages).length === u.items.length
      ) &&
      owners.flatMap((u) => u.items).length === keys.size &&
      [...keys].every((k) => units.filter((u) => u.items.includes(k)).length === 1)
    )
  }
  if (!owned(previous, before) || !owned(page, [target, number])) return false
  const clear = (p: PdfLayoutPage, items: PdfLayoutTextItem[]): boolean => {
    const domain = nativeProseProofDomain(items)
    return (
      !!domain &&
      domain.x >= 0 &&
      domain.y >= 0 &&
      domain.right <= p.width &&
      domain.bottom <= p.height &&
      !p.items.some((i) => !items.includes(i) && nativeTextOverlapsProof(i, domain))
    )
  }
  if (!clear(previous, [head, ...packet]) || !clear(page, [target, number])) return false
  const matches = (text: string, p: number): LayoutUnit[] =>
    units.filter(
      (u) =>
        u.fragments.every((f) => f.page === p) &&
        u.originalStrings.join(' ').toUpperCase() === text.toUpperCase() &&
        nativeReferenceItems(u, pages).every(
          (i) => sameSize(i) && i.fontName === target.fontName
        ) &&
        nativeReferenceItems(u, pages).length === u.items.length &&
        clear(pages[p - 1], nativeReferenceItems(u, pages))
    )
  const main = entries.filter((e) => /^[IVXLCDM]+\. /u.test(e.text)),
    anchors = main.filter((e) => matches(e.text, e.destination).length === 1)
  if (
    main.length < 3 ||
    main[0].destination !== page.page ||
    matches(main[0].text, page.page).length !== 1 ||
    new Set(anchors.map((e) => e.destination)).size < 3 ||
    matches(target.str, destination).length !== 1
  )
    return false
  if (
    pages[destination - 1].items.filter(
      (i) =>
        i.str.toUpperCase() === target.str.toUpperCase() &&
        sameSize(i) &&
        i.fontName === target.fontName
    ).length !== 1
  )
    return false
  return true
}
